(window.GIM_TS=window.GIM_TS||{})["Pesachim.6"]={"from":144,"a":[["\u0003כיצד צולין את\u0004 קרבן \u0003הפסח? מביאין שפוד של\u0004 עץ \u0003רמון, ותוחבו לתוך פיו\u0004 של הקרבן \u0003עד בית נקובתו\u0004 (פי הטבעת), \u0003ונותן את כרעיו ואת בני מעיו לתוכו,\u0004 וצולה הכל יחד, אלו \u0003דברי ר' יוסי הגלילי. ר' עקיבא אומר:\u0004 אין מכניסים מעיו וכרעיו לתוכו, כי \u0003כמין בישול הוא זה,\u0004 שכל המצוי בתוך הקרבן אינו נצלה מן האש במישרין, והרי זה דומה לבישול, \u0003אלא תולין\u0004 אותם באמצעות שפוד למעלה מפיו \u0003חוצה לו. אין צולין את הפסח לא על השפוד\u0004 של מתכת \u0003ולא על האסכלא\u0004 (כלי מתכת המיועד לצליה), אבל \u0003אמר ר' צדוק: מעשה ברבן גמליאל שאמר לטבי עבדו: צא וצלה לנו את הפסח על האסכלא.\u0004","שואלים: \u0003וניתי\u0004 \u0005[ושיביאו]\u0006 באמת שפוד של \u0003מתכת!\u0004 ומשיבים: משום שכלי מתכת \u0003איידי\u0004 \u0005[מתוך]\u0006 שהוא \u0003חם מקצתו חם כולו, וקמטוי\u0004 \u0005[ו\u0006נמצא ש\u0005נצלה]\u0006 הבשר \u0003מחמת\u0004 חום \u0003השפוד, ורחמנא\u0004 \u0005[והכתוב]\u0006 \u0003אמר \"צלי אש\"\u0004 דוקא \u0003ולא צלי מחמת דבר אחר.\u0004 ושואלים: מדוע מביאים שפוד של רימון דוקא? \u0003וניתי\u0004 \u0005[ונביא]\u0006 שפוד \u0003של דקל!\u0004 ומשיבים: \u0003איידי דאית ליה שיבי, מפיק מיא\u0004 \u0005[מתוך שיש לו סדקים\u0006 בתוך הענף בין העלים, \u0005מוציא\u0006 מעט \u0005מים]\u0006 מתוכו אגב הצליה, \u0003ו\u0004בשר הפסח הנוגע בשפוד \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003כמבושל.\u0004 ושואלים: \u0003וניתי\u0004 \u0005[ונביא]\u0006 שפוד \u0003של תאנה?\u0004 ומשיבים: \u0003איידי דמחלחל, מפיק מיא\u0004 \u0005[מתוך ש\u0006הוא \u0005חלול\u0006 ויש לו מוח מבפנים, \u0005מוציא מים]\u0006 \u0003והוה ליה\u0004 \u0005[והרי הוא]\u0006 \u0003כמבושל.\u0004","ושואלים: \u0003וניתי\u0004 \u0005[ונביא]\u0006 \u0003של אלון,\u0004 או \u0003של חרוב,\u0004 או \u0003של שקמה\u0004 שהם קשים ואין בהם מוח? ועונים: כל אחד מאלה, \u0003איידי דאית ביה קיטרי, מפיק מיא\u0004 \u0005[מתוך שיש בו קשרים, מוציא מים].\u0006 שהן אותן הבליטות שבענף ומקומות ההסתעפות שבענפים, וכיון שצריך לחתוך ולישר את הענף, יוצאים בשעת הצלייה מים ממקום החיתוך, והרי הוא כמבושל.","ומקשים: \u0003של רמון נמי אית ביה קיטרי\u0004 \u0005[גם כן יש בו קשרים]?\u0006 ומשיבים: \u0003שיעי קיטרי\u0004 \u0005[חלקים קשריו]\u0006 ואין צורך לישרם בסכין כדי להשתמש בענף, וממילא אין המים יוצאים משם. \u0003ואיבעית אימא: בנבגא בר שתא, דלית ביה קיטרי\u0004 \u0005[ואם תרצה\u0006 אמור ש\u0005מדובר בענף בן שנתו, ש\u0006עדיין \u0005אין בו קשרים]\u0006 שלא נסתעף עדיין. ושואלים: \u0003והא איכא בי פסקיה\u0004 \u0005[והרי יש\u0006 בו \u0005בית\u0006 מקום \u0005החיתוך]\u0006 מן העץ שמשם יוצאים המים! ומשיבים: \u0003דמפיק לבי פסקיה לבר\u0004 \u0005[שמוציא את מקום חיתוכו לחוץ]\u0006 ואינו מכניס אותו בתוך הגדי.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: כשם ששפוד של עץ אינו נשרף\u0004 אף על פי שהוא על האש, \u0003כך שפוד של מתכת אינו מרתיח,\u0004 ואין לחשוש שייצלה הבשר מחמתו. \u0003אמרו לו\u0004 חכמים: אין הדבר כן, \u0003זה\u0004 המתכת, כשהוא \u0003חם מקצתו — חם כולו. וזה\u0004 העץ, כאשר הוא \u0003חם מקצתו — אינו חם כולו,\u0004 ולכן מקום חיתוכו שאינו מונח בתוך האש אינו פולט מים.","שנינו במשנה: \u0003ונותן את כרעיו\u0004 ובני מעיו בתוך הקרבן, לשיטת ר' יוסי הגלילי. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' ישמעאל\u0004 היה \u0003קוריהו\u0004 לגדי זה \u0003\"תוך תוך\",\u0004 משום שכאשר נותן את הכרעיים והמעיים בתוכו הם משמיעים קול כעין 'תוך תוך' כשאר דברים מבושלים. \u0003ר' טרפון קוריהו \"גדי מקולס\",\u0004 כלומר גדי שכובע בראשו, כי לדעתו יש לצלות את המעיים כשהם על ראש הגדי.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו גדי מקולס\u0004 ש\u0003אסור לאכול בלילי פסח בזמן הזה\u0004 שלא יראה כמקריב קרבן בחוץ — \u0003כל שצלאו כולו כאחד\u0004 כצורת צליית הפסח! ואולם אם \u0003נחתך ממנו אבר\u0004 או \u0003נשלק\u0004 (בושל) \u0003ממנו אבר\u0004 לחוד — \u0003אין זה\u0004 עוד \u0003גדי מקולס.\u0004","על לשון ברייתא זו תוהים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003יש לומר\u0004 שכאשר \u0003נחתך ממנו אבר, דאף על גב\u0004 \u0005[שאף על פי]\u0006 \u0003דקא מטוי ליה בהדיה\u0004 \u0005[שצולה אותו יחד עמו]\u0006 \u0003אמרת לא,\u0004 ששוב אין דינו כמקולס, \u0003נשלק\u0004 אבר ממנו \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]!?\u0006 \u0003אמר רב ששת:\u0004 כאן מדובר \u0003ששלקו\u0004 את האבר הזה \u0003במחובר\u0004 לגדי, ואם כן יש חידוש בדבר שאף שהגדי שלם, כיון שנשלק אחד מאיבריו שוב אינו כמקולס, בין שחותכו בין ששולקו במחובר.","\u0003אמר רבה: האי מולייתא\u0004 \u0005[מילוי זה]\u0006 של גדי או תרנגולת בבשר — \u0003שריא\u0004 \u0005[מותר],\u0006 ואפילו עשה זאת לפני שמלח את הבשר הממולא כל צרכו להוציא ממנו את הדם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא קא בלע דמא\u0004 \u0005[והלא\u0006 בשר הגדי \u0005בולע דם]\u0006 מבשר המילוי שבתוכו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כבולעה,\u0004 כפי שהוא בולע מן הדם, \u0003כך פולטה\u0004 בחזרה את הדם. שהחום גורם שייפלט הדם, וייצלה בחום האש.","ומציעים: \u0003נימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 ממשנתנו, שאמרנו: \u0003נותן את כרעיו ואת בני מעיו לתוכו\u0004 של קרבן הפסח וצולה אותם כאחת. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שמותר לעשות כן — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 \u0003כבולעו כך פולטו?\u0004 ואם כן הרי זו ראיה לשיטת רבה. שאף שנחלקו אם מותר לעשות זאת בפסח בגלל דינים המיוחדים לו, נראה שהכל מודים שאין בכך חשש מאיסור דם. ודוחים: \u0003אמרי\u0004 \u0005[אומרים],\u0006 \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בפסח מבמילוי, \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003בית השחיטה דמחלחל\u0004 \u0005[ש\u0006הוא \u0005חלול]\u0006 ופתוח,"],["\u0003מידב דייבי\u0004 \u0005[זב]\u0006 החוצה. אבל במולייתא רגילה שסתומה מכל צד, אין מקום לדם לצאת.","ומעירים עוד: \u0003נימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 ממה ששנינו: \u0003הלב\u0004 של בעלי חיים \u0003קורעו ומוציא את דמו\u0004 לפני שצולה אותו או שמבשלו. \u0003לא קרעו — קורעו לאחר בישולו\u0004 (צלייתו), \u0003ומותר.\u0004 ויש לשאול: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שמותר הלב על אף שלכאורה יש עדיין דם בתוכו? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 \u0003כבולעו כך פולטו?\u0004 ולכן תוך כדי צלייה הדם נבלע בתוכו וגם נפלט בחזרה החוצה, ולא נשאר בתוך הבשר כל דם אסור, ומה שישנו בתוך חלל הלב אפשר לחתוך ולהוציא, ולכאורה הרי הוא כרבה.","ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 הוא \u0003לב, דשיע\u0004 \u0005[ש\u0006הוא \u0005חלק]\u0006 ואינו בולע כל כך, אבל בכלל אין לומר שכבולעו כך פולטו.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבין סבא\u0004 \u0005[הזקן],\u0006 \u0003טפליה ההיא בר גוזלא\u0004 \u0005[טפל,\u0006 מרח בבצק, \u0005גוזל אחד]\u0006 \u0003לרב,\u0004 \u0005וצלאו.\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003אי מעלי טפליה\u0004 \u0005[אם מעולה,\u0006 טעימה היא \u0005הטפילה,\u0006 הבצק שעל הבשר\u0005]\u0006, \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי\u0004 ממנו \u0003ואיכול\u0004 \u0005[ואוכל].\u0006 הרי שאף שאותה טפילה בלעה מן הדם, אומרים שודאי גם נפלט ממנה הדם תוך כדי צלייה! ודוחים: \u0003ההיא בסמידא דמפריר\u0004 \u0005[\u0006ב\u0005אותו\u0006 ענין מדובר \u0005בסולת ש\u0006היא \u0005פריכה]\u0006 והדם שותת ויוצא דרך בצק זה.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא איקלע לבי ריש גלותא, וטפלו ליה בר אווזא\u0004 \u0005[הזדמן לבית ראש הגולה, וטפלו לו ברווז\u0006 בבצק\u0005]\u0006 \u0003אמר: אי\u0004 \u0005[אם]\u0006 \u0003לא דחזיתיה דזיג כזוזא חיורא\u0004 \u0005[שראיתי\u0006 את הבצק \u0005ש\u0006הוא \u0005צלול כדינר לבן,\u0006 חדש\u0005],\u0006 \u0003לא\u0004 הייתי \u0003אכלי מיניה\u0004 \u0005[אוכל ממנו]\u0006 שמא בלע מן הדם. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לקבל את הכלל ש\u0003\"כבולעו כך פולטו\" — מאי איריא כי זיג\u0004 \u0005[מה שייך,\u0006 מדוע דוקא, \u0005כאשר היה צלול\u0006 ובהיר\u0005]?\u0006 \u0003אפילו כי\u0004 \u0005[כאשר]\u0006 \u0003לא זיג, נמי\u0004 \u0005[צלול, גם כן]\u0006 יהא מותר! ומשיבים: \u0003התם בחיורתא דשריר\u0004 \u0005[שם\u0006 מדובר \u0005ב\u0006קמח \u0005לבן, ש\u0006אינו סולת, \u0005ש\u0006הוא \u0005מוצק]\u0006 והדם אינו יוצא מתוכו כלל, ולכך אכלו רק לאחר שציבעו הוכיח עליו שאין בו דם.","את הבעיה הזו מסכמים: \u0003והילכתא\u0004 \u0005[והלכה\u0006 היא\u0005]\u0006 אם עושה את הטפילה, הכיסוי בבצק, \u0003דסמידא\u0004 \u0005[\u0006בבצק \u0005של סולת],\u0006 \u0003בין אסמיק\u0004 \u0005[האדימה]\u0006 מחמת הדם \u0003בין לא אסמיק\u0004 \u0005[האדימה] —\u0006 \u0003שריא\u0004 \u0005[מותרת].\u0006 \u0003דחיורתא\u0004 \u0005[ב\u0006קמח \u0005לבן],\u0006 \u0003אי זיג כזוזא חיורא\u0004 \u0005[אם צלול כמטבע לבן] —\u0006 \u0003שריא\u0004 \u0005[מותר],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003אסיר\u0004 \u0005[אסור].\u0006 ובצק של \u0003שאר קמחים\u0004 שאינם קשים ולא פריכים ביותר, אם \u0003אסמיק\u0004 \u0005[האדים] —\u0006 \u0003אסור, ו\u0004אם \u0003לא אסמיק — שרי\u0004 \u0005[מותר].\u0006","\u0003האי מולייתא\u0004 \u0005[אותו\u0006 בעל חיים \u0005ממולא\u0006 בשר\u0005],\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אסר, אפילו\u0004 היה \u0003פומא\u0004 \u0005[הפה\u0006 הצד הפתוח\u0005],\u0006 נמצא \u0003לתחת,\u0004 למטה, שהדם שותת ויורד — אסור. \u0003ומאן דשרי\u0004 \u0005[ומי שהתיר],\u0006 מתיר \u0003אפילו פומא לעיל\u0004 \u0005[הפה מלמעלה]\u0006 ותלויה בתנור. ומסכמים: \u0003והילכתא\u0004 \u0005[והלכה]\u0006 \u0003מולייתא שרי\u0004 \u0005[המילוי מותר],\u0006 \u0003אפילו\u0004 היה \u0003פומא לעיל\u0004 \u0005[הפה למעלה]\u0006 כשיטת המתיר.","ועוד בנושא זה של דם בלוע באיברים והכשרת בשר לאכילה. בנושא זה דנו בשלושה מקרים, ב \u0003אומצא\u0004 (בשר הנאכל בלא מליחה), \u0003ביעי\u0004 \u0005[ביצי\u0006 זכר בהמה וחיה\u0005],\u0006 \u0003ומיזרקי\u0004 \u0005[וורידים\u0006 גדולים\u0005].\u0006 \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אחא ורבינא,\u0004 ומעירים: \u0003בכל התורה כולה\u0004 כשיש מחלוקת ביניהם סתם, ואין מפורטת שיטתו של כל אחד מהם, דע כי שיטת \u0003רב אחא לחומרא\u0004 \u0005[להחמיר]\u0006 \u0003ו\u0004שיטת \u0003רבינא לקולא\u0004 \u0005[להקל],\u0006 \u0003והילכתא\u0004 \u0005[והלכה]\u0006 \u0003כרבינא לקולא\u0004 \u0005[להקל]\u0006 בכל מחלוקותיהם. \u0003לבר מהני תלת\u0004 \u0005[חוץ משלוש\u0006 מחלוקות \u0005אלו]\u0006 שבהן דעת \u0003רב אחא לקולא\u0004 \u0005[להקל]\u0006 \u0003ו\u0004דעת \u0003רבינא לחומרא\u0004 \u0005[להחמיר],\u0006 \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כרב אחא לקולא\u0004 \u0005[להקל].\u0006","ומפרטים: \u0003האי אומצא דאסמיק\u0004 \u0005[\u0006חתיכת \u0005בשר שהאדימה]\u0006 מחמת דם שבה, \u0003חתכיה ומלחיה\u0004 \u0005[\u0006אם \u0005חתך אותה ומלח אותה]\u0006 כראוי — \u0003אפילו\u0004 בבישול \u0003לקדרה שרי\u0004 \u0005[מותר],\u0006 משום שברור לנו כי המלח מוציא את הדם מן הבשר. \u0003שפדיה בשפודא\u0004 \u0005[אם שיפדה על\u0006 גבי \u0005שפוד]\u0006 לצלותה — \u0003שרי\u0004 \u0005[מותר],\u0006 משום שהדם \u0003מידב דייב\u0004 \u0005[זב\u0006 ושותת\u0005].\u0006 אם \u0003אחתיה אגומרי\u0004 \u0005[הניחה על גחלים]\u0006 — בכך \u0003פליגי בה\u0004 \u0005[נחלקו בו]\u0006 \u0003רב אחא ורבינא. חד\u0004 \u0005[אחד]\u0006 \u0003אסר וחד שרי\u0004 \u0005[ואחד התיר].\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אסר,\u0004 סבר כי \u0003מצמית צמית\u0004 \u0005[\u0006הגחלים \u0005צומתות,\u0006 מקשות\u0005]\u0006 את הבשר ונמצא כל הדם שמור בתוכו. \u0003ומאן דשרי\u0004 \u0005[ומי שהתיר],\u0006 סבר שחום הגחלים \u0003מישאב שאיב\u0004 \u0005[שואב]\u0006 את הדם החוצה, והוא יוצא כולו. \u0003והלכתא: מישאב שאיב\u0004 \u0005[והלכה\u0006 היא שאנו אומרים שהגחלים \u0005שואבות\u0006 את הדם החוצה\u0005],\u0006 ומותר.","\u0003וכן ביעי\u0004 \u0005[ביצי\u0006 הזכר\u0005]\u0006 \u0003חתכינהו ומלחינהו\u0004 \u0005[\u0006אם \u0005חתכן ומלחן],\u0006 \u0003אפילו\u0004 לבישול \u0003לקדרה שריין\u0004 \u0005[מותרות].\u0006 \u0003תלינהו בשפודא — שריין, מידב דייב\u0004 \u0005[\u0006אם \u0005תלה אותם על שפוד\u0006 לצלות \u0005מותרות\u0006 משום שהדם \u0005זב].\u0006 אם \u0003אחתינהו אגומרי\u0004 \u0005[הניחן על גחלים]\u0006 \u0003פליגי ביה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אחא ורבינא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אסר וחד שרי\u0004 \u0005[ואחד\u0006 \u0005התיר].\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אסר\u0004 סבר: \u0003מצמית צמית\u0004 \u0005[צומתו,\u0006 מקשהו\u0005]\u0006 \u0003ומאן דשרי\u0004 \u0005[ומי שהתיר]\u0006 סבר: כי \u0003מישאב שאיב\u0004 \u0005[שואב\u0006 הוא\u0005].\u0006","\u0003וכן מיזרקי\u0004 (ורידים גדולים) \u0003חתכיה ומלחיה\u0004 \u0005[חתכו ומלחו\u0006 לוריד זה\u0005] —\u0006 \u0003אפילו לקדרה שרי\u0004 — \u0005[מותר],\u0006 אם \u0003תלייה בשפודא\u0004 \u0005[תלאו בשפוד]\u0006 והיה \u0003בית השחיטה\u0004 (מקום החיתוך) \u0003לתתאי שרי\u0004 — \u0005[מותר],\u0006 כי \u0003מידב דאיב\u0004 \u0005[שותת\u0006 הדם\u0005].\u0006 \u0003אחתיה אגומרי\u0004 \u0005[הניחו על גחלים]\u0006 \u0003— פליגי\u0004 \u0005[נחלקו]\u0006 בדבר \u0003רב אחא ורבינא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אסר וחד שרי\u0004 \u0005[ואחד התיר].\u0006 ומסבירים: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אסר —\u0004 סבר שהוא \u0003מצמית צמית\u0004 \u0005[מקשה]\u0006 את הבשר. \u0003ומאן דשרי\u0004 \u0005[ומי שהתיר] —\u0006 סבר שהוא \u0003מישאב שאיב\u0004 \u0005[שואב]\u0006 את הדם. \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא: גחלים \u0003מישאב שאיב\u0004 \u0005[שואבות\u0006 את הדם\u0005],\u0006 ומותר.","ועוד בדיני דם שהיה בבשר. שהיו נוהגים לשרות בשר חי (תוספות) בתוך חומץ כדי שלא ייפלט מן הדם החוצה, וממילא לא יאסר הבשר כלל, שכל שעדיין לא פרש הדם — אינו אסור. \u0003האי אומצא דאסמיק חלייה\u0004 \u0005[חתיכת בשר זו\u0006 שהכניסוה בחומץ \u0005והאדים חומץ שלו]\u0006 מחמת הדם שנבלע בו — \u0003אסור\u0004 הכל. \u0003לא אסמיק חלייה\u0004 \u0005[לא האדים החומץ שלו] —\u0006 \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003רבינא אמר: אפילו\u0004 אם \u0003לא אסמיק נמי חלייה\u0004 \u0005[האדים גם כן החומץ שלו]\u0006 — \u0003אסור,\u0004 משום ש\u0003אי אפשר דלית בה שורייקי דמא\u0004 \u0005[שלא יהיה בו חוטי דם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר בר אמימר לרב אשי: אבא\u0004 (אמימר) \u0003מגמע ליה גמועי\u0004 \u0005[היה גומע אותו\u0006 את החומץ\u0005]\u0006 ולא היה חושש לדם שיש בו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003רב אשי גופיה מגמע ליה גמועי\u0004 \u0005[עצמו היה גומע אותו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר בר אמימר לרב אשי: אבא\u0004 (אמימר), \u0003האי חלא דחליט ביה חדא זימנא\u0004 \u0005[חומץ זה שהיה שם בו\u0006 אומצה \u0005פעם אחת]\u0006 כדי להחזיק את דמה בתוכה, \u0003תו\u0004 \u0005[שוב]\u0006 \u0003לא תאני חליט ביה\u0004 \u0005[היה נותן בו שנית],\u0006 ששוב אין בו את הכוח הראוי להחזיק את הדם בתוכו. ושואלים: \u0003מאי שנא מחלא מתמהא דחלטינן ביה\u0004 \u0005[מה שונה\u0006 זה שהשתמש בו כבר \u0005מחומץ החלש שאנו חולטים בו\u0006 את הבשר\u0005]\u0006 ואין אנו חוששים שמא לא יוכל להחזיק את הדם באומצה? ומשיבים: יש לחלק, \u0003התם\u0004 \u0005[שם] —\u0006 \u0003איתיה\u0004 \u0005[יש]\u0006"],["\u0003לקיוהא דפירא בעיניה\u0004 \u0005[לחריפות הפרי\u0006 שבחומץ \u0005בעינה]\u0006 ואף שאינו חומץ חריף מכל מקום חריפותו לא פגה. \u0003הכא\u0004 \u0005[כאן] —\u0006 \u0003ליתא לקיוהא דפירא בעיניה\u0004 \u0005[אין חריפות הפרי בעינה]\u0006 שכבר בטלה בתוך הבשר ואין בכוחה להחזיק את הדם בתוכו.","שנינו ש \u0003אין צולין את הפסח\u0004 על האסכלא. ומיד הובא מעשה ברבן גמליאל שהורה לעבדו לצלות לו את הפסח על האסכלא. ותוהים: \u0003מעשה לסתור?!\u0004 וכי מביאים מיד מעשה באותה משנה כדי לסתור את ההלכה הקודמת? ומשיבים: \u0003חסורי מיחסרא, והכי קתני\u0004 \u0005[חסרה\u0006 המשנה, \u0005וכך יש לשנותה]:\u0006 \u0003ואם אסכלא מנוקבת\u0004 היא, שדרך האש להגיע לכל מקום ואין הפסח נצלה בחום האסכלה עצמה — \u0003מותר,\u0004 ועל כך \u0003אמר ר' צדוק, מעשה ברבן גמליאל שאמר לטבי עבדו: צא וצלה לנו את הפסח על האסכלא מנוקבת.\u0004","אגב הדיון בצליית הפסח מביאים: \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב חיננא בר אידי מרב אדא בר אהבה: תנור שהסיקו בקליפי\u0004 \u0005[קליפות]\u0006 של פירות \u0003ערלה\u0004 ופירות אלה אסורים, בהנאה, ולאחר שהתלהט התנור מחום העצים \u0003גרפו\u0004 הוציא מתוכו את העצים והאפר \u0003ואפה בו את הפת, לדברי האוסר\u0004 בפת שנאפתה בחום עצי ערלה, פת זו שנאפתה רק לאחר שהוציא העצים מהחום שנקלט בתנור, \u0003מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הפת מותרת.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חיננא: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב חיננא סבא\u0004 \u0005[הזקן]\u0006 \u0003אמר ר' אסי אמר ר' יוחנן: תנור שהסיקו וגרפו\u0004 ואחר כך \u0003צלה בו את הפסח — אין זה צלי אש\u0004 שציוותה עליו התורה, \u0003שנאמר\u0004 בתורה \"ואכלו את הבשר בלילה הזה \u0003צלי אש\u0004 ומצות על מרורים יאכלוהו אל תאכלו ממנו נא ובשל מבושל במים כי אם \u0003צלי אש\u0004 ראשו על כרעיו ועל קרבו\" (שמות יב, ח-ט), שכיון שנאמר \"צלי אש\" \u0003שתי פעמים\u0004 הרי זו הדגשה שהפסח צריך להצלות באש ממש.","ומכאן נדייק: \u0003טעמא\u0004 \u0005[הטעם\u0006 דוקא\u0005]\u0006 \u0003דגלי רחמנא\u0004 \u0005[שגלתה התורה]\u0006 לענין פסח על ידי החזרה \u0003\"צלי אש\" \"צלי אש\" שתי פעמים, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא גלי רחמנא\u0004 \u0005[גילה הכתוב]\u0006 בהדגשה מיוחדת, \u0003הוי אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003צלי אש הוא.\u0004 ואם כן, בשאר מקרים כאשר דבר נצלה בתנור אפילו אינו נצלה ישירות מחומה של האש, דינו כאילו נצלה על ידי העצים — ואסור!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 : \u0003גלי רחמנא התם, וילפינן מינה\u0004 \u0005[גילה הכתוב שם, ולומדים אנו ממנה]\u0006 שאותו דין בקרבן הפסח יהא כבנין אב ומקור לכל התורה כולה. שרק דבר שנצלה באש ממש הוא הקרוי צלי אש.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ותרץ באופן אחר: \u0003התם טעמא\u0004 \u0005[שם הטעם]\u0006 דווקא משום ש\u0003כתב רחמנא\u0004 \u0005[הכתוב]\u0006 \u0003\"צלי אש\" שתי פעמים, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא כתב רחמנא\u0004 \u0005[הכתוב]\u0006 \u0003\"צלי אש\" שתי פעמים, הוה אמינא: אאש קפיד רחמנא\u0004 \u0005[הייתי אומר: על האש הקפיד הכתוב]\u0006 שיהא מקור החום בתנור מחמת אש, \u0003ואפילו גרפו נמי\u0004 \u0005[גם כן] —\u0006 עדיין \u0003צלי אש הוא.\u0004 ולכן היה צורך לחזור פעמיים על המילים \"צלי אש\", \u0003אבל הכא\u0004 \u0005[כאן],\u0006 \u0003אעצים דאיסורא קא קפיד רחמנא, והא ליתנהו\u0004 \u0005[על עצי האיסור הקפיד הכתוב, והרי אינם]\u0006 ואין איפוא מקום לאסור.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חתכו\u0004 חתכים לא עמוקים בכמה מקומות בקרבן הפסח, \u0003ונתנו על גבי גחלים. רבי אומר: אומר אני שזה צלי אש,\u0004 שגחלים דינן כאש גמורה. \u0003רמי ליה\u0004 \u0005[השליך לו,\u0006 הראה סתירה\u0005]\u0006 \u0003רב אחדבוי בר אמי לרב חסדא: מי\u0004 \u0005[האם]\u0006 \u0003אמר רבי גחלים אש נינהו\u0004 \u0005[הן]?\u0006","\u0003ורמינהו\u0004 \u0005[משליכים\u0006 מראים סתירה\u0005]\u0006 ממה שנאמר בתורה בהלכות נגע צרעת \u0003\"\u0004או בשר כי יהיה בעורו \u0003מכות אש\"\u0004 (ויקרא יג, כד), לכאורה \u0003אין לי אלא שנכוה באש\u0004 עצמה, \u0003נכוה בגחלת, ברמץ\u0004 אפר רותח , \u0003בסיד רותח, בגפסיס\u0004 (גבס) \u0003רותח, וכל דבר\u0004 רותח אחר \u0003הבא\u0004 (שמקור חומו) \u0003מן האור\u0004 (האש ), \u0003לאיתויי\u0004 \u0005[להביא]\u0006 גם את \u0003חמי האור\u0004 (מים חמים שנתחממו באש), שגם כוייה שעל ידם קרויה מכוה \u0003מניין? תלמוד לומר: \"מכוה\" \"מכוה\" ריבה.\u0004 שהמלה \"מכוה\" חוזרת עוד בהמשך, ללמדנו שכל מין מכוה בכלל.","ונדייק: \u0003טעמא דרבי רחמנא\u0004 \u0005[הטעם\u0006 דוקא, \u0005שריבה הכתוב]\u0006 על ידי המלים \u0003\"מכוה\" \"מכוה\", הא\u0004 \u0005[הרי]\u0006 אם \u0003לא\u0004 היה \u0003רבי רחמנא\u0004 \u0005[מרבה הכתוב]\u0006 \u0003\"מכוה\" \"מכוה\",\u0004 היינו אומרים \u0003גחלים לאו\u0004 \u0005[לא]\u0006 \u0003אש נינהו\u0004 \u0005[הן]\u0006 בניגוד לדברי רבי שאש משמעו גם גחלים!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גחלת של עץ לא איצטריך קרא לרבויי\u0004 \u0005[צריך המקרא לרבותה],\u0006 שכל עוד בוערת היא הריהי ודאי נחשבת כאש. \u0003כי איצטריך קרא\u0004 \u0005[כאשר הוצרך המקרא]\u0006 ללמוד \"מכוה\" \"מכוה\" הריהו לענין \u0003גחלת של מתכת\u0004 חתיכת מתכת שהתלהטה באש ולולי הפסוק אפשר היה לחשוב שאם נכוה האדם בחתיכת מתכת שלובנה אין דינה כאש.","ותוהים: וכי \u0003גחלים של מתכת לאו\u0004 \u0005[אינן]\u0006 \u0003אש הוא? והא גבי\u0004 \u0005[והרי לענין]\u0006 \u0003בת כהן\u0004 שזנתה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ובת איש כהן כי תחל לזנות את אביה היא מחללת \u0003באש תשרף\"\u0004 (ויקרא כא, ט). \u0003ואמר רב מתנה:\u0004 לא היו שורפים אותה ממש באש, אלא \u0003פתילה של אבר\u0004 (חתיכת עופרת) \u0003היו עושין לה,\u0004 שהיו מתיכים עופרת ושופכים בגרונה וכך היו ממיתים אותה, משמע שמתכת לוהטת הרי היא נחשבת כאש!","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 לא רק \"באש\", אלא \u0003\"באש תשרף\",\u0004 ומהמלה \u0003\"תשרף\"\u0004 אנו למדים: \u0003לרבות כל שריפות הבאות מן האש.\u0004","ומקשים: אם כן, \u0003וכל שכן אש עצמה\u0004 ודאי מקיימים בה מצות שריפה. ואם כן, \u0003נקיף לה\u0004 \u0005[אותה]\u0006 \u0003חבילי זמורות ונקלה\u0004 \u0005[ונשרפנה]\u0006 בהן! ומשיבים: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שוה מן המילים \u0003\"שריפה\" \"שריפה\"\u0004 האמורות גם במיתת \u0003בני אהרן. מה להלן\u0004 בבני אהרן נאמר שנשרפו באש (ויקרא י, ב) — היתה זו \u0003שריפת נשמה וגוף\u0004 עצמו ברובו קיים, שהרי אף בגדיהם לא נשרפו. \u0003אף כאן\u0004 בבת כהן — \u0003שריפת נשמה וגוף קיים.\u0004","ושואלים: \u0003ונעביד\u0004 \u0005[ונעשה]\u0006 \u0003לה\u0004 מיתתה ב\u0003חמי האור\u0004 על ידי מים רותחים, ואף על ידי כך אפשר להמיתה כבאש? ומשיבים שכאן יש נימוק נוסף, \u0003משום\u0004 דבריו של \u0003רב נחמן.\u0004 ש\u0003אמר רב נחמן: אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ואהבת לרעך כמוך\"\u0004 (ויקרא יט, יח) ובין שאר המסקנות להלכה הנלמדות מכתוב זה יש לקיימו שגם בשעת מיתת בית דין \u0003ברור לו מיתה יפה.\u0004 שאף כשחייבים לדון אדם למיתה יש לדאוג שיהא זה בצורה הנוחה ביותר.","ושואלים: \u0003וכי מאחר דאיכא\u0004 \u0005[שיש]\u0006 נימוק זה של \u0003רב נחמן,\u0004 אם כן \u0003גזירה שוה\u0004 מבני אהרן \u0003למה לי?\u0004 הלוא גם בלעדיה היינו מנסים לקיים מצות שריפה בעופרת שהיא מיתה קלה יותר! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003גזירה שוה הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003שריפת נשמה וגוף קיים לאו\u0004 \u0005[לא]\u0006 \u0003שריפה היא,\u0004 שמיתה זו אינה קרויה כלל שריפה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום\u0004 דבריו של \u0003רב נחמן\u0004 בלבד שיש לברור מיתה יפה — \u0003ניפוש\u0004 \u0005[נרבה]\u0006 \u0003לה חבילי זמורות טובא\u0004 \u0005[הרבה],\u0006 \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003תמות בעגלא\u0004 \u0005[במהרה],\u0006 ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בלימוד מבני אהרן שמיתה כזו קרויה שריפה.","ושואלים: \u0003ואלא\u0004 אם כן שאמר הכתוב \"תשרף\" לרבות כל מין שריפה המילה \u0003\"באש\" למה לי?\u0004 ומשיבים: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003אבר מעיקרו.\u0004 שבשעה שמוציאים את העופרת מקרקע היא רותחת מעצמה, ובעופרת רותחת זו אין מקיימים מצות שריפה, כיון שאין חומה בא על ידי האש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא: וכל היכא דכתיב\u0004 \u0005[מקום שנאמר]\u0006 \u0003\"באש תשרף\",\u0004 האם בא הדבר \u0003לרבות כל שריפות הבאות מחמת אש הוא? והא\u0004 \u0005[והרי]\u0006 לגבי \u0003פרים הנשרפים דכתיב בהו\u0004 \u0005[שנאמר בהם]:\u0006 \u0003\"ושרף אתו על עצים באש\u0004 על שפך הדשן ישרף\u0003\"\u0004 (ויקרא ד, יב. וראה ויקרא ד, כא) \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"באש\" — ולא בסיד רותח ולא בגפסיס\u0004 (גבס) \u0003רותח,\u0004 ומדוע אין מתירים גם כאן בכל מין שריפה?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם כתיב\u0004 \u0005[שם\u0006 בבת כהן \u0005נאמר]\u0006 \u0003\"באש\", והדר\u0004 \u0005[ואחר כך]\u0006 כתב \u0003\"תשרף\"\u0004 ודבר זה בא \u0003לרבות כל שריפות הבאות מחמת האש, הכא כתיב\u0004 \u0005[כאן נאמר]\u0006 \u0003\"ושרף אתו על עצים באש\" לבסוף\u0004 נאמרה \u0003\"אש\", למימרא\u0004 \u0005[האם לומר]:\u0006 ש\u0003אש — אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר] —\u0006 \u0003לא.\u0004","ודוחים: והלוא \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 בענין פרים הנשרפים \u0003כתיבא\u0004 \u0005[נאמרה]\u0006 לשון \u0003\"שריפה\" לבסוף, דכתיב\u0004 \u0005[שנאמר]\u0006 בסופו של הכתוב:"],["\u0003\"על שפך הדשן ישרף\"\u0004 (ויקרא ד, יב)! ודוחים, \u0003אמרי: ההוא\u0004 \u0005[אומרים: אותו]\u0006 \u0003\"ישרף\" מיבעי ליה לכדתניא\u0004 \u0005[צריך אותו\u0006 כענין הברייתא \u0005השנויה]:\u0006 \u0003\"ישרף\"\u0004 — מכל מקום, \u0003אף על פי שאין שם דשן\u0004 אין להקפיד, ש\"על שפך הדשן\" אינו מעכב. \u0003\"ישרף\" — אף על פי שהצית האור ברובו\u0004 אין די בכך וצריך לגמור את שריפתו.","\u0003רבינא אמר:\u0004 את הסתירה בענין גחלים שלכאורה אינן קרויות אש יש לתרץ על ידי שינוי בגירסת הברייתא \u0003כרוך ותני\u0004 \u0005[כרך ושנה]\u0006 את הנושאים יחד: \u0003\"מכות אש\" אין לי אלא שנכוה באש ובגחלת, נכוה ברמץ\u0004 (אפר רותח) \u0003בסיד רותח ובגפסיס\u0004 (גבס) \u0003רותח ובכל דבר\u0004 רותח \u0003הבא מחמת האור, לאיתויי\u0004 \u0005[להביא]\u0006 \u0003חמי האור מניין? תלמוד לומר: \"מכוה\" \"מכוה\" ריבה\u0004 הכתוב שלגירסה זו גחלת ואש מנויות יחד בענין אחד.","\u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר רבי גחלים איקרו\u0004 \u0005[נקראו]\u0006 \u0003אש, ורמינהו\u0004 \u0005[משליכים,\u0006 מביאים סתירה\u0005]\u0006 שנדרש הכתוב \"ולקח מלא המחתה גחלי אש מעל המזבח מלפני ה'\" (ויקרא טז, יב) \u0003\"גחלי\" יכול\u0004 גחלים \u0003עוממות\u0004 (שהאש כמעט כבתה בהן ואינה ניכרת בחוץ) \u0003תלמוד לומר: \"אש\". אי\u0004 \u0005[אם]\u0006 \u0003אש יכול\u0004 הכוונה ל\u0003שלהבת תלמוד לומר \"גחלי\". הא כיצד\u0004 מיישב את שתי הדרישות \u0003מביא מן\u0004 הגחלים \u0003הלוחשות\u0004 שהאש נראית בהן. \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003גחלים\u0004 סתם \u0003לא איקרי\u0004 \u0005[נקראו]\u0006 \u0003אש!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 ומשיבים: אין לדון מברייתא זו \u0003והא גופא קשיא\u0004 \u0005[והרי\u0006 היא \u0005עצמה קשה]\u0006 \u0003אמרת \"גחלי\" יכול\u0004 גחלים \u0003עוממות, אלמא\u0004 \u0005[מכאן]\u0006 שברור לו כי גחלים \u0003לוחשות אש נינהו\u0004 \u0005[הן],\u0006 \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של אותה ברייתא: \u0003אי\u0004 \u0005[אם]\u0006 \u0003אש, יכול שלהבת — תלמוד לומר: \"גחלי\", אלמא\u0004 \u0005[מכאן]\u0006 \u0003אפילו\u0004 גחלים \u0003לוחשות לאו\u0004 \u0005[לא]\u0006 \u0003אש נינהו\u0004 \u0005[הן],\u0006 ויש סתירה בתוך הברייתא עצמה.","\u0003ואמר רב ששת\u0004 כדי ליישב לשון הברייתא, \u0003הכי קתני\u0004 \u0005[כך שנה,\u0006 כך יש לשנות\u0005]:\u0006 \u0003\"גחלי\" — יכול\u0004 יקח כפי רצונו \u0003בין עוממות בין לוחשות תלמוד לומר \"אש\", אי\u0004 \u0005[אם]\u0006 \u0003אש יכול שלהבת — תלמוד לומר: \"גחלי\", הא כיצד? מביא מן\u0004 הגחלים \u0003הלוחשות. מכל מקום\u0004 למדנו מכאן כי \u0003גחלים, אפילו\u0004 הן לוחשות, \u0003לא איקרי\u0004 \u0005[נקראו]\u0006 \u0003אש, קשיא\u0004 \u0005[קשה]\u0006 \u0003לרבי\u0004 שלדעתו גחלים בכלל אש!","\u0003אמר אביי: תריץ הכי\u0004 \u0005[ישב כך]\u0006 \u0003\"גחלי\" — יכול עוממות ולא לוחשות, תלמוד לומר: \"אש\". אי\u0004 \u0005[אם]\u0006 \u0003\"אש\" יכול רצה שלהבת — יביא, רצה גחלת — יביא, תלמוד לומר \"גחלי\"\u0004 דוקא. \u0003הא כיצד — מביא מן הלוחשות.\u0004 ומדברים אלו ברור כי גם הגחלים קרויות אש כדברי רבי.","\u0003אמר רבה\u0004 בפירוש אחרון זה אמרנו: \u0003רצה גחלת — יביא, רצה שלהבת — יביא\u0004 אולם \u0003שלהבת בלא גחלת היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]?\u0006 ומשיבים: \u0003כגון דשפייה למנא משחא ואתלי ביה נורא\u0004 \u0005[שמרח את הכלי בשמן והדליק בו אש],\u0006 ואולם \u0003ההוא\u0004 דבר כגון זה \u0003למה לי קרא למעוטי\u0004 \u0005[מקרא\u0006 מפורש \u0005למעטו]\u0006 ללמד שאין עושים כן, \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003לפני מלך בשר ודם אין עושין כן\u0004 שדרך בזיון היא להביא לפני מלך מין שלהבת כזו, \u0003לפני מלך מלכי המלכים הקדוש ברוך הוא לא כל שכן!\u0004 ולא יתכן שיצטרך המקרא ללמד על דבר כגון זה.","\u0003אלא אמר רבא: תריץ הכי\u0004 \u0005[ישב כך]\u0006 את הברייתא: \u0003\"גחלי\" יכול עוממות ולא לוחשות — תלמוד לומר: \"אש\", אי\u0004 \u0005[אם]\u0006 \u0003\"אש\" יכול יביא מחצה גחלת ומחצה שלהבת\u0004 שתהיינה הגחלים בשעת לקיחתן מהמזבח בוערות על פני חלקן בחזקה ושלהבתן ניכרת, \u0003אדעייל לגואי\u0004 \u0005[עד ש\u0006הוא \u0005נכנס פנימה]\u0006 תתעמעם האש ו\u0003הוי כוליה\u0004 \u0005[יהיה הכל]\u0006 \u0003גחלת\u0004 — \u0003תלמוד לומר: \"ולקח מלא המחתה גחלי אש מעל המזבח\"\u0004 משמעו: \u0003משעת לקיחה ניהוי\u0004 \u0005[יהיו]\u0006 כבר \u0003גחלים\u0004 ולא שלהבת.","כיון שדובר עד כה בגחלים עוממות מזכירים כי \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 כיצד יש לגרוס: \u0003אוממות\u0004 באל\"ף \u0003או עוממות\u0004 בעי\"ן? \u0003אמר ר' יצחק:\u0004 יש לומר בעי\"ן, שנאמר: \u0003\"ארזים לא עממהו בגן אלהים\"\u0004 (יחזקאל לא, ח).","\u0003נגע\u0004 הפסח \u0003בחרסו של תנור — יקלוף את מקומו\u0004 של הפסח שנגע בגוף התנור, משום שחלק זה מן הקרבן נצלה על ידי חום התנור ולא על ידי האש עצמה. \u0003נטף מרוטבו\u0004 של הפסח \u0003על החרס, וחזר\u0004 הרוטב \u0003אליו\u0004 לקרבן — \u0003יטול את מקומו\u0004 שלא די בקליפה בלבד וצריך ליטול חתיכה גדולה יותר, שמקום זה לא נצלה אלא נתבשל מהרוטב. נטף \u0003מרוטבו על הסולת\u0004 הרותחת \u0003יקמוץ את מקומו\u0004 של הרוטב בסולת, ויבערנו.","\u0003סכו\u0004 את הפסח \u0003בשמן תרומה, אם חבורת כהנים\u0004 היא חבורה זו — \u0003יאכלו\u0004 שהרי מותרים הם באכילת תרומה. \u0003אם\u0004 חבורה \u0003של ישראל, אם חי\u0004 (בלתי מבושל) \u0003הוא\u0004 עדיין הפסח — \u0003ידיחנו\u0004 ויוריד ממנו את שמן התרומה. \u0003ואם צלי הוא — יקלוף את החיצון\u0004 שנבלע בו השמן, כדי שלא יאכלו ישראלים משמן התרומה שהם אסורים בו. \u0003סכו בשמן של מעשר שני — לא יעשנו דמים על בני חבורה\u0004 כלומר, האיש שנתן את שמן המעשר הזה אסור לו לדרוש תשלום עבורו משאר בני החבורה. \u0003שאין פודין מעשר שני בירושלים\u0004 שהמעשר השני אסור לפדותו (או למוכרו) בירושלים, ומיועד לאכילה בלבד, ואסור במכירה לאחרים, ומותר רק לתתו במתנה.","מתוך משנתנו מפתחים דיון רחב בהלכות איסורים שנגעו זה בזה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיות אלה וקודם כל מונים את הדברים הברורים: אם היה דבר \u0003חם\u0004 שנפל או נגע \u0003בתוך חם,\u0004 כגון בשר חם בתוך חלב רותח, או בשר היתר במרק של איסור — \u0003דברי הכל\u0004"],["\u0003אסור,\u0004 משום שההיתר בולע מן האיסור. אם היה \u0003צונן לתוך צונן — דברי הכל מותר,\u0004 ואינם צריכים אלא שטיפה. נפל \u0003חם לתוך צונן,\u0004 או \u0003צונן\u0004 שנפל \u0003לתוך חם,\u0004 בכך נחלקו; \u0003רב אמר: עילאה גבר\u0004 \u0005[העליון גובר]\u0006 ודנים הכל לפי מה שהיה למעלה, שאם היה העליון חם — נדון כאילו נפל חם בחם, שהרי העליון מחמם את התחתון ונחשב כאילו חם בחם. היה העליון קר — נדון כקר בקר העליון מקרר את התחתון וכאילו נפל קר בקר. \u0003ושמואל אמר: תתאה גבר\u0004 \u0005[התחתון גובר]\u0006 שאם העליון חם והתחתון קר — מותר, ואם העליון קר והתחתון חם — אסור.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 \u0003נטף\u0004 בתנור \u0003מרוטבו\u0004 של הפסח \u0003על החרס וחזר אליו — יטול את מקומו. קא סלקא דעתך\u0004 \u0005[עלה על דעתך]\u0006 לומר שמדובר כאן \u0003בחרס צוננת\u0004 ואם כן, \u0003בשלמא ל\u0004שיטת \u0005[נניח]\u0006 \u0003רב\u0004 ש\u0003אמר עילאה גבר\u0004 \u0005[העליון גובר],\u0006 \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003יטול את מקומו.\u0004 שלפי שיטה זו \u0003דאזל\u0004 \u0005[שהולך]\u0006 \u0003רוטב\u0004 השותת מן הפסח \u0003מרתח ליה\u0004 \u0005[מחמם אותו]\u0006 את \u0003החרס, והדר\u0004 \u0005[וחוזר]\u0006 ה\u0003חרס מרתח ליה\u0004 \u0005[מחמם אותו]\u0006 את ה\u0003רוטב, וכי הדר\u0004 \u0005[וכאשר חוזר]\u0006 ה\u0003רוטב ל\u0004\u0003פסח — קא מטוי\u0004 \u0005[נצלה]\u0006 ה\u0003פסח מחמת חמימותא\u0004 \u0005[חמימות]\u0006 ה\u0003חרס, ורחמנא\u0004 \u0005[והכתוב]\u0006 \u0003אמר \"צלי אש\"\u0004 (שמות יב, ח) \u0003ולא צלי מחמת דבר אחר.\u0004","\u0003אלא, ל\u0004שיטת \u0003שמואל\u0004 ש\u0003אמר תתאה גבר\u0004 \u0005[תחתון גובר]\u0006 \u0003חרס כיון\u0004 ש\u0003צונן הוא אקורי מיקר ליה\u0004 \u0005[מקרר הוא אותו]\u0006 את ה\u0003רוטב, אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003יטול את מקומו?\u0004 ומתרצים: \u0003כ\u0004פי ש\u0003אמר ר' ירמיה אמר שמואל\u0004 בהמשך כביאור לדברי המשנה בדין רוטב הפסח שנטף על סולת: \u0003בסולת רותחת, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בחרס רותח\u0004 שהיה חרס לוהט מחמת עצמו ואף לשיטת שמואל נחשב כחם בחם.","ועוד \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 \u0003\"נטף מרוטבו\u0004 של הפסח \u0003על הסולת יקמוץ את מקומו\". קא סלקא דעתך\u0004 \u0005[עלה על דעתך]\u0006 לומר שמדובר \u0003בסולת צוננת. בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר עילאה גבר — משום הכי\u0004 \u0005[כך]\u0006 \u0003יקמוץ את מקומו,\u0004 כיצד — \u0003דמרתח לה\u0004 \u0005[ש\u0006הרוטב \u0005מרתיח אותה]\u0006 את ה\u0003סולת דהדר הודרניה\u0004 \u0005[שמסביבו],\u0006 \u0003והדרא\u0004 \u0005[וחוזרת]\u0006 ה\u0003סולת ומרתחא ליה לדידיה\u0004 \u0005[ומרתיחה אותו עצמו]\u0006 את הרוטב של הפסח, \u0003וקא מטוי\u0004 \u0005[ונצלה]\u0006 ה\u0003רוטב מחמת חמימותא\u0004 \u0005[החום]\u0006 של ה\u0003סולת, ורחמנא\u0004 \u0005[והכתוב]\u0006 \u0003אמר \"צלי אש\" ולא צלי מחמת דבר אחר.\u0004","\u0003אלא ל\u0004שיטת \u0003שמואל\u0004 ש\u0003אמר תתאה גבר\u0004 \u0005[התחתון גובר],\u0006 \u0003סולת כיון\u0004 ש\u0003צוננת היא אקורי קא מיקר ליה\u0004 \u0005[מקררת היא אותו]\u0006 \u0003למה לי יקמוץ את מקומו? תסגי ליה\u0004 \u0005[די לו]\u0006 במה שיקלף ו\u0003\"יטול את מקומו\"\u0004 ואינו צריך ליטול יותר! על כך \u0003אמר ר' ירמיה אמר שמואל:\u0004 מדובר כאן \u0003בסולת רותחת\u0004 שהרוטב נצלה מפני חומה ולכן צריך ליטול חלק זה בשלמותו.","ועוד \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003סכו\u0004 את הפסח \u0003בשמן של תרומה, אם חבורת כהנים\u0004 היתה זו — \u0003יאכלו. אם\u0004 חבורה \u0003של ישראל, אם\u0004 עדיין \u0003חי הוא\u0004 ולא צלי — \u0003ידיחנו, אם צלי הוא — יקלוף את החיצון. בשלמא\u0004 \u0005[נניח]\u0006 \u0003לרב\u0004 ש\u0003אמר עילאה גבר\u0004 \u0005[העליון גובר]\u0006 \u0003אמטו להכי סגי ליה\u0004 \u0005[משום כך די לו]\u0006 \u0003בקליפה, משום דעילאה\u0004 \u0005[שהעליון]\u0006 \u0003צונן הוא,\u0004 ולכן אינו נבלע כל כך,","\u0003אלא לשמואל\u0004 ש\u0003אמר תתאה גבר\u0004 \u0005[התחתון גובר]\u0006 \u0003כיון\u0004 ש\u0003חם הוא\u0004 הבשר התחתון — \u0003מבלע בלע\u0004 \u0005[בולע]\u0006 הוא את השמן, \u0003אמאי סגי ליה\u0004 \u0005[מדוע\u0006 אם כן \u0005די לו]\u0006 \u0003בקליפה? ניתסר\u0004 \u0005[שיאסר]\u0006 \u0003לגמרי!\u0004 ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003סיכה\u0004 ש\u0003משהו בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא דעבידא\u0004 \u0005[שעשויה],\u0006 שאין סכים בשמן הרבה, אלא בכמות קטנה מאוד, ואין בה כדי לאסור את כל הפסח כולו.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 כשיטתו של \u0003שמואל: חם לתוך חם — אסור, וכן צונן שנתן לתוך חם — אסור. חם לתוך צונן וצונן לתוך צונן — מדיח\u0004 אותו.","ושואלים: ואם נפל היתר \u0003חם לתוך צונן מדיחו כיון\u0004 ש\u0003חם הוא, אדמיקר ליה\u0004 \u0005[עד ש\u0006הוא \u0005מקרר אותו]\u0006 — \u0003אי אפשר\u0004 ש\u0003לא בלע פורתא\u0004 \u0005[מעט]\u0006 מן האיסור, \u0003קליפה מיהא ניבעי\u0004 \u0005[על כל פנים יצטרך]\u0006 ואין די בהדחה! \u0003אלא אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 כך: \u0003חם לתוך צונן — קולף, צונן לתוך צונן — מדיח.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 \u0003בשר רותח שנפל לתוך חלב רותח, וכן צונן שנפל לתוך חם — אסור. חם לתוך צונן וצונן לתוך צונן — מדיח.\u0004 ונשאלת לכאורה אותה שאלה: \u0003חם לתוך צונן מדיח?! כיון\u0004 ש\u0003חם הוא, אדמיקר ליה\u0004 \u0005[עד ש\u0006הוא \u0005מקרר אותו]\u0006 — \u0003אי אפשר\u0004 ש\u0003לא בלע פורתא\u0004 \u0005[מעט]\u0006 מן האיסור, \u0003קליפה מיהא ניבעי\u0004 \u0005[על כל פנים יצטרך]!\u0006 \u0003אלא אימא\u0004 \u0005[אמור\u0006 תקן\u0005]\u0006 כך: \u0003חם לתוך צונן — קולף, צונן לתוך צונן — מדיח.\u0004","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003צונן לתוך צונן — מדיח. אמר רב הונא: לא שנו אלא שלא מלחו\u0004 אחד מהם, \u0003אבל מלחו — אסור.\u0004 ש\u0003אמר שמואל: מליח הרי הוא כרותח\u0004 מצד כוחו לבלוע. \u0003כבוש\u0004 בתוך חומץ וכיוצא בו \u0003הריהו כמבושל\u0004 שבולע.","\u0003אמר רבא: הא\u0004 \u0005[זה]\u0006 ש\u0003אמר שמואל מליח הרי הוא כרותח לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 שהיה מלוח עד כדי \u0003שלא נאכל\u0004 לרוב האנשים \u0003מחמת מלחו, אבל\u0004 אם עדיין \u0003נאכל מחמת מלחו,\u0004 כלומר, על אף מליחותו \u0003— לא,\u0004 אין דינו כרותח ואינו בולע.","מסופר: \u0003ההוא בר גוזלא\u0004 \u0005[גוזל אחד]\u0006 ש\u0003נפל לכדא דכמכא\u0004 \u0005[לכד של כותח]\u0006 שאחד ממרכיביו הוא חלב. והשאלה היתה בדבר איסור של בשר בחלב שיש כאן, \u0003שריא\u0004 \u0005[התירו]\u0006 \u0003רב חיננא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מ\u0004העיר \u0003פשרוניא,\u0004","\u0003אמר\u0004 על כך \u0003רבא: מאן חכים למישרא מילתא כי הא\u0004 \u0005[מי חכם להתיר דבר\u0006 מסובך \u0005כגון זה]\u0006 \u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003רב חיננא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מ\u0004העיר \u0003פשרוניא, דגברא רבה\u0004 \u0005[שאדם גדול]\u0006 \u0003הוא,\u0004 ויכול למצוא היתר אפילו במה שנראה אסור. כי \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך, כי\u0004 \u0005[כאשר]\u0006 \u0003אמר שמואל מליח הרי הוא כרותח\u0004 — הרי זה במלוח \u0003שאין נאכל מחמת מלחו,\u0004 ואולם \u0003האי\u0004 \u0005[זה,\u0006 הכותח\u0005]\u0006 \u0003נאכל מחמת מלחו\u0004 ואם כן הרי דינו כצונן שנפל בתוך צונן ודיו בהדחה, ואינו נאסר כולו.","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים כאשר היה הגוזל \u0003חי, אבל\u0004 אם היה \u0003צלי — בעי\u0004 \u0005[צריך]\u0006 \u0003קליפה,\u0004 שכיון שנצלה נתרכך ובולע יותר. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא דלית ביה פילי\u0004 \u0005[שאין בו\u0006 בגוזל \u0005סדקים],\u0006 \u0003אבל\u0004 אם \u0003אית ביה פילי\u0004 \u0005[יש בו סדקים]\u0006 — \u0003אסור,\u0004 שנבלע בהם הכותח. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003מתובל בתבלי\u0004 \u0005[בתבלינים] —\u0006 \u0003אסור,\u0004 שעל ידיהם הוא מתרכך ובולע.","\u0003אמר רב:\u0004"],["\u0003בשר שחוטה\u0004 כלומר בשר כשר, \u0003שמן, שצלאו\u0004 באותו תנור \u0003עם בשר נבילה כחוש,\u0004 אף שלא נגעו זה בזה — \u0003אסור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003מפטמי מהדדי\u0004 \u0005[הם מתפטמים,\u0006 מקבלים, \u0005זה מזה]\u0006 משום שהבשר השמן מדיף מריחו, ונכנס הריח בבשר הנבילה, וחוזר משם ובולע הכשר בחזרה משהו ממנו.","\u0003ולוי אמר\u0004 שאין לחשוש לאיסור שעל ידי ריח, \u0003אפילו בשר שחוטה כחוש שצלאו עם בשר נבילה שמן — מותר. מאי טעמא\u0004 \u0005[מה הטעם],\u0006 מפני שאף שבשר הנבלה מדיף מריחו ונבלע הריח בשחוטה הרי \u0003ריחא בעלמא\u0004 \u0005[ריח בלבד]\u0006 \u0003הוא, וריחא לאו מילתא\u0004 \u0005[וריח לא דבר\u0006 של ממש\u0005]\u0006 \u0003היא.\u0004 ומסופר: \u0003עביד\u0004 \u0005[עשה]\u0006 \u0003לוי עובדא בי ריש גלותא\u0004 \u0005[מעשה בבית ראש הגולה]\u0006 \u0003בגדי ודבר אחר\u0004 (חזיר) שנצלו כאחד, ולא אסר את הגדי משום ריחו של החזיר.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003אין צולין שני פסחים כאחד מפני התערובת. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא מפני \u0003תערובת טעמים,\u0004 שריחו של זה נכנס בזה, \u0003וקשיא\u0004 \u0005[וקשה]\u0006 \u0003ל\u0004שיטת \u0003לוי!\u0004 ודוחים: \u0003לא,\u0004 הטעם הוא \u0003מפני תערובת גופין\u0004 שפעמים יוכלו להחליף זה בזה ונמצא הפסח נאכל שלא למנויו.","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 \u0003מדקתני סיפא\u0004 \u0005[ממה ששנינו בסוף\u0006 אותה ברייתא\u0005]\u0006 \u0003אפילו\u0004 היו אלה \u0003גדי וטלה. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שהטעם \u0003מפני\u0004 תערובת \u0003גופין — היינו דקתני\u0004 \u0005[זו היא ששנינו]\u0006 \u0003אפילו גדי וטלה,\u0004 שאם כי אינם דומים זה לזה — מכל מקום חוששים שמא יחליפו אותם לאחר הפשטת העור. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהטעם \u0003מפני תערובת טעמים, מה לי גדי וטלה מה לי גדי וגדי\u0004 ואין חידוש בטלה וגדי יותר מבגדי וגדי,","ומקשים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אומר אתה \u0003על כרחיך מפני תערובת גופין הוא\u0004 ש\u0003אסור, אבל תערובת טעמים — שרי\u0004 \u0005[מותר]\u0006 \u0003לימא תיהוי תיובתיה\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה]\u0006 \u0003לרב\u0004 החושש לתערובת טעמים! \u0003אמר ר' ירמיה: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שצלאו בשתי קדירות,\u0004 ואין קולטים ריח זה מזה.","ותוהים: \u0003בשתי קדירות סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 והלוא אסור לצלות את הפסח בקדירה! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 \u0003כעין שתי קדירות.\u0004 כלומר, שהיו מרוחקים ומובדלים במחיצה זה מזה. \u0003והכי קאמר\u0004 \u0005[וכך אמר]\u0006 כך יש לפרש את הברייתא: \u0003אין צולין שני פסחים כאחד מפני תערובת מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003תערובת\u0004 זו — \u0003תערובת טעמים. ואפילו כעין שתי קדירות דליכא\u0004 \u0005[שאין]\u0006 \u0003תערובת טעמים — אסור\u0004 גם כן, מפני חשש אחר \u0003משום תערובת גופין, ואפילו\u0004 היו אלה \u0003גדי וטלה.\u0004","\u0003אמר רב מרי כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שאף הם נחלקו באותו ענין עצמו. \u0003הרודה פת חמה ונתנה על פי חבית יין של תרומה, ר' מאיר אוסר\u0004 פת זו באכילה לזר, שלדעתו סופגת הפת מריח יין התרומה, והריהי כתרומה, \u0003ור' יהודה מתיר. ור' יוסי מתיר\u0004 בפת \u0003של חיטין\u0004 שאינה סופגנית כל כך \u0003ואוסר בשל שעורין מפני שהשעורים שואבות\u0004 וסופגות ריח. \u0003מאי לאו תנאי היא\u0004 \u0005[האם לא\u0006 מחלוקת \u0005תנאים היא]\u0006 שהרי ברור שיש תנא החושש לספיגת ריח. \u0003דמר סבר ריחא לאו מילתא היא, ומר סבר ריחא מילתא היא\u0004 \u0005[שחכם זה\u0006 ר' יהודה, \u0005סבר: ריח אינו דבר. וחכם זה,\u0006 ר' מאיר, \u0005סבר: ריח דבר הוא].\u0006","ואומרים: \u0003ל\u0004שיטת \u0003לוי\u0004 שריח אינו דבר, \u0003ודאי\u0004 מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא,\u0004 שלר' מאיר ור' יוסי הריהו דבר ואילו לר' יהודה אינו דבר, והוא עצמו סובר כשיטת ר' יהודה. ואולם האם \u0003ל\u0004שיטת \u0003רב נימא תנאי\u0004 \u0005[נאמר\u0006 שמחלוקת \u0005תנאים]\u0006 \u0003היא?\u0004","שהרי \u0003אמר לך רב\u0004 \u0005[\u0006יכול היה \u0005רב לומר לך]\u0006 \u0003דכולי עלמא ריחא מילתא היא\u0004 \u0005[לדעת הכל ריח דבר הוא],\u0006 ולא נחלקו אלא בשאלה, האם הפת שואבת את הריח באופן כזה, שכן \u0003ולאו איתמר עלה דההיא\u0004 \u0005[וכי לא נאמר עליה על אותה\u0006 משנה\u0005],\u0006 \u0003אמר רבה בר בר חנה אמר ריש לקיש: בפת חמה וחבית פתוחה — דברי הכל אסור.\u0004 משום שודאי היא שואבת, \u0003בפת צוננת וחבית מגופה\u0004 (מכוסה) \u0003— דברי הכל מותר. לא נחלקו אלא בפת חמה וחבית חתומה\u0004 (סגורה) שמא בכל זאת היא שואבת דרך סדקים, וכן ב\u0003פת צוננת וחבית פתוחה. והא נמי\u0004 \u0005[וזו גם כן]\u0006 בשני פסחים הנצלים בתנור אחד \u0003כפת חמה וחבית פתוחה דמיא\u0004 \u0005[נחשב].\u0006","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב כהנא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חיננא סבא: פת שאפאה עם צלי בתנור — אסור לאכלה בכותחא\u0004 שיש בו חלב, משום שבפת נספג משהו מטעם הבשר. מסופר: \u0003ההיא ביניתא דאיטווא בהדי בישרא, אסרה\u0004 \u0005[דג שנצלה\u0006 יחד \u0005עם בשר, אסרו]\u0006 \u0003רבא מפרזיקיא למיכליה בכותחא\u0004 \u0005[לאכול אותו בכותח]\u0006 משום טעם הבשר שנבלע בו. \u0003מר בר רב אשי אמר: אפילו\u0004 לאכלה \u0003במילחא נמי\u0004 \u0005[במלח בלא\u0006 כותח \u0005גם כן]\u0006 \u0003אסורה, משום\u0004 שבשר שנתבשל או נצלה עם דגים \u0003קשיא לריחא\u0004 \u0005[היא קשה,\u0006 גורמת \u0005לריח\u0006 רע מן הפה\u0005].\u0006 \u0003ולדבר אחר\u0004 (לצרעת) ויש להתרחק לכך מאכילתו מחשש סכנה שבדבר.","\u0003חמשה דברים\u0004 מן הקרבנות \u0003באין\u0004 (מוקרבים) \u0003בטומאה,\u0004 אבל \u0003אינן נאכלין בטומאה,\u0004 שהתירה התורה להקריבם, אך לא לאכלם, וכולם מקרבנות הציבור. ואלו הם: \u0003העומר\u0004 שמביאים בניסן, \u0003ושתי הלחם\u0004 בשבועות, \u0003ולחם הפנים\u0004 שבכל שבת, \u0003וזבחי שלמי צבור\u0004 שמביאים בשבועות. \u0003ושעירי ראשי חדשים\u0004 שהם קרבנות חטאת הנאכלים לכהנים. ואילו \u0003הפסח שבא בטומאה\u0004 אף \u0003נאכל בטומאה, שלא בא\u0004 (קרב) \u0003מתחילתו אלא לאכילה,\u0004 שהיא מעיקר מצותו. ולא כקרבנות האחרים שעיקר מצוותם הוא בהקרבתם, ואכילתם אינה מעכבת.","שנינו במשנה מנין \u0003חמשה.\u0004 ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט את מה]\u0006 באה הדגשת מספר זה? ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003חגיגת חמשה עשר\u0004 שהיא חגיגה שמביאים בתוך החג עצמו שאינה באה בטומאה.","\u0003דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]:\u0006 \u0003כיון\u0004 ש\u0003קרבן ציבור הוא,\u0004 שהרי כל הציבור חייב להביא אותה \u0003וקביעא ליה\u0004 \u0005[וקבוע לה]\u0006 \u0003מועד\u0004 (זמן), שאין להביאה בכל יום — \u0003תידחי\u0004 (תדחה) \u0003טומאה,\u0004 כשאר קרבנות ציבור שזמנן קבוע, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו],\u0006 \u0003כיון דאית ליה\u0004 \u0005[שיש לו]\u0006 לקרבן זה \u0003תשלומין כל שבעה,\u0004 שאם לא הוקרבה בחמישה עשר, יש לה עדיין תשלומים בשאר ימי החג — \u0003לא דחיא\u0004 \u0005[דוחה]\u0006 \u0003שבת, ומ\u0004כיון ש\u0003שבת לא דחיא\u0004 \u0005[דוחה] —\u0006 \u0003לא דחיא\u0004 \u0005[דוחה]\u0006 \u0003טומאה,\u0004 ולכן אין קרבן זה בא בטומאה.","ושואלים: \u0003וניתני נמי\u0004 \u0005[וישנה גם כן]\u0006 \u0003שעירי הרגלים\u0004 שהרי בחגים מביאים שעירים נוספים לחטאת, שאף הם דוחים את הטומאה! ועונים: \u0003הא תנא ליה\u0004 \u0005[הרי\u0006 כבר \u0005שנה אותם]\u0006 בכלל \u0003זבחי שלמי צבור,\u0004 ושעירים כיוצא בהם. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003שעירי ראשי חדשים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ניתני\u0004 \u0005[ישנה],\u0006 \u0003דהא תנא\u0004 \u0005[שהרי\u0006 כבר \u0005שנה]\u0006 \u0003זבחי שלמי צבור! אמרי\u0004 \u0005[אומרים]\u0006 כתשובה:"],["\u0003שעירי ראשי חדשים איצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 לאומרם במיוחד, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא כתיב בהו\u0004 \u0005[כתוב בהם]\u0006 \u0003\"מועד\",\u0004 וכיון שלא נאמר בראש חדש \"מועד\" לא ידחו את השבת ואת הטומאה כשאר קרבנות ציבור שדחייתם נלמדת ממה שנאמר בהם \"מועד\", \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף \u0003ראש חדש איקרי\u0004 \u0005[נקרא]\u0006 \u0003מועד,\u0004","\u0003וכד\u0004ברי \u0003אביי,\u0004 ביישוב המסורת שהיום שחזרו בו המרגלים מארץ ישראל, ובו בכו כל העדה בכיה של חנם היה תשעה באב ובשל כך נענשו שיהא יום זה בכיה לדורות ולפי החשבון אין הזמנים עולים יפה, ולכן \u0003אמר אביי: תמוז דהאי שתא מלויי מליוה\u0004 \u0005[של אותה שנה מילאו אותו]\u0006 שהיה בן שלושים יום (ולא עשרים ותשעה כרגיל) ויום הארבעים לו הוא תשעה באב, ורמז לדבר \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"קרא עלי מועד לשבר בחורי\"\u0004 (איכה א, טו) כלומר לצורך זה נקבע (\"נקרא\") ראש חדש, הקרוי כאן מועד, כדי לשבור את ישראל בעתיד, ומכאן למדים שראש חודש אף הוא קרוי מועד.","ושואלים \u0003למימרא\u0004 \u0005[האם לומר]\u0006 שאפשר ללמוד מכאן \u0003דכולהו\u0004 \u0005[שכולם]\u0006 \u0003מ\u0004מה שנאמר \u0003\"מועד\" אתו\u0004 \u0005[באים,\u0006 נלמדים\u0005],\u0006 \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר \u0003\"וידבר משה את מועדי ה'\u0004 אל בני ישראל\u0003\"\u0004 (ויקרא כג, מד) \u0003מה תלמוד לומר\u0004 מה באו ללמדנו מילים אלה? ומשיבים: \u0003לפי שלא למדנו אלא לתמיד ופסח\u0004 שדוחים את השבת ואת הטומאה \u0003שנאמר בהו\u0004 \u0005[בהם]\u0006 \u0003\"במועדו\"\u0004 ולמדים: \u0003\"במועדו\" ואפילו בשבת, \"במועדו\" ואפילו בטומאה,\u0004","\u0003שאר קרבנות ציבור מניין\u0004 שדוחים את השבת ואת הטומאה — \u0003שנאמר\u0004 בענין מוספים הבאים בימי הרגלים: \u0003\"אלה תעשו לה' במועדיכם\"\u0004 (במדבר כט, לט).","\u0003מניין לרבות עומר והקרב\u0004 הכבשים הקרבים \u0003עמו, שתי הלחם והקרב עמם\u0004 (שלמי ציבור) שגם הם דוחים את השבת אף שאינם מפורשים בכתוב זה שבספר במדבר — \u0003תלמוד לומר: \"וידבר משה את מועדי ה' אל בני ישראל\"\u0004 לאחר שמנה את כל השבתות והמועדים האחרים, הרי למדנו כי \u0003הכתוב קבעו מועד אחד לכולן.\u0004 שכל הימים המיוחדים הללו כולם קרויים מועד, ואין קרבנותיהם נדחים.","ושואלים: \u0003וכל הני\u0004 \u0005[אלה]\u0006 \u0003למה לי?\u0004 לכאורה אפשר היה ללמוד מאחד על האחרים! ומשיבים: \u0003צריכי\u0004 \u0005[נצרכו]\u0006 כולם ומסבירים: \u0003דאי כתב רחמנא תמיד\u0004 \u0005[שאם היתה התורה כותבת\u0006 בקרבן \u0005תמיד]\u0006 בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אמור]\u0006 קרבן \u0003תמיד\u0004 יש לו מעלה יתירה \u0003שכן\u0004 הוא \u0003תדיר\u0004 בכל יום וגם קרבן \u0003כליל\u0004 שכולו עולה לה' ולכן דוחה את השבת והטומאה \u0003אבל פסח\u0004 שאין בו אף לא אחד מאלה — \u0003לא, קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם הפסח דוחה את השבת.","\u0003ואי כתב רחמנא\u0004 \u0005[ואילו היתה התורה כותבת]\u0006 \u0003פסח\u0004 הייתי אומר: \u0003פסח שהוא ענוש כרת\u0004 אם מבטלו — דוחה את השבת ואת הטומאה, \u0003אבל תמיד\u0004 ש\u0003אין ענוש כרת\u0004 על ביטול הקרבתו \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף הוא דוחה.","\u0003ואי כתב רחמנא הני תרתי\u0004 \u0005[ואם התורה היתה כותבת שני אלה]\u0006 פסח ותמיד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003הני הוא\u0004 \u0005[אלה הם]\u0006 מיוחדים משום ש\u0003יש בהן צד חמור, תמיד —\u0004 שהוא \u0003תדיר וכליל, פסח — שהוא ענוש כרת. אבל שאר קרבנות ציבור\u0004 שאין בהם אף לא אחת מחומרות הללו \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"אלה תעשו לה' במועדיכם\"\u0004 לומר שאף הם דוחים.","\u0003ואי כתב רחמנא\u0004 \u0005[ואם\u0006 היתה \u0005התורה כותבת]\u0006 \u0003\"אלה תעשו לה' במועדיכם\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003שאר קרבנות ציבור הבאין לכפר\u0004 והרי חטאות ועולות (המכפרות על עשה ואל לאו הניתק לעשה) בכלל זה. \u0003אבל עומר ושתי הלחם\u0004 ש\u0003אין באין לכפר אלא להתיר בעלמא נינהו\u0004 \u0005[בלבד הם],\u0006 שעל ידי העומר מותר לאכול מתבואת השנה החדשה ועל ידי שתי הלחם מותר להקריב מתבואת השנה החדשה למזבח, הייתי אומר שאין הם דוחים את השבת והטומאה. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף אלה דוחים.","\u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 \u0003עומר ושתי הלחם לחודייהו\u0004 \u0005[לעצמם]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003אדרבה: עומר ושתי הלחם דאלימי\u0004 \u0005[שתקיפים]\u0006 חשובים הם כיון ש\u0003באין להתיר\u0004 לכן אינם נדחים, \u0003אבל הנך\u0004 \u0005[אלה,\u0006 האחרים\u0005]\u0006 \u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בכל אחד לחוד.","כיון שדובר בקרבנות הצבור הדוחים את הטומאה דנים בגמרא בעיקרי ההלכות הללו. ומקדימים כי \u0003סברוה\u0004 \u0005[היו\u0006 הלומדים \u0005סבורים]\u0006 תחילה \u0003דלכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003טומאה דחויה היא בציבור\u0004 כלומר שאיסור הטומאה בקרבנות ציבור הותר בקושי וכאילו רק נדחתה הטומאה מפני חובה אחרת, אבל בעצם עדיין יש איסור טומאה בענין זה. ולכן \u0003בעיא\u0004 \u0005[צריכה]\u0006 עדיין \u0003ציץ\u0004 של הכהן הגדול \u0003לרצות\u0004 על הקרבת קרבנות בטומאה.","\u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003תנא\u0004 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר טומאה הותרה\u0004 לגמרי \u0003בציבור\u0004 ולגבי הציבור אין לטומאה משמעות במקדש \u0003אלא ר' יהודה, דתניא\u0004 [\u0005ש\u0006כן \u0005שנינו\u0006 בברייתא]: \u0003ציץ\u0004 של כהן גדול, \u0003בין שישנו על מצחו ובין שאינו על מצחו — מרצה,\u0004 אלו \u0003דברי ר' שמעון. ר' יהודה אומר: עודיהו\u0004 \u0005[בעודו]\u0006 \u0003על מצחו — מרצה, אין עודיהו על מצחו — אינו מרצה\u0004 כפי הנראה לכאורה מן הכתוב \"והיה על מצח אהרן ונשא אהרן את עוון הקדשים אשר יקדישו בני ישראל\" (שמות כח, לח).","\u0003אמר לו ר' שמעון\u0004 לר' יהודה: \u0003כהן גדול ביום הכפורים יוכיח, שאינו על מצחו\u0004 של הכהן \u0003ומרצה\u0004 על קרבנות הציבור שהוקרבו בו בטומאה. שהרי הכהן הגדול ביום הכיפורים לבוש חלק מן היום רק בארבעה בגדי הלבן ולא בשאר בגדי הזהב, וממילא גם לא בציץ,","\u0003אמר לו\u0004 ר' יהודה: \u0003הנח ליום הכפורים שטומאה הותרה\u0004 לגמרי \u0003בציבור\u0004 ואין הציץ מרצה אלא על קרבן יחיד שהובא בטומאה, ולכאורה \u0003מכלל\u0004 הדברים נלמד ש\u0003ר' שמעון סבר: טומאה דחויה היא בציבור\u0004 ולא הותרה לגמרי, ודרוש הציץ לכפר עליה.","ועוד סברו הלומדים כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אין הציץ מרצה על אכילות\u0004 של בשר קרבן שנטמא, ואינו מרצה אלא על הקרבת קרבן בטומאה, \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003תנא\u0004 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר\u0004 ש\u0003הציץ מרצה על אכילות אלא ר' אליעזר, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אליעזר אומר: הציץ מרצה על אכילות\u0004 של קרבן שנטמא, \u0003ר' יוסי אומר: אין הציץ מרצה על אכילות.\u0004","ומעתה, אם נקבל את ההנחות הללו, שהיו פשוטות לבני בית המדרש, אם כן \u0003נימא\u0004 \u0005[נאמר]\u0006 כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' יהושע\u0004 היא, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"ועשית עלתיך הבשר והדם על\u0004 מזבח ה' אלהיך ודם זבחיך ישפך על מזבח ה' אלהיך והבשר תאכל\u0003\"\u0004 (דברים יב, כז), ובפירוש הפסוק נחלקו חכמים, \u0003ר' יהושע אומר: אם אין דם\u0004 ראוי כגון שאבד או נטמא \u0003— אין\u0004 ה\u0003בשר\u0004 מוקרב למזבח, וכן \u0003אם אין בשר\u0004 ראוי כגון שנטמא או אבד \u0003— אין\u0004 זורקין את ה\u0003דם\u0004 ואין מרצה.","\u0003ר' אליעזר אומר: דם\u0004 מרצה \u0003אף על פי שאין בשר\u0004 קרב, \u0003שנאמר: \"ודם זבחיך ישפך\"\u0004 מכל מקום, שהוא עיקר הקרבן, \u0003ומה אני מקיים\u0004 ומסביר את ההשוואה וההיקש \u0003\"ועשית עלתיך הבשר והדם\" — לומר לך מה דם בזריקה\u0004 על המזבח \u0003אף בשר בזריקה.\u0004","\u0003הוי אומר\u0004 ולמד מכאן: \u0003לול\u0004 (חלל, רווח) \u0003קטן יש בין כבש למזבח\u0004 שלא היה הכבש צמוד לגמרי למזבח אלא חלל קטן היה ביניהם ומעל אותו חלל היו זורקים את הקרבן על המערכה ולא די בהולכתו והנחתו בלבד, שיש לקיים בו מצות זריקה למזבח.","ושואלים: \u0003ור' יהושע נמי\u0004 \u0005[גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי כתוב]\u0006 \u0003\"ודם זבחיך ישפך\",\u0004 ומשמע שהוא העיקר! \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003הא כתיב גביה\u0004 \u0005[הרי כתוב ליד זה]\u0006 \u0003\"והבשר תאכל\"\u0004 ומשמע שהבשר חשוב לקרבן כמו הדם."],["ושואלים: \u0003והני תרי קראי\u0004 \u0005[ואותם שני כתובים]\u0006 \u0003למה לי?\u0004 שהרי לשיטת ר' יהושע נמצא כי אותו דין עצמו חוזר פעמיים באותו פסוק! ומשיבים: \u0003חד\u0004 \u0005[אחד]\u0006 \u0003בעולה, וחד\u0004 \u0005[ואחד]\u0006 \u0003בשלמים.\u0004 ומעירים: \u0003וצריכא\u0004 \u0005[ונצרכו]\u0006 שניהם, \u0003דאי כתב רחמנא\u0004 \u0005[שאילו\u0006 היתה \u0005כותבת התורה]\u0006 רק \u0003בעולה, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003עולה היא דחמירא\u0004 \u0005[שחמורה],\u0006 \u0003שכן כליל\u0004 כולה למזבח, \u0003אבל שלמים\u0004 ש\u0003לא חמירי\u0004 \u0005[חמורים],\u0006 שרוב בשרם נאכל לכהנים או לבעלים, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 שאין בשרם מעכב.","\u0003ואי כתב רחמנא\u0004 \u0005[ואם\u0006 היתה \u0005כותבת התורה]\u0006 \u0003שלמים, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003אדרבה,\u0004 שלמים יש חשיבות יתירה לבשרם משום \u0003דאית בהו\u0004 \u0005[שיש בהם]\u0006 \u0003שתי אכילות\u0004 'אכילת' האימורים על המזבח, ואכילת הבעלים והכהנים את שאר הבשר. \u0003אבל עולה דלית\u0004 \u0005[שאין]\u0006 \u0003בה שתי אכילות\u0004 אלא רק 'אכילת' מזבח, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בשני המקרים.","ושואלים: \u0003ור' אליעזר נמי\u0004 \u0005[גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי כתוב]\u0006 \u0003\"והבשר תאכל\"\u0004 משמע שזה תנאי הכרחי! \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]:\u0006 \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005צריך לו]\u0006 ללמדנו \u0003שאין הבשר\u0004 של קרבן \u0003מותר באכילה עד שיזרק הדם.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שלזה בא הכתוב, \u0003אימא כוליה להכי\u0004 \u0005[אמור\u0006 ש\u0005כל\u0006 הפסוק \u0005כולו, לכך\u0006 ללמדנו דבר זה\u0005]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ואם כן, הלכה זו שזורקים את ה\u0003דם אף על פי שאין שם בשר\u0004 שאין הבשר ראוי להקרבה מחמת טומאתו או שאבד \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006","\u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 ר' אליעזר: \u0003אם כן נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"הבשר תאכל\" והדר\u0004 \u0005[ואחר כך]\u0006 \u0003\"ודם זבחיך ישפך\", כדכתיב ברישא\u0004 \u0005[כפי שכתוב בראש\u0006 הפסוק\u0005]\u0006 \u0003\"ועשית עלתיך הבשר והדם\"\u0004 קודם בשר ואחר כך דם, \u0003מאי שנא דאקדמיה\u0004 \u0005[במה שונה שהקדים]\u0006 הכתוב \u0003ל\"דם זבחיך\" — שמע מינה\u0004 \u0005[למד מכאן]\u0006 שני דברים, ראשית ש\u0003דם\u0004 מרצה \u0003אף על פי שאין בשר, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 גם \u0003שאין הבשר מותר באכילה עד שיזרק הדם.\u0004","ושואלים: \u0003ור' יהושע\u0004 מנין לו ש\u0003אין הבשר מותר באכילה עד שיזרק הדם?\u0004 ומשיבים: לשיטתו \u0003קל וחומר הוא, ומה אימורין דכי ליתנהו לא מעכבי\u0004 \u0005[שכאשר אינם\u0006 כגון שאבדו או נטמאו, לדעת הכל \u0005אינם מעכבים]\u0006 את הקרבן, \u0003כי איתנהו\u0004 \u0005[כאשר ישנם] —\u0006 \u0003מעכבי\u0004 \u0005[\u0006הם \u0005מעכבים]\u0006 את אכילת הבשר, \u0003דם דכי ליתיה\u0004 \u0005[שכאשר אינו],\u0006 כאשר אבד או נטמא — הוא \u0003מעכב, כי איתיה\u0004 \u0005[כאשר ישנו] —\u0006 \u0003לא כל שכן\u0004 שהוא מעכב את המשך העבודה בקרבן ואכילתו בטרם נזרק.","ושואלים: \u0003ור' אליעזר,\u0004 כיון שיש קל וחומר זה מה טעם שכתב הדבר מפורש במקרא? ומשיבים: \u0003מילתא דאתיא\u0004 \u0005[דבר שבא,\u0006 נלמד\u0005]\u0006 \u0003בקל וחומר טרח וכתב לה קרא\u0004 \u0005[אותו המקרא],\u0006 שגם כשיכולים אנו ללמוד את הדבר בעצמנו מקל וחומר, פעמים נכתב הדבר במפורש לחיזוק הדבר. ושואלים: \u0003ור' יהושע\u0004 מה עונה הוא על טענה זו? ומשיבים: \u0003כל היכא דאיכא למדרש\u0004 \u0005[מקום שיש לדרוש\u0006 את הכתובים\u0005] —\u0006 \u0005—\u0006 \u0003דרשינן\u0004 \u0005[דורשים אנו]\u0006 אותם לצורך לימוד חדש, ואיננו אומרים שהכתוב פירש דבר שאינו הכרחי.","ולאחר הקדמות אלה, \u0003השתא לימא מתניתין\u0004 \u0005[עכשיו נאמר\u0006 ש\u0005משנתנו]\u0006 היא ש\u0003לא כר' יהושע,\u0004 ש\u0003כיון\u0004 ש\u0003אמר בעינן תרתי\u0004 \u0005[צריכים שניהם]\u0006 גם בשר וגם דם הקרבן, ולפי הנחתנו כי \u0003ציץ\u0004 על \u0003אכילות\u0004 של טומאה \u0003לא מרצה,\u0004 ואם כן בקרבנות ציבור אלה יש רק את הדם שהוא אחד מן המתירים, ואם כן \u0003היכי אתי\u0004 \u0005[כיצד יבואו]\u0006 אלה \u0003בטומאה,\u0004 כשאסור לאכול את הבשר?","ודוחים \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כי משנתנו כשיטת \u0003ר' יהושע, אלא קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' יהושע: הציץ מרצה על העולין\u0004 על אימורי הקרבן שהם עולים למזבח ואפילו נטמאו, וכיון שריצה על אכילת המזבח יכול כבר הדם להיזרק.","ומקשים: \u0003הא תינח\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 לגבי ה\u0003זבחים\u0004 שבקרבנות הציבור \u0003דאיכא\u0004 \u0005[שיש]\u0006 בהם חלקים ה\u0003עולין\u0004 למזבח, \u0003אלא עומר ושתי הלחם דליכא\u0004 \u0005[שאין]\u0006 מהם חלקים ה\u0003עולין\u0004 על המזבח, אלא נאכל לכהנים, פרט לקומץ שדינו במנחה כדין זריקת דם בקרבן, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003אמרי\u0004 \u0005[אומרים\u0006 בתשובה\u0005]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' יהושע נמי\u0004 \u0005[גם כן]\u0006 \u0003דבעינן תרתי\u0004 \u0005[שצריכים שנים]\u0006 \u0003בזבחים\u0004 אמר, אבל \u0003במנחות לא אמר.\u0004","ותוהים: \u0003ו\u0004כי \u0003במנחות לא אמר\u0004 שצריכים גם את הקומץ וגם את גוף המנחה? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נטמאו שיריה\u0004 של מנחה (כל מה שנותר לאחר הפרשת הקומץ), או \u0003אבדו שיריה — כמדת\u0004 (לשיטת) \u0003ר' אליעזר\u0004 האומר \"דם אף על פי שאין בשר\" — \u0003כשרה, כמדת ר' יהושע — פסולה.\u0004","ודוחים: דעה זו היא \u0003כמדת ולא כמדת,\u0004 כלומר שהדבר הוא בהתאם לשיטה דומה אבל אינה בדיוק שיטתו. ומפרטים: \u0003כמדת ר' יהושע, דבעינן תרתי\u0004 \u0005[שצריכים שתים]\u0006 גם בשר וגם דם, ואם היה ממשיך כשיטתו, גם במנחות היה אומר כן. אבל \u0003לא כמדת ר' יהושע,\u0004 ש\u0003אילו ר' יהושע\u0004 עצמו \u0003בזבחים אמר\u0004 כן, \u0003במנחות — לא אמר, ואילו האי תנא\u0004 \u0005[אותו תנא]\u0006 של משנה זו שהמשיך את שיטת ר' יהושע \u0003סבר: אפילו במנחות.\u0004","ושואלים: \u0003ומנו האי תנא דקאי כוותיה\u0004 \u0005[ומי הוא תנא זה שעומד,\u0006 שסובר \u0005כשיטתו]\u0006 \u0003ומחמיר טפי מיניה\u0004 \u0005[יותר ממנו],\u0006 שתמוה שתמצא שיטה כזו. \u0003ועוד, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003אמר ר' יוסי: רואה אני\u0004 כנכונים \u0003את דברי ר' אליעזר במנחות ובזבחים, ודברי ר' יהושע בזבחים ובמנחות,\u0004","ומפרטים: \u0003דברי ר' אליעזר בזבחים, שהיה אומר:\u0004 שה\u0003דם\u0004 מרצה \u0003אף על פי שאין\u0004 שם \u0003בשר. ודברי ר' יהושע בזבחים, שהיה אומר: אם אין דם אין בשר אם אין בשר אין דם. ודברי ר' אליעזר במנחות, שהיה אומר: קומץ אף על פי שאין שירים,\u0004 ו\u0003דברי ר' יהושע במנחות, שהיה אומר: אם אין קומץ\u0004 כשר \u0003אין שירים\u0004 עולים, \u0003אם אין שירים אין קומץ.\u0004 ומכאן משמע שר' יהושע כמחלוקתו בזבחים כן מחלוקתו במנחות!","\u0003אלא\u0004 יש לדחות את התירוץ הקודם, ולומר: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' יהושע הציץ מרצה\u0004 גם \u0003על\u0004 אימורי הקרבנות \u0003העולין\u0004 וגם \u0003על האכילות,\u0004 שלא כפי שהנחנו מתחילה, וממילא אף הקרבנות האלה יכולים להיקרב.","ותוהים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003כמדת ר' יהושע פסולה\u0004 שכיון שנטמא שוב אינו בא לידי פסול. ומשיבים: לא נאמרה שיטה זו אלא על \u0003אבוד ושרוף,\u0004 אבל אם נטמאו, הציץ מרצה והקרבן כשר.","ומקשים: \u0003אלא נטמא,\u0004 אותה הלכה למנחות שנטמאו, \u0003ל\u0004שיטת \u0003מאן קתני\u0004 \u0005[מי שנה\u0006 דבר זה\u0005]?\u0006 אם \u0003ל\u0004שיטת \u0003ר' אליעזר, פשיטא\u0004 \u0005[פשוט]\u0006 שהוא מתיר, \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003יש לומר\u0004 ש\u0003אבוד ושרוף דליתנהו\u0004 \u0005[שאינם]\u0006 מצויים כלל, \u0003מכשיר ר' אליעזר, נטמא דאיתיה\u0004 \u0005[שישנו]\u0006 במציאות אלא רק נפסל, \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שמתיר? \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שהחידוש הוא לשיטת \u0003ר' יהושע, וקתני\u0004 \u0005[ושנינו]\u0006 \u0003פסולה.\u0004","\u0003ועוד, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' יהושע אומר: כל זבחים שבתורה, בין שנטמא בשר וחלב\u0004 של הקרבן שהוא חלק העולה למזבח \u0003קיים, ובין שנטמא חלב ובשר קיים — זורק את הדם.\u0004 ונלמד מכאן: \u0003אבל נטמאו תרווייהו\u0004 \u0005[שניהם]\u0006 \u0003לא,\u0004 אינו זורק את הדם. \u0003אלמא קסבר\u0004 \u0005[מכאן שסבור הוא]\u0006 \u0003ר' יהושע אין הציץ מרצה על העולין\u0004 למזבח \u0003ולא על האכילות!\u0004","\u0003אלא\u0004 נדחו התירוצים הקודמים, ונאמר: \u0003לעולם\u0004 אף כ\u0003ר' יהושע היא מתניתין\u0004 \u0005[משנתנו],\u0006 \u0003ולא קשיא\u0004 \u0005[קשה]\u0006 \u0003כאן\u0004 שקבע ר' יהושע שיהיו שניהם ראויים להקרבה גם הבשר וגם הדם — הרי זה \u0003לכתחלה, כאן\u0004 במשנתנו — ב\u0003דיעבד,\u0004 שאם היה רק אחד מהם ראוי והובא למזבח, הריהו כשר. \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' יהושע\u0004 שאין מקריבים — \u0003לכתחלה\u0004 אמר, אבל ב\u0003דיעבד לא\u0004 אמר.","\u0003ומנא תימרא דשני ליה\u0004 \u0005[ומנין תאמר ששונה לו]\u0006 \u0003לר' יהושע בין לכתחלה לדיעבד — דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003נטמא בשר או שנפסל\u0004 במגע טבול יום \u0003או שיצא חוץ לקלעים\u0004 ונפסל על ידי כך, \u0003ר' אליעזר אומר: יזרק\u0004 הדם וכשר, \u0003ר' יהושע אומר: לא יזרק. ומודה ר' יהושע שאם זרק — הורצה.\u0004","את התירוץ הזה דוחים בכמה צורות: \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד]\u0006 הלשון \u0003\"פסולה\"\u0004 אף ב\u0003דיעבד משמע,\u0004 לא רק שאין לעשות כך מלכתחילה, אלא אף שאם עשה כן פסול. \u0003ועוד, \"חמשה דברים באין\"\u0004 שנאמר במשנתנו, סגנון זה \u0003לכתחלה משמע\u0004"],["\u0003אלא, לא קשיא\u0004 \u0005[קשה]\u0006 \u0003כאן\u0004 שאמר שלכתחילה פסולה — הוא בקרבן \u0003יחיד, כאן\u0004 שאפילו לכתחילה מקריבים — הוא בקרבן \u0003ציבור.\u0004","ושואלים: \u0003נימא מתניתין\u0004 \u0005[\u0006האם \u0005נאמר שמשנתנו]\u0006 אינה כשיטת \u0003ר' יוסי? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 ברייתא\u0005]\u0006 \u0003ר' אליעזר אומר: הציץ מרצה\u0004 גם \u0003על אכילות\u0004 של קרבנות בטומאה. \u0003ור' יוסי אומר: אין הציץ מרצה על אכילות\u0004 אלא על הקרבת הקרבן בטומאה בלבד.","ומסבירים את השאלה: \u0003קא סלקא דעתך\u0004 \u0005[עלה על דעתנו]\u0006 לומר כי \u0003מדקאמר\u0004 \u0005[ממה שאמר]\u0006 \u0003ר' יוסי: אין הציץ מרצה על אכילות כ\u0004שיטת \u0003ר' יהושע סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ש\u0003אמר בעינן תרתי\u0004 \u0005[צריכים אנו שני\u0006 דברים\u0005]\u0006 שכדי שיעלה הקרבן לרצון, צריך שיהיו גם הבשר וגם הדם ראויים להקרבה. \u0003נימא השתא מתניתין\u0004 \u0005[נאמר עכשיו כי משנתנו]\u0006 היא ש\u0003לא כ\u0004שיטת \u0003ר' יוסי,\u0004 שאם לא צריך את שניהם, אם כן לשם מה צריך ריצוי ציץ לאכילות, הרי די במה שמרצה על זריקת הדם?","ודוחים: \u0003לא, ר' יוסי כר' אליעזר סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ש\u0003אמר\u0004 שדי באחד מהם, ולכן כשיש את \u0003דם\u0004 הקרבן \u0003אף על פי שאין בשר — מרצה.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003למאי הלכתא\u0004 \u0005[לאיזה\u0006 צד של \u0005הלכה]\u0006 נתכוון ר' יוסי באמרו \u0003אין הציץ מרצה על אכילות?\u0004 הרי גם אם אינו מרצה, מכל מקום אפשר להקריב את הקרבן! ודוחים: \u0003וליטעמיך\u0004 \u0005[ולשיטתך]\u0006 \u0003ר' אליעזר\u0004 עצמו ש\u0003אמר הציץ מרצה\u0004 אף על אכילות, \u0003כיון\u0004 ש\u0003אמר דם אף על פי שאין בשר,\u0004 לשיטתו \u0003הציץ מרצה על אכילות למאי הלכתא\u0004 \u0005[ל\u0006צורך \u0005איזו הלכה]\u0006 אמר זאת? שאם השיקול היחידי הוא ענין ריצוי הקרבן, אם כן, גם אם אין הציץ מרצה יצא ידי חובה בדם לחוד!","\u0003אלא\u0004 ודאי הכוונה היא לענין אחר, \u0003למיקבעיה\u0004 \u0005[ל\u0006צורך \u0005קביעתו]\u0006 \u0003בפיגול ולאפוקי\u0004 \u0005[ו\u0006כן \u0005להוציאו]\u0006 \u0003מידי מעילה,\u0004 שכשם שאין הקרבן נקבע לרצון אלא אם כן אין בו פסול כלשהו, כך אינו נקבע לפיגול (אם חשב בו מחשבת חוץ לזמנו) אלא אם כן אין בו כל פסול אחר. וכך יש להבין את המחלוקת ש\u0003ר' אליעזר סבר: מרצה ציץ עילויה\u0004 \u0005[עליו]\u0006 על הבשר שנטמא \u0003ומשוי ליה\u0004 \u0005[ועושה אותו]\u0006 \u0003כ\u0004בשר \u0003טהור\u0004 שלא היה בו פסול אחר אף שאסור באכילה מחמת טומאתו, ולכן \u0003קבע ליה\u0004 \u0005[קובע אותו]\u0006 \u0003בפיגול\u0004\u0005,\u0006 ובדומה לכך אף \u0003מפיק ליה\u0004 \u0005[מוציא אותו]\u0006 \u0003מידי מעילה\u0004 שמועלים בקרבן (קדשי קדשים) עד שעה שנרצה לכפר, ומאז ואילך שוב אין מועלים בו, ועל ידי ריצוי הציץ נחשב הבשר הטמא גם הוא כעולה לרצון וממילא אף יוצא מידי מעילה.","ואילו \u0003ר' יוסי סבר: לא מרצה ציץ עילויה\u0004 \u0005[עליו],\u0006 \u0003ולא משוי ליה\u0004 \u0005[עושה אותו]\u0006 \u0003כטהור, ולא קבע ליה\u0004 \u0005[\u0006יכול \u0005לקובעו]\u0006 \u0003בפיגול, ולא מפיק ליה\u0004 \u0005[מוציא אותו]\u0006 \u0003מידי מעילה,\u0004 ועל כל פנים אין מקום לקושיה שהקשינו.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על מסקנתנו זו \u0003רב מרי: נהי נמי\u0004 \u0005[נניח גם כן]\u0006 ש\u0003ר' יוסי סבר כר' אליעזר\u0004 שעולה הקרבן לרצון גם בדם הקרבן לחוד אם נטמא הבשר עצמו \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003זבחים\u0004 שיש בהם שני מתירים, \u0003איכא\u0004 \u0005[יש]\u0006 לפחות דבר אחד שבעטיו הוא עולה לרצון, שהוא ה\u0003דם\u0004 שריצה הציץ על טומאתו ועל ידו עולה הקרבן לרצון. ב\u0003עומר נמי\u0004 \u0005[גם כן]\u0006 \u0003איכא\u0004 \u0005[יש]\u0006 \u0003קומץ\u0004 שהציץ מכפר עליו ומכשירו, וב\u0003לחם הפנים נמי\u0004 \u0005[גם כן]\u0006 יש \u0003בזיכין\u0004 שמתירים את הלחם כמו הקומץ במנחה,","\u0003אלא שתי הלחם מאי איכא למימר\u0004 \u0005[מה יש לומר\u0006 בהם\u0005]?\u0006 הרי עשויים הם לאכילה בלבד!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003לקרב עמהן\u0004 שהכוונה ששתי הלחם מצטרפים עם קרבן שני הכבשים הקרב עמהם, שאף ששתי הלחם עצמם טמאים, מכל מקום דם הכבשים שעולה לרצון אחר שריצה הציץ על טומאתם מתיר אף אותם, אבל הרי \u0003היינו שלמי ציבור\u0004 שנמנו לעצמם במשנה, \u0003ואם כן הוו להו ארבעה\u0004 \u0005[הרי הם ארבעה\u0006 דברים\u0005]\u0006 במשנה \u0003ואנן חמשה תנן\u0004 \u0005[ואנחנו חמשה שנינו]\u0006 ובמנין זה שתי הלחם ושלמי ציבור נמנים כל אחד לעצמו!","\u0003אלא\u0004 יש לדחות מה שאמרנו, ונאמר כי \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' יוסי: טמאה הותרה בציבור\u0004 ללא היתר ציץ ומטעם זה קרבים שתי הלחם.","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בענין טהרת הכהן הגדול לצורך יום הכיפורים וכן הכהן העושה את הפרה האדומה שמפרישים אותם שבעה ימים קודם לכן כדי להיטהר ואמרו כי \u0003אחד זה ואחד זה מזין עליו כל שבעה\u0004 ימי הפרישה \u0003מכל חטאות\u0004 (אפר פרה האדומה) \u0003שהיו שם\u0004 במקדש שאם נטמא באחד הימים בטומאת מת נטהר על ידי הזיית מי חטאת, אלו \u0003דברי ר' מאיר, ר' יוסי אומר: אין מזין עליו אלא שלישי ושביעי בלבד\u0004 שמא נטמא בדיוק ביום לפני שפרש לטהרה, ואין חוששים ביותר מכן.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 ש\u0003סבר ר' יוסי טומאה הותרה בציבור למה לי הזאה כלל\u0004 הרי קרבן יום הכיפורים ופרה אדומה הם קרבן ציבור והותרה טומאתו? \u0003אלא\u0004 אין לקבל ביאור זה ו\u0003מחוורתא מתניתין\u0004 \u0005[מחוור,\u0006 ברור, \u0005כי משנתנו]\u0006 ש\u0003לא כר' יוסי.\u0004","ביחס לדברי ר' יוסי שהובאו קודם, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי\u0004 בתמיהה: \u0003ור' יוסי שטרא מזכי לבי תרי הוא\u0004 \u0005[שטר מזכה הוא לשניים\u0006 גם לתובע וגם לנתבע\u0005]\u0006 שהוא מסכים לשתי הדעות הסותרות?! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יוסי: רואה אני\u0004 כנכונים \u0003את דברי ר' אליעזר בזבחים, ו\u0004את \u0003דברי ר' יהושע בזבחים, ו\u0004את \u0003דברי ר' אליעזר במנחות ו\u0004את \u0003דברי ר' יהושע במנחות.\u0004","ומפרטים: את \u0003דברי ר' אליעזר בזבחים, שהיה אומר:\u0004 זורקים את ה\u0003דם אף על פי שאין בשר,\u0004 וכן את \u0003דברי ר' יהושע בזבחים, שהיה אומר: אם אין דם אין בשר, אם אין בשר אין דם\u0004 וכן רואה את \u0003דברי ר' אליעזר במנחות שהיה אומר: קומץ\u0004 מרצה \u0003אף על פי שאין שם שירים\u0004 שאבדו או נטמאו, וכן \u0003דברי ר' יהושע במנחות, שהיה אומר: אם אין שם שירים אין קומץ, אם אין קומץ אין שירים\u0004 וכל דבריו סותרים זה את זה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: אין הכוונה שפסק הלכה כשתי דעות סותרות, אלא \u0003מסתברא קאמר\u0004 \u0005[מסתברים\u0006 הדברים, רצה \u0005לומר]\u0006 כיצד? \u0003כי קאי\u0004 \u0005[כאשר עמד,\u0006 היה עוסק\u0005]\u0006 \u0003בזבחים אמר: מסתברא כי היכי דפליגי\u0004 \u0005[מסתבר, כפי ש\u0006הם \u0005חלוקים]\u0006 \u0003בזבחים, פליגי נמי\u0004 \u0005[חלוקים\u0006 הם \u0005גם]\u0006 \u0003במנחות, קאי\u0004 \u0005[\u0006וכאשר \u0005עמד]\u0006 \u0003במנחות אמר: מסתברא כי היכי דפליגי\u0004 \u0005[מסתבר כשם ש\u0006הם \u0005חלוקים]\u0006 \u0003במנחות פליגי נמי\u0004 \u0005[חלוקים\u0006 הם \u0005גם]\u0006 \u0003בזבחים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003התינח\u0004 \u0005[\u0006דבר \u0005זה נוח,\u0006 נניח\u0005]\u0006 \u0003כי קאי\u0004 \u0005[כאשר עמד\u0006 עסק\u0005]\u0006 \u0003בזבחים אמר: מסתברא כי היכי דפליגי\u0004 \u0005[מסתבר\u0006 ש\u0005כפי ש\u0006הם \u0005חלוקים]\u0006 \u0003בזבחים, פליגי נמי\u0004 \u0005[חלוקים\u0006 הם \u0005גם כן]\u0006 \u0003במנחות,\u0004 ש\u0003עיקר קראי כי כתיבי\u0004 \u0005[המקראות הכתובים]\u0006 בענין זה \u0005—\u0006 \u0003בזבחים כתיבי\u0004 \u0005[\u0006הם \u0005כתובים].\u0006 \u0003אלא, כי קאי\u0004 \u0005[כאשר היה עומד\u0006 עוסק\u0005]\u0006 \u0003במנחות ואמר: מסתברא כי היכי דפליגי\u0004 \u0005[מסתבר\u0006 ש\u0005כפי שהם חלוקים]\u0006 \u0003במנחות פליגי נמי\u0004 \u0005[חלוקים\u0006 הם \u0005גם כן]\u0006 \u0003בזבחים?\u0004 \u0005—\u0006 אי אפשר לומר כן, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003עיקר קראי\u0004 \u0005[המקראות]\u0006 \u0003בזבחים הוא דכתיבי\u0004 \u0005[שכתובים]\u0006 וברור לו שנחלקו בזבחים.","\u0003אלא\u0004 נדחה תירוץ זה, \u0003ולא קשיא\u0004 \u0005[קשה]\u0006 וכך יש לתרץ ולבאר סתירת דבריו: שכשאמר \u0003רואה אני את דברי ר' אליעזר\u0004 לא אמר כן אלא \u0003בנטמא,\u0004 וכשאמר \u0003דברי ר' יהושע\u0004 לא אמר כן אלא \u0003באבוד ושרוף.\u0004 ולפי הסבר זה הסכים למקצת דברי ר' אליעזר ומקצת דברי ר' יהושע.","ושואלים: \u0003בנטמא מאי טעמא\u0004 \u0005[מה הטעם]\u0006 אמר שהוא רואה את דברי ר' אליעזר — \u0003משום דמרצי\u0004 \u0005[שמרצה]\u0006 \u0003ציץ\u0004 על הטומאה. אך זה אינו אפשרי, \u0003הא שמעת ליה\u0004 \u0005[הרי שמעת אותו]\u0006 את \u0003ר' יוסי\u0004 ש\u0003אמר: אין הציץ מרצה על אכילות!\u0004","\u0003אלא\u0004 יש לדחות תירוץ זה ולומר הסבר אחר בסתירת דבריו, \u0003לא קשיא\u0004 \u0005[קשה]\u0006 ויש להבין כך: \u0003רואה אני את דברי ר' אליעזר\u0004 בקרבן \u0003ציבור, רואה אני את דברי ר' יהושע\u0004 בקרבן \u0003יחיד,\u0004","ושוב מקשים: \u0003בציבור מאי טעמא\u0004 \u0005[מה הטעם]\u0006 מסכים הוא לדברי ר' אליעזר \u0003משום\u0004 ש\u0003טומאה הותרה בציבור\u0004 והסבר זה יש לדחות מפני סיבות שונות \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד]\u0006 כנגד זה: ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את \u0003ר' יוסי\u0004 ש\u0003אמר טומאה דחויה היא\u0004 בלבד \u0003בציבור\u0004 ולא הותרה לגמרי כפי שהוכחנו קודם, \u0003ועוד: אי\u0004 \u0005[אם]\u0006 מדובר \u0003בציבור,\u0004 וכי \u0003ר' אליעזר\u0004 לבדו \u0003מכשיר ולא ר' יהושע?\u0004"],["\u0003הא אמרת\u0004 \u0005[הרי\u0006 כבר \u0005אמרת]\u0006 \u0003בציבור אפילו ר' יהושע מודה.\u0004","\u0003אלא\u0004 כך יש ליישב: גם לר' אליעזר וגם לר' יהושע מדובר בקרבן יחיד, אלא ש\u0003רואה אני את דברי ר' אליעזר בדיעבד, ודברי ר' יהושע לכתחלה.\u0004 ומקשים: \u0003דיעבד אפילו ר' יהושע נמי\u0004 \u0005[גם כן]\u0006 \u0003מודה הוא, דקתני\u0004 \u0005[ששנינו]:\u0006 \u0003מודה ר' יהושע שאם זרק\u0004 את הדם — \u0003הורצה\u0004 ויצא בו.","ומשיבים: \u0003הא\u0004 \u0005[זה,\u0006 שמודה\u0005]\u0006 הוא \u0003בטומאה, הא\u0004 \u0005[זה\u0006 שנחלק בו\u0005]\u0006 \u0003באבוד ושרוף.\u0004 ומסבירים: \u0003כי קתני\u0004 \u0005[כאשר שנינו]\u0006 \u0003מודה ר' יהושע שאם זרק הורצה\u0004 מדובר כאן \u0003בנטמא, אבל באבוד ושרוף — לא,\u0004 ואפילו בדיעבד. \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' יוסי רואה אני את דברי ר' אליעזר בדיעבד\u0004 הרי היא \u0003באבוד ושרוף.\u0004 שבזה לא הודה ר' יהושע.","\u0003נטמא\u0004 ה\u0003בשר\u0004 של קרבן הפסח \u0003וחלב קיים\u0004 בטהרתו ואפשר להקטירו על המזבח — \u0003אינו זורק את הדם.\u0004 ולהיפך: \u0003נטמא החלב והבשר קיים — זורק את הדם\u0004 שהרי ראוי הבשר לאכילה. וכן הדין בקרבן פסח, שעיקרו לאכילה. למנויים עליו. אבל בשאר ה\u0003מוקדשים\u0004 (קרבנות) \u0003אינו כן, אלא אף על פי שנטמא הבשר והחלב קיים — זורק את הדם,\u0004 שהרי מקצת הקרבן נמצא.","\u0003אמר רב גידל אמר רב:\u0004 כשהבשר נטמא, \u0003אם זרק\u0004 בכל זאת את הדם — \u0003הורצה,\u0004 ואינו צריך לעשות פסח שני. ומקשים: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 אכילת קרבן הפסח, ולא היתה כאן! ומשיבים: \u0003אכילה לא מעכבא\u0004 \u0005[מעכבת]\u0006 וגם אם אין אפשרות לאכול — הורצה.","ומקשים: \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"\u0004ואם ימעט הבית מהיות משה ולקח הוא ושכנו הקרוב אל ביתו במכסת נפשות \u0003איש לפי אכלו\"\u0004 (שמות יב, ד) הרי שהקפידה על אכילת הפסח?! ודוחים: פסול זה נאמר \u0003למצוה\u0004 בלבד. שלכתחילה צריך לעשות כן, אבל בדיעבד אינו מעכב.","ושואלים: \u0003ולעכב לא\u0004 נאמר? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"במכסת\u0004 נפשות תכוסו על השה \u0003\"\u0004\u0003מלמד שאין הפסח נשחט אלא למנויו\u0004 שנכנסו מראש למכסת הנפשות. \u0003יכול שחטו שלא למנויו יהא\u0004 רק \u0003כעובר על המצוה\u0004 אבל \u0003כשר\u0004 בדיעבד — \u0003תלמוד לומר: \"איש לפי אכלו תכסו\" הכתוב שנה עליו\u0004 כדי \u0003לעכב.\u0004","\u0003ואיתקש\u0004 \u0005[והוקשו,\u0006 הושוו\u0005]\u0006 בכתוב \u0003אוכלין\u0004 (הראויים לאכול, ולא חולה או זקן) \u0003למנויין,\u0004 ולכן הפסול במנויין שאינם אוכלים פוסל גם באוכלים, וקשה לרב!","\u0003אלא\u0004 יש לומר כי רב ש\u0003אמר\u0004 דבריו \u0003כר' נתן\u0004 הוא שאמרם, ש\u0003אמר\u0004 ר' נתן: \u0003אכילת פסחים לא מעכבא\u0004 \u0005[מעכבת]\u0006 והיא מצוה לעצמה ואינה מעכבת שיצא ידי חובה.","ושואלים: \u0003הי\u0004 \u0005[איזה]\u0006 \u0003ר' נתן?\u0004 כלומר: היכן פירש שיטתו זו? \u0003אילימא הא\u0004 \u0005[אם תאמר\u0006 דבר \u0005זה]\u0006 של \u0003ר' נתן. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' נתן אומר: מניין שכל ישראל יוצאין\u0004 בדיעבד בקרבן \u0003פסח אחד — תלמוד לומר: \"ושחטו אתו כל קהל עדת ישראל בין הערבים\"\u0004 (שמות יב, ו) ושאל: \u0003וכי כל הקהל שוחטין\u0004 ומצוה שכל יחיד ישחט? \u0003והלא אין שוחט אלא אחד\u0004 בשביל כל החבורה! \u0003אלא\u0004 שימוש הלשון שבפסוק זה \u0003מלמד שכל ישראל יוצאין בפסח אחד\u0004 ונחשב כאילו כולם שחטו אותו וכולם יוצאים בו, אף שאין כולם יכולים לאכול ממנו כזית.","ודוחים: אינו דומה, \u0003דילמא שאני התם\u0004 \u0005[שמא שונה שם]\u0006 \u0003דאי ממשכי הני חזי להני, ואי ממשכי הני חזי להני\u0004 \u0005[אם ימשכו אלה\u0006 חלק מן המנויים עליו את ידיהם ממנו \u0005יהיה ראוי לאלה, ואם ימשכו אלה יהיה ראוי לאלה]\u0006 שאף שאין כל ישראל כאחד יכולים לאכול את קרבן הפסח הזה, מכל מקום ראוי הוא לכל אחד ואחד בפני עצמו!","\u0003אלא הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 של \u0003ר' נתן דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נמנו עליו\u0004 על הפסח בני \u0003חבורה אחת, וחזרו ונמנו עליו\u0004 עוד \u0003חבורה אחרת,\u0004 ונתרבו כל כך שאין הפסח מספיק לכולם, \u0003ראשונים שיש להן כזית\u0004 לכל אחד מן הפסח \u0003אוכלין — ופטורין מלעשות פסח שני, אחרונים שאין להם\u0004 כבר \u0003כזית\u0004 כל אחד \u0003אין אוכלין וחייבין לעשות פסח שני,\u0004","\u0003ר' נתן אומר: אלו ואלו פטורין מלעשות פסח שני, שכבר נזרק הדם\u0004 ויצאו כולם ידי חובתם. משמע שלר' נתן אין אכילה מעכבת.","\u0003אכתי\u0004 \u0005[עדיין]\u0006 מקשים: \u0003דילמא שאני התם\u0004 \u0005[שמא שונה שם]\u0006 \u0003דאי ממשכי הני חזי להו\u0004 \u0005[שמא ימשכו אלה\u0006 הראשונים את ידם \u0005יהיה ראוי להם\u0006 לאחרונים\u0005].\u0006 את הקושיה הזו דוחים: \u0003אם כן,\u0004 אם זה הוא הטעם \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003הואיל וראויים לימשך\u0004 \u0005[להימשך],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 ההדגשה \u0003שכבר נזרק הדם? שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003בדם תליא מילתא\u0004 \u0005[תלוי הדבר]\u0006 \u0003אבל אכילה לא מעכבא\u0004 \u0005[מעכבת].\u0006","ושואלים: \u0003מאי דוחקיה דרב דמוקים לה מתניתין\u0004 \u0005[מה הדוחק ש\u0006מביא את \u0005רב להעמיד\u0006 להסביר \u0005את משנתנו]\u0006 שכוונתה שזורק את הדם \u0003לכתחלה, ו\u0004כשיטת \u0003ר' נתן? נוקמה כרבנן\u0004 \u0005[נעמיד\u0006 נסביר את המשנה \u0005כ\u0006שיטת \u0005חכמים],\u0006 \u0003ו\u0004נאמר ש\u0003אפילו בדיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יוצא? ומשיבים: \u0003רב מתניתין קשיתיה\u0004 \u0005[משנתנו היתה קשה לו]\u0006 \u0003אמאי תני\u0004 \u0005[מדוע שנה]\u0006 \u0003\"אין זורק את הדם\"? ליתני\u0004 \u0005[שישנה]\u0006 \u0003פסול. אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 מדיוק הלשון: \u0003אין זורק\u0004 משמעו — \u0003לכתחלה, אבל דיעבד — שפיר דמי\u0004 \u0005[יפה].\u0006","ושואלים: \u0003ולר' נתן,\u0004 פסוק זה \u0003\"איש לפי אכלו\" למה לי\u0004 לשם מה צריך הוא, אם אכילה אינה מעכבת? ומשיבים שאף לדעת ר' נתן נצרכה, \u0003דבעינן גברא דחזי\u0004 \u0005[שצריכים אנו אדם הראוי]\u0006 \u0003לאכילה,\u0004 שאם אינו ראוי כלל לאכילה כגון: חולה או זקן — אינו יוצא בקרבן.","על פי הדברים שאמרנו דנים: \u0003מאן תנא להא\u0004 \u0005[מי שנה\u0006 דבר \u0005זה]\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003שחטו לאוכליו\u0004 (הראויים לאוכלו) \u0003וזרקו דמו שלא\u0004 לשם \u0003אוכליו — הפסח עצמו כשר ואדם יוצא בו ידי חובתו. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 \u0003נימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 כשיטת \u0003ר' נתן היא\u0004 שאין אכילה מעכבת, \u0003ולא רבנן?\u0004","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003רבנן\u0004 \u0005[\u0006כשיטת \u0005חכמים],\u0006 אלא שהכל מודים כי \u0003אין מחשבת אוכלין\u0004 שאינם ראויים פוסלת \u0003בזריקה,\u0004 אלא בשעת שחיטה בלבד.","ועוד דנים: \u0003מאן תנא להא\u0004 \u0005[מי שנה\u0006 דבר \u0005זה]\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003הרי שהיה חולה בשעת שחיטה\u0004 ואינו יכול לאכול \u0003וחלים\u0004 (בריא) \u0003בשעת זריקה,\u0004 או \u0003חלים בשעת שחיטה וחולה בשעת זריקה — אין שוחטין וזורקין עליו, עד שיהא חלים משעת שחיטה עד שעת זריקה. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006 הוא\u0005]\u0006 \u0003נימא רבנן היא\u0004 \u0005[נאמר\u0006 כשיטת \u0005חכמים]\u0006 המקפידים על אכילת הפסח \u0003ולא\u0004 כשיטת \u0003ר' נתן?\u0004 ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003ר' נתן\u0004 ואף לדעתו \u0003גברא דחזי\u0004 \u0005[איש הראוי]\u0006 \u0003לאכילה בעינן\u0004 \u0005[צריכים אנו].\u0006","ועוד דנים: \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי שנה דבר זה ששנו חכמים]:\u0006 \u0003שחטו בטהרה ואחר כך נטמאו הבעלים — יזרק הדם בטהרה ואל יאכל בשר בטומאה. כמאן\u0004 \u0005[כמי]\u0006","\u0003אמר ר' אלעזר:\u0004 דבר זה \u0003במחלוקת שנויה,\u0004 כלומר אינו כדעת כל החכמים אלא כשיטת \u0003ר' נתן היא\u0004 שאכילה אינה מעכבת. \u0003ור' יוחנן אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 כשיטת \u0003רבנן היא. הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003בציבור\u0004 שנטמא רוב הציבור, ש\u0003אפילו בטומאה נמי עבדי\u0004 \u0005[גם כן עושים]\u0006 והלכה זו כדברי הכל.","ומקשים: \u0003אי בציבור אמאי\u0004 \u0005[אם בצבור מדוע]\u0006 \u0003אין הבשר נאכל בטומאה?\u0004 הלוא טומאה לפחות דחויה בצבור, וכל הקהל אוכל פסח טמא! ומשיבים איסור זה משום \u0003גזירה\u0004 מיוחדת היא \u0003שמא יטמאו הבעלים לאחר זריקה, ויאמרו: אשתקד\u0004 \u0005[בשנה שעברה]\u0006 האם \u0003לא נטמאנו ואכלנו?\u0004 שהרי כשהכל טמאים היו, הפסח נעשה ונאכל בטומאה. \u0003השתא נמי ניכול\u0004 \u0005[עכשיו גם כן נאכל]\u0006 בטומאה, \u0003ולא ידעי\u0004 \u0005[ואינם יודעים]\u0006 ההבדל \u0003דאשתקד כי איזדריק\u0004 \u0005[שבשנה שעברה כאשר נזרק]\u0006 ה\u0003דם,\u0004 ה\u0003בעלים טמאים הוו\u0004 \u0005[היו],\u0006 \u0003השתא\u0004 \u0005[עכשיו,\u0006 השנה\u0005]\u0006 \u0003בעלים טהורים הוו\u0004 \u0005[הם]\u0006 שנטמאו רק לאחר זמן זריקת הדם ופסח שנעשה בטהרה אסור לאוכלו בטומאה, אפילו הכל טמאים."],["\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003רב\u0004 ש\u0003אמר\u0004 על משנתנו שאם זרק הורצה — כשיטת \u0003ר' יהושע\u0004 הסובר שאכילת הפסח אינה מעכבת אמר. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהושע אומר: כל הזבחים שבתורה בין שנטמא בשר וחלב קיים, בין שנטמא חלב ובשר קיים — זורק את הדם.\u0004","אם היו אלו שלמי \u0003נזיר\u0004 או \u0003עושה פסח,\u0004 אם \u0003נטמא חלב ובשר קיים — זורק את הדם. נטמא בשר וחלב קיים — אין זורק את הדם\u0004 משום שבשני קרבנות אלה אכילת הבשר היא מעיקר המצוה, אבל \u0003אם זרק — הורצה.\u0004","אם \u0003נטמאו הבעלים\u0004 בטומאת \u0003מת\u0004 ואינם יכולים איפוא לאכול מבשר הזבח — \u0003לא יזרוק\u0004 את הדם, \u0003ואם זרק לא הורצה\u0004 שגם אם אכילה אינה מעכבת מכל מקום צריך שיהא בעל הקרבן ראוי לאכול ממנו.","שנינו במשנה שבשאר \u0003מוקדשין אינו כן,\u0004 אלא אפילו נטמא הבשר והחלב קיים — זורקים את הדם. ושואלים: \u0003מתניתין מני\u0004 \u0005[משנתינו\u0006 כשיטת \u0005מי היא]?\u0006","ומשיבים: כשיטת \u0003ר' יהושע היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהושע אומר: כל הזבחים שבתורה שנשתייר מהם כזית בשר\u0004 הראוי לאכילה \u0003או כזית חלב\u0004 הראוי להקטרה \u0003— זורק את הדם.\u0004 אם נשתייר \u0003כחצי זית בשר וכחצי זית חלב\u0004 בלבד \u0003— אין זורק את הדם.\u0004 כי החלב נאכל באש המזבח, והבשר נאכל לכהנים או לבעלים ואינם מצטרפים זה לזה.","\u0003ובעולה, אפילו\u0004 השתייר \u0003כחצי זית בשר וכחצי זית חלב — זורק את הדם, מפני שכולה\u0004 נאכלת \u0003כליל\u0004 למזבח גם הבשר וגם החלב, ולכן מצטרפים. \u0003ובמנחה אף על פי שכולה קיימת — לא יזרוק\u0004 את הדם עליה.","ותוהים: \u0003מנחה מאי עבידתה\u0004 \u0005[מה מעשיה\u0006 כאן\u0005]\u0006 הלוא כאן מדובר בענין זריקת דם, ומה מקום להזכרת קרבן מנחה? \u0003אמר רב פפא:\u0004 מנחה זו היא \u0003מנחת נסכים.\u0004 אותה מנחה שמביאים יחד עם הזבח. \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003כיון דקא אתיא מכח זבח — כגופיה דזבח דמי\u0004 \u0005[כיון שהיא באה מכוח הזבח\u0006 ולצורך הזבח \u0005כגופו של הזבח נחשבת]\u0006 ואם נטמא הזבח ונשארה המנחה טהורה יוכל לזרוק את הדם בשל המנחה. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא.","ושואלים: \u0003חלב מנא לן\u0004 \u0005[מנין לנו]\u0006 שאפשר לזרוק את דם הקרבן אם קיים רק החלב? \u0003אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' ישמעאל ומטו\u0004 \u0005[ומגיעים]\u0006 \u0003בה\u0004 בשלשלת מסורת שמועה זו \u0003משום\u0004 \u0005[בשם]\u0006 \u0003ר' יהושע בן חנניה:\u0004 ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"\u0004וזרק הכהן את הדם על מזבח ה' פתח אהל מועד \u0003והקטיר החלב לריח ניחח לה\"\u0004 (ויקרא יז, ו), ללמדנו: זורקים הדם עבור \u0003חלב, אף על פי שאין בשר,\u0004","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 מקור לדין אם נשתייר \u0003חלב\u0004 כאמור במקרא, אולם אם נשתיירו \u0003יותרת הכבד ושתי כליות,\u0004 שאף הן אימורין העולים למזבח, \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 שזורקים את הדם בשלהם?","ושואלים: \u0003היכא אמרינן דזרקינן\u0004 \u0005[היכן אמרנו שאנו זורקים\u0006 עבורם\u0005]?\u0006 שמא אם נשארו יותרת הכבד ושתי כליות בלבד אכן אין זורקים את הדם בשלהם? ומשיבים: \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 בסוף הדברים \u0003ובמנחה אף על פי\u0004 ש\u0003כולה קיימת — לא יזרוק,\u0004 ומכאן אפשר לדייק: \u0003מנחה הוא\u0004 ש\u0003לא\u0004 יזרוק כי אינה מגוף הזבח, \u0003אבל יותרת הכבד ושתי הכליות — שפיר דמי\u0004 \u0005[יפה\u0006 וראוי\u0005],\u0006 ואם כן דבר זה \u0003מנא לן\u0004 \u0005[מנין לנו]?\u0006","ומשיבים: \u0003ר' יוחנן דידיה\u0004 \u0005[משלו]\u0006 \u0003אמר,\u0004 הפעם לא בשם התנאים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 שכבר הבאנו לענין זה \u0003\"לריח ניחח\"\u0004 ללמדנו: \u0003כל שאתה מעלה לריח ניחח\u0004 — זורקים את הדם עבורו.","ומעירים: \u0003ואיצטריך למכתב חלב\u0004 \u0005[וצריך היה לכתוב\u0006 באותו פסוק \u0005חלב]\u0006 \u0003ואיצטריך למכתב\u0004 \u0005[וצריך היה לכתוב]\u0006 \u0003\"ריח ניחח\", דאי כתב רחמנא חלב\u0004 \u0005[שאם\u0006 היתה \u0005כותבת התורה חלב\u0006 בלבד\u0005]\u0006 \u0003הוה אמינא: חלב — אין\u0004 \u0005[הייתי אומר: חלב —\u0006 \u0005כן]\u0006 \u0003יותרת הכבד ושתי הכליות — לא,\u0004 שאינן חשובות כחלב, לכך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"לריח ניחח\", ואי כתב רחמנא\u0004 \u0005[ואם\u0006 היתה \u0005כותבת התורה]\u0006 רק \u0003\"לריח ניחח\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003כל העולין לריח ניחח, ואפילו מנחה\u0004 בכלל זה, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003חלב,\u0004 ללמדנו שדין זה הוא באימורים בלבד, אבל לא בנסכים ובמנחות.","\u0003נטמא\u0004 כל \u0003קהל\u0004 ישראל \u0003או רובו\u0004 של הקהל, \u0003או שהיו הכהנים טמאים\u0004 כולם אף על פי ש\u0003הקהל טהורים — יעשו\u0004 את הפסח \u0003בטומאה. נטמא מיעוט הקהל\u0004 ואפילו הם מרובים במספר — \u0003הטהורין עושין את\u0004 הפסח \u0003הראשון, והטמאין עושין את\u0004 הפסח \u0003השני.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרי שהיו\u0004 כל או רוב \u0003ישראל טמאין וכהנים וכלי שרת שבמקדש טהורין, או\u0004 להיפך \u0003ישראל טהורין וכהנים וכלי שרת טמאין, ואפילו\u0004 מצב שהיו \u0003ישראל וכהנים טהורין וכלי שרת טמאין — יעשו\u0004 כולם את הפסח \u0003בטומאה, שאין קרבן ציבור\u0004 הבא בטומאה \u0003חלוק,\u0004 וכיון שיש לעשות חלק מן העבודה בטומאה, תיעשה כולה בטומאה.","\u0003אמר רב חסדא: לא שנו\u0004 שעושים הכל בטומאה בשל טומאת כלי שרת \u0003אלא\u0004 כגון \u0003שנטמא הסכין\u0004 ששוחטים בו \u0003בטמא מת, דרחמנא אמר\u0004 \u0005[שהתורה אמרה]:\u0006 \"וכל אשר יגע על פני השדה \u0003בחלל חרב\u0004 או במת או בעצם אדם או בקבר יטמא שבעת ימים\" (במדבר יט, טז) ודרשו חכמים: \u0003חרב הרי הוא כחלל,\u0004 ונעשית הסכין הנוגעת במת בדרגת טומאה כמת עצמו (אבי אבות הטומאה),","\u0003וקא מטמא לגברא\u0004 \u0005[והוא\u0006 הסכין \u0005מטמא את האיש\u0006 ששוחט בו\u0005]\u0006 \u0003דמעיקרא כי מיתעביד\u0004 \u0005[שמתחילה כאשר נעשה\u0006 הקרבן\u0005]\u0006 \u0003בטומאת הגוף\u0004 שיש בה \u0003כרת קא מיתעביד\u0004 \u0005[הוא נעשה].\u0006","\u0003אבל\u0004 אם \u0003נטמא הסכין בטומאת שרץ, דבשר הוא דמטמיא ליה\u0004 \u0005[שאת הבשר הוא שמטמא\u0006 הסכין הזו\u0005]\u0006 אבל \u0003לגברא לא מטמיא ליה\u0004 \u0005[את האיש אין\u0006 הסכין \u0005מטמאה],\u0006 שדבר שנטמא מחמת אב טומאה (כשרץ), נעשה ולד הטומאה ואינו מטמא אדם אלא אוכל בלבד. הרי במקרה זה \u0003טהורין עביד\u0004 \u0005[אנשים הטהורים עושים\u0006 את הפסח\u0005]\u0006 \u0003טמאין לא עביד\u0004 \u0005[אין עושים],\u0006 כי \u0003מוטב\u0004\u0005,\u0006 \u0003יאכל\u0004 הפסח \u0003בטומאת בשר\u0004 שאיסורה הוא רק \u0003בלאו, ואל יאכל בשר בטומאת הגוף שהוא בכרת.\u0004","ומעירים כי מתוך דברי רב חסדא המנסה לחלק בין טומאה לטומאה, ושרק בטומאה חמורה אומרים שיעשה כל הציבור בטומאה, \u0003אלמא קסבר\u0004 \u0005[מכאן שסבר]\u0006 \u0003רב חסדא: טומאה דחויה היא בציבור\u0004 שאיסור הטומאה לא הותר לגמרי בציבור אלא נדחה בלבד בשעת הדחק, וממילא בכל מקום שאפשר לעשות בטהרה או אפילו בטומאה קלה יותר — עושים. \u0003וכן אמר ר' יצחק\u0004 במפורש: \u0003טומאה דחויה היא בציבור.\u0004","\u0003ורבא אמר:\u0004 במקרה שיש טומאה כל שהיא \u0003אפילו טמאין נמי עבדי\u0004 \u0005[גם כן עושים]\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והבשר אשר יגע בכל טמא לא יאכל, באש ישרף, והבשר כל טהור יאכל בשר\"\u0004 (ויקרא ז, יט)","ולומד מכאן \u0003כל היכא דלא קרינן ביה\u0004 \u0005[בכל מקום שאין אנו קוראים בו]\u0006 \u0003\"והבשר אשר יגע בכל טמא לא יאכל\"\u0004 אלא נאכל על אף טומאתו, שם גם \u0003לא קרינן ביה\u0004 \u0005[אין אנו קוראים בו]\u0006 ואיננו דורשים שיתקיים חלקו האחר של הפסוק \u0003\"והבשר כל טהור יאכל בשר\",\u0004 ונאכל אף לטמא. ורק \u0003כל היכא דקרינן ביה\u0004 \u0005[כל מקום שאנו קוראים בו]\u0006 \u0003\"והבשר אשר יגע בכל טמא לא יאכל\"\u0004 אז מקפידים אנו על הצד השני, ו\u0003קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 \u0003\"והבשר כל טהור יאכל בשר\"\u0004 ולמדנו שאם אין הקרבן בא בטהרה שוב אין איסור שיאכלו טמאים ממנו.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה מהו רוב ציבור. \u0003הרי שהיו ישראל\u0004 בדיוק \u0003מחצה טהורין ומחצה טמאין. רב אמר: מחצה על מחצה כרוב. ורב כהנא אמר: מחצה על מחצה אינו כרוב.\u0004","ולמעשה, \u0003רב אמר: מחצה על מחצה\u0004 דינם \u0003כרוב,\u0004 ואם כן גם הטמאים וגם הטהורים נחשבים כל קבוצה בפני עצמה כרוב, לכן \u0003הללו\u0004 הטהורים \u0003עושין לעצמן\u0004 פסח הראשון בטהרה שהרי הם כרוב ציבור, \u0003והללו\u0004 הטמאים \u0003עושין לעצמן\u0004 פסח בטומאה, שאף הם בפני עצמם נחשבים כרוב ציבור, ורוב ציבור אינו נדחה לפסח שני. \u0003ורב כהנא אמר: מחצה על מחצה אינו כרוב.\u0004 ולכן \u0003טהורין עושין את הראשון, וטמאין עושין את השני,\u0004","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 לא כך יש להסיק מדברי רב כהנא, אלא \u0003אמר רב כהנא: מחצה על מחצה אינו כרוב,\u0004 כיצד? \u0003טהורין\u0004 ודאי \u0003עושין את\u0004 הפסח \u0003הראשון.\u0004"],["\u0003וטמאין אין עושין לא את הראשון ולא את השני.\u0004 מה טעם? \u0003בראשון לא עבדי דלא הוו רובא\u0004 \u0005[בראשון אינם עושים\u0006 בטומאה \u0005משום שאינם רוב]\u0006 כי רק כשרוב הציבור טמא עושים את הראשון אף בטומאה. וכן \u0003בשני לא עבדי, דלא הוו מיעוטא\u0004 \u0005[אינם עושים, שאין הם מיעוט]\u0006 ורק מיעוט קהל עושה פסח שני.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003נטמא קהל או רובו, או שהיו הכהנים טמאין והקהל טהורים יעשה בטומאה.\u0004 ונדייק: נטמא \u0003רובו הוא דעבדי\u0004 \u0005[הוא שעושים]\u0006 \u0003בטומאה אבל פלגא ופלגא לא עבדי בראשון\u0004 \u0005[אבל\u0006 אם היו \u0005מחצה ומחצה לא יעשו\u0006 בפסח \u0005ראשון]\u0006 \u0003קשיא\u0004 \u0005[קשה]\u0006 איפוא לשיטת \u0003רב!\u0004","\u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003רב: רובא עבדי כולהו בטומאה\u0004 \u0005[רוב\u0006 טמאים \u0005עושים כולם בטומאה]\u0006 אפילו הטהורים, \u0003פלגא ופלגא\u0004 \u0005[מחצה ומחצה]\u0006 \u0003הללו\u0004 הטהורים \u0003עושין לעצמן\u0004 בראשון \u0003והללו\u0004 הטמאים \u0003עושין לעצמן\u0004 בשני.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 להבין את דיוק לשון המשנה. כי \u0003קתני סיפא\u0004 \u0005[שנינו בסופה]\u0006 \u0003נטמא מיעוט הקהל, טהורין עושין את\u0004 הפסח \u0003הראשון וטמאין עושין את השני,\u0004 ונדייק: נטמא \u0003מיעוט הוא דעבדי\u0004 \u0005[שעושים]\u0006 \u0003בשני, אבל פלגא ופלגא — לא\u0004 \u0005[מחצה ומחצה לא]\u0006 יעשו בשני. ונלמד מכאן: \u0003ועבדי\u0004 \u0005[ועושים]\u0006 הראויים לכך \u0003בראשון.\u0004 משמע: \u0003הללו\u0004 הטהורים \u0003עושין לעצמן\u0004 בראשון \u0003והללו\u0004 הטמאים \u0003עושין לעצמן\u0004 בשני.","ושואלים: אם כן, \u0003ואלא קשיא\u0004 \u0005[קשה]\u0006 \u0003לרב כהנא\u0004 מדיוק זה! ומשיבים: \u0003אמר לך רב כהנא\u0004 \u0005[\u0006יכול היה \u0005רב כהנא לומר]\u0006 שכך יש לדייק: \u0003נטמאו מיעוט הקהל — טהורין עושין את הראשון וטמאין עושין את השני, הא פלגא ופלגא\u0004 \u0005[הרי מחצה ומחצה] —\u0006 \u0003טהורין עושין את הראשון, אבל טמאין אינן עושין לא את הראשון ולא את השני.\u0004","ומקשים עוד: \u0003התינח ללישנא בתרא דרב כהנא\u0004 \u0005[זה נוח, ל\u0006פי \u0005הלשון האחרונה\u0006 בדברי \u0005רב כהנא]\u0006 שכך עושים כשיש מחצה ומחצה. \u0003אלא להך לישנא\u0004 \u0005[אלא ללשון זו]\u0006 ש\u0003אמר רב כהנא:\u0004 במחצה ומחצה \u0003טהורים עושין את הראשון, וטמאין עושין את השני, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 וקשה לדבריו!","\u0003אמר לך רב כהנא:\u0004 כך יש לפרש את המשנה, \u0003הוא הדין דאפילו פלגא ופלגא נמי\u0004 \u0005[מחצה ומחצה גם כן]\u0006 \u0003טהורין עושין את הראשון, וטמאין עושין את השני. והאי דקתני\u0004 \u0005[וזה ששנינו\u0006 במשנה\u0005]\u0006 \u0003מיעוט הקהל\u0004 עושין את השני אינו מדויק, כי \u0003איידי דתנא רישא רובו — תנא נמי סיפא מיעוטו\u0004 \u0005[על ידי ששנה בראשה\u0006 של המשנה \u0005רובו שנה גם כן בסופה\u0006 משום גרר הלשון \u0005מיעוטו].\u0006","ומעירים: \u0003תניא כוותיה דרב, תניא כוותיה דרב כהנא כתרי לישני\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת רב ושנויה\u0006 ברייתא \u0005כשיטת רב כהנא כשתי הלשונות\u0006 בשמו\u0005]\u0006 \u0003תניא כוותיה דרב\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת רב]:\u0006 \u0003היו ישראל מחצה טהורין ומחצה טמאין, הללו\u0004 הטהורים \u0003עושין\u0004 פסח \u0003לעצמן\u0004 בטהרה והטמאים \u0003עושין לעצמן\u0004 בטומאה בפסח ראשון.","\u0003תניא כלישנא קמא דרב כהנא\u0004 \u0005[שנויה\u0006 ברייתא \u0005כלשון ראשונה של רב כהנא]:\u0006 \u0003הרי שהיו ישראל מחצה טהורין ומחצה טמאין, טהורין עושין את הראשון וטמאין עושין את השני.\u0004","\u0003ותניא כלישנא בתרא\u0004 \u0005[כלשון אחרונה]\u0006 של \u0003רב כהנא: הרי שהיו ישראל מחצה טהורין ומחצה טמאין, טהורין עושין את הראשון וטמאין אינן עושין לא את הראשון ולא את השני,\u0004","ושואלים: ולשיטת \u0003רב, או ללישנא בתרא\u0004 \u0005[ללשון אחרונה]\u0006 של \u0003רב כהנא, הא דתנא\u0004 \u0005[זה ששנה]\u0006 באותה הברייתא השניה שהובאה \u0003\"טהורין עושין את הראשון וטמאין את השני\", היכי מתרצי לה\u0004 \u0005[איך מישבים אותה]?\u0006 ומשיבים שהם מוצאים דרך מיוחדת להסביר את הדבר, כי מדובר לדעתם במקרה \u0003כגון שהיו ישראל\u0004 הזכרים רובם טהורים ומיעוטם טמאים ואם מחשיבים גם את הגברים וגם את הנשים כאחד הרי זה \u0003מחצה טהורין ומחצה טמאין, ונשים משלימות לטמאים\u0004 כי בין הנשים היה רוב של טמאות.","\u0003וקסבר\u0004 \u0005[וסבר]\u0006 תנא זה: השתתפות \u0003נשים\u0004 בפסח \u0003ראשון\u0004 הרי הוא \u0003רשות\u0004 אם כן \u0003דל נשים מטמאין\u0004 \u0005[הוצא את הנשים\u0006 ממנין \u0005הטמאים]\u0006 \u0003והוו להו טמאין מיעוטא\u0004 \u0005[ונעשו להם הטמאים מיעוט]\u0006 וכיון שכך \u0003מיעוטא ידחו לפסח שני\u0004 לכל הדעות.","ושואלים עוד: לשיטת \u0003רב וללישנא קמא\u0004 \u0005[ללשון ראשונה]\u0006 של \u0003רב כהנא הא דתניא\u0004 \u0005[זו\u0006 הברייתא \u0005ששנויה]\u0006 \u0003\"טהורין עושין את הראשון וטמאין אין עושין לא את הראשון ולא את השני\" היכי מתרצי לה\u0004 \u0005[כיצד מיישבים הם אותה]\u0006 לשיטתם?","מסבירים: \u0003רב מתריץ לה\u0004 \u0005[מישב אותה]\u0006 \u0003כגון שהיו ישראל\u0004 הזכרים \u0003מחצה טמאין ומחצה טהורין, ונשים\u0004 שרובן טהורות \u0003עודפות על הטהורים\u0004 שבגללן נעשים הטהורים רוב, \u0003וסבר\u0004 אותו תנא: \u0003נשים בראשון חובה,\u0004 אבל בפסח \u0003שני\u0004 אינן חייבות אלא \u0003רשות\u0004 היא להן.","ולכן \u0003בראשון\u0004 אף אחד \u0003לא עבדי\u0004 \u0005[אינם עושים\u0006 בטומאה\u0005]\u0006 \u0003דהוי ליה מיעוט\u0004 \u0005[שהרי הם מיעוט]\u0006 שרוב הקהל הזכרים והנשים הם טהורים, \u0003ומיעוטא לא עבדי\u0004 \u0005[אינם עושים]\u0006 בטומאה בפסח \u0003ראשון. ובשני לא עבדי\u0004 \u0005[\u0006ואף \u0005בשני אינם עושים]\u0006 פסח, כי \u0003דל נשים מינייהו\u0004 \u0005[הוצא את הנשים מהם]\u0006 ממנין הטהורים \u0003והוו להו פלגא\u0004 \u0005[והרי הם\u0006 הטמאים \u0005מחצה]\u0006 \u0003ופלגא לא עבדי בשני\u0004 \u0005[ומחצה אינם עושים\u0006 בפסח \u0005שני].\u0006","ולשיטת \u0003רב כהנא\u0004 ש\u0003אמר\u0004 בלשון זו: \u0003פלגא נמי עבדי בשני\u0004 \u0005[שמחצה גם כן עושים בשני]\u0006 \u0003הכי מתריץ לה\u0004 \u0005[כך היה מסביר אותה\u0006 את הברייתא\u0005]\u0006 לשיטתו: \u0003כגון שהיו ישראל\u0004 נשים וגברים כאחד \u0003מחצה טהורין ומחצה טמאין, ונשים\u0004 הן ש\u0003משלימות לטהורין\u0004 שיהיו מחצה. \u0003וקסבר: נשים בראשון חובה ובשני רשות.\u0004","ולכן \u0003בראשון לא עבדי\u0004 \u0005[\u0006בפסח \u0005ראשון אינם עושים\u0006 בטומאה\u0005] —\u0006 \u0003דהוו להו פלגא ופלגא\u0004 \u0005[שהם מחצה ומחצה]\u0006 בטומאה, ולשיטתו \u0003פלגא בראשון לא עבדי\u0004 \u0005[מחצה בראשון אינם עושים],\u0006 \u0003ובשני נמי לא עבדי\u0004 \u0005[\u0006ופסח \u0005שני גם כן אינם עושים]\u0006 כי אם \u0003דל נשים מינייהו\u0004 \u0005[הוצא את הנשים מהם]\u0006 ממנין \u0003הטהורין הוו להו טמאין רובא\u0004 \u0005[נמצאו להם הטמאים\u0006 בפני עצמם \u0005רוב],\u0006 \u0003ורובא לא עבדי בשני\u0004 \u0005[ורוב\u0006 הקהל \u0005אינם עושים\u0006 בפסח \u0005שני]\u0006","ועוד: \u0003ולרב כהנא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]\u0006 \u0003הרי שהיו ישראל מחצה טהורין ומחצה טמאין הללו עושין לעצמן והללו עושין לעצמן, היכי מתריץ לה\u0004 \u0005[כיצד יכול לישב אותה]\u0006 לשיטתו? \u0003אמר לך רב כהנא\u0004 \u0005[\u0006היה \u0005אומר לך רב כהנא]:\u0006 בהכרח \u0003תנאי היא\u0004 \u0005[מחלוקת תנאים היא]\u0006 בנושא זה \u0003איכא למאן דאמר\u0004 \u0005[יש מי שאומר]\u0006 \u0003מחצה על מחצה\u0004 כל מחצה בפני עצמו הריהו \u0003כרוב, ואיכא למאן דאמר\u0004 \u0005[ויש מי שאומר]\u0006 \u0003מחצה על מחצה אינו כרוב.\u0004","כיון שהבאנו ברייתא זו, דנים מעתה \u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה ברייתא, \u0003הרי שהיו ישראל מחצה טהורין ומחצה טמאין. הללו עושין לעצמן והללו עושין לעצמן. היו טמאין עודפין\u0004 במספרם \u0003על הטהורין, אפילו\u0004 עודפים באיש \u0003אחד — יעשו\u0004 את הפסח כולו \u0003בטומאה, לפי שאין קרבן ציבור חלוק\u0004 ואין להיחלק מרוב הציבור הטמא, ויעשו כל הציבור כאחד את הפסח בטומאה.","\u0003ר' אלעזר בן מתיא אומר: אין\u0004 עודף של האיש \u0003היחיד מכריע את הציבור\u0004 כולו \u0003לטומאה, שנאמר:\u0004"],["\u0003\"לא תוכל לזבח את הפסח באחד שעריך\"\u0004 (דברים טז ה), ודרש מכאן שבשל אדם אחד אין לעשות שכל הציבור יזבח את הפסח בטהרה או בטומאה.","\u0003ר' שמעון אומר: אפילו\u0004 היה \u0003שבט אחד טמא ושאר כל השבטים טהורים — הללו\u0004 בני השבטים הטהורים \u0003עושין לעצמן\u0004 בפסח ראשון \u0003והללו\u0004 בני השבט הטמא \u0003עושין לעצמן\u0004 בפסח שני\u0003.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' שמעון.\u0004 ומשיבים \u0003קסבר: שבט אחד איקרי\u0004 \u0005[נקרא]\u0006 \u0003קהל\u0004 ישראל, וכל קהל חשוב כציבור, ולכן הוא עושה פסח בפני עצמו.","\u0003ר' יהודה אומר: אפילו שבט אחד טמא ושאר כל השבטים טהורין — יעשו\u0004 כולם \u0003בטומאה, שאין קרבן ציבור חלוק.\u0004 ומסבירים: \u0003ר' יהודה סבר\u0004 כר' שמעון ש\u0003שבט אחד איקרי\u0004 \u0005[נקרא]\u0006 \u0003קהל. והוו להו\u0004 \u0005[והרי הם\u0006 נעשים לפיכך\u0005]\u0006 קהל טהור וקהל טמא והרי הם כעין \u0003פלגא ופלגא\u0004 \u0005[מחצה ומחצה]\u0006 \u0003ואין קרבן ציבור חלוק ועבדי כולהו\u0004 \u0005[ועושים כולם]\u0006 \u0003בטומאה.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה זו: \u0003היו ישראל מחצה טהורין ומחצה טמאין\u0004 בדיוק, \u0003אמר רב: מטמאין אחד מהן\u0004 מהטהורים \u0003בשרץ,\u0004 ונמצא רוב הציבור טמאים, ועושים כולם פסח ראשון בטומאה.","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יעשו כן? \u0003ניעבדו הני לחודייהו והני לחודייהו\u0004 \u0005[יעשו אלה לעצמם ואלה לעצמם]\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר רב\u0004 עצמו: מחצה טהורים ומחצה טמאים — \u0003הללו\u0004 הטהורים \u0003עושין\u0004 פסח \u0003לעצמן, והללו\u0004 הטמאים \u0003עושין\u0004 פסח \u0003לעצמן! אמרי\u0004 \u0005[אומרים]\u0006 כתשובה לדבר: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 במקרה מיוחד \u0003כגון שהיו טמאין עודפין על הטהורין\u0004 באדם \u0003אחד\u0004","ומקשים: \u0003אי הכי הוו להו רובא טמאים\u0004 \u0005[אם כך נעשה להם רוב טמאים]\u0006 \u0003ניעבדו כולהו בטומאה\u0004 \u0005[שיעשו כולם בטומאה]\u0006 ומשיבים \u0003סבר לה\u0004 רב כשיטת \u0003ר' אלעזר בן מתיא,\u0004 ש\u0003אמר: אין היחיד מכריע את הציבור\u0004 כולו \u0003לטומאה.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שיחיד אינו מכריע את הכל לטומאה \u0003הדר קושיין לדוכתיה\u0004 \u0005[חוזרת קושייתנו למקומה]\u0006 שאם הם כמחצה ומחצה \u0003ניעבדו הני לחודייהו והני לחודייהו\u0004 \u0005[יעשו אלה לעצמם ואלה לעצמם]\u0006 כל אחד בזמן הראוי לו!","\u0003אלא הכי קאמר\u0004 \u0005[כך אמר]\u0006 רב, כך יש להבין את דבריו: \u0003אי איכא תנא דסבר לה כתנא קמא, דאמר פלגא ופלגא לא עבדי כולהו בטומאה\u0004 \u0005[אם יש תנא\u0006 כל שהוא \u0005הסבור\u0006 לענין זה \u0005כתנא קמא שאמר שמחצה ומחצה אינם עושים כולם בטומאה]\u0006 ואף \u0003סבר לה\u0004 כשיטת \u0003ר' יהודה,\u0004 ש\u0003אמר אין קרבן ציבור חלוק\u0004 אין דרך אחרת לפטור את הבעיה אלא כאשר \u0003מטמאין אחד מהן בשרץ,\u0004","\u0003ועולא אמר:\u0004 אין מטמאין בשרץ אלא \u0003משלחין אחד מהן לדרך רחוקה\u0004 ויהיו אז רוב הציבור טמאים ויקריבו כולם בפסח שני. ושואלים: \u0003ויטמאנו בשרץ\u0004 כדברי רב, שהוא קל ופשוט יותר!","ומשיבים: \u0003קסבר\u0004 עולא כי \u0003שוחטין\u0004 את הפסח \u0003וזורקין\u0004 דמו אף \u0003על טמא שרץ\u0004 כיון שלעת ערב יטהר ויוכל לאכול את הפסח, ואם כן אין תועלת כשיטמאנו בשרץ.","ומקשים: \u0003ויטמאנו במת\u0004 שמטמא טומאת שבעה! ומשיבים: דבר זה אין עושים לו כי \u0003מדחהו אתה מחגיגתו\u0004 שכיון שטמא בכל ימי החג אתה גורם שאסור לו להקריב קרבן חגיגה הבא בחג ומאבד מצוה שלא לצורך.","ומקשים: \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 שאתה משלחו בדרך רחוקה הרי \u0003מדחהו אתה מפסחו\u0004 ומבטל מצוה! ומשיבים לענין קרבן פסח יש לו תקנה \u0003אפשר דעביד בשני\u0004 \u0005[אפשר שיעשה ב\u0006פסח \u0005שני].\u0006","ומקשים: בטומאת \u0003מת נמי אפשר דעביד בשביעי\u0004 \u0005[אפשר שיעשה\u0006 קרבן חגיגה ביום \u0005השביעי\u0006 בפסח\u0005]\u0006 \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003שמיני שלו\u0004 שהרי נטמא במת בערב פסח ושביעי של פסח הוא יום שמיני לטומאתו ואז יכול להטהר ולהקריב קרבנות!","ומשיבים: \u0003קסבר עולא: כולהו\u0004 \u0005[כל\u0006 ימי החג \u0005כולם]\u0006 שמקריבים גם בהם קרבן חגיגה — \u0003תשלומין\u0004 של היום ה\u0003ראשון נינהו\u0004 \u0005[הם],\u0006 שכולם באים להשלים מה שהיה צריך להקריב ביום הראשון של החג, ולא הספיק. ולכן, \u0003דחזי בראשון חזי בכולהו\u0004 \u0005[הראוי בראשון ראוי בכולם]\u0006 \u0003וכל היכא דלא חזי בראשון לא חזי בכולהו\u0004 \u0005[וכל מקום שאינו ראוי בראשון אינו ראוי בכולם]\u0006 ולכן אינו ראוי להקריב בשביעי של פסח ונמצא שהוא בטל מן המצוה","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן\u0004 לתלמידים: \u0003זילו ואמרו ליה לעולא\u0004 \u0005[לכו ואמרו לו לעולא]\u0006 שאין הפתרון שנתן אפשרי לביצוע, \u0003מאן ציית דעקר סיכיה ומשכניה ורהיט\u0004 \u0005[מי יציית לך שיעקור את יתדותיו ואהלו וירוץ]\u0006 למקום רחוק, לדירתם של אחרים.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שדנו בנושא זה: \u0003היו רובן\u0004 של הקהל \u0003זבין\u0004 שהדין הוא שגם אם רוב הקהל זבים אינם עושים פסח בטומאה, \u0003ומיעוטן\u0004 היו \u0003טמאי מתים\u0004 מה יעשו? \u0003אמר רב: אותן טמאי מתים אינן עושין\u0004 פסח \u0003לא בראשון ולא בשני.\u0004","ומסביר: פסח \u0003ראשון לא עבדי\u0004 \u0005[אינם עושים]\u0006 משום \u0003דהוו מיעוטא\u0004 \u0005[שהם מיעוט]\u0006 \u0003ומיעוטא לא עבדי בראשון\u0004 \u0005[ומיעוט\u0006 הקהל \u0005אינו עושה\u0006 פסח \u0005בראשון]\u0006 בטומאה. \u0003בשני נמי\u0004 \u0005[גם כן]\u0006 \u0003לא עבדי\u0004 \u0005אינם עושים]\u0006 כי \u0003כל היכא דעבדי ציבור בראשון — עביד יחיד בשני\u0004 \u0005[כל מקום שעושים הציבור\u0006 כולם בפסח \u0005ראשון עושה היחיד בפסח שני]\u0006 \u0003כל היכא דלא עבדי ציבור בראשון — לא עביד יחיד בשני\u0004 \u0005[כל מקום שאין עושים הציבור בראשון אין עושה היחיד בשני]\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003שמואל\u0004 לאלה שמסרו לו את דברי רב: \u0003זילו אמרו ליה\u0004 \u0005[לכו ואמרו לו]\u0006 \u0003לאבא\u0004 (שמו הפרטי של רב) את מצות הכתוב \u0003\"ויעשו בני ישראל את הפסח במועדו\"\u0004 (במדבר ט, ב) \u0003מאי עבדת ליה\u0004 \u0005[מה עושה אתה בו]?\u0006 \u0003אמר להו: זילו אמרו ליה\u0004 \u0005[אמר להם\u0006 רב לאלה שמסרו לו דברי שמואל; \u0005לכו ואמרו לו\u0006 לשמואל\u0005]\u0006 \u0003כי הוו כולהו זבין מאי עבדת ליה\u0004 \u0005[אם היו כל\u0006 הקהל \u0005כולם זבים מה תעשה לו\u0006 לפסוק זה\u0005]\u0006 הלוא בעל כרחך תאמר כי \u0003כיון\u0004 ש\u0003לא אפשר\u0004 לקיימו \u0003לא אפשר, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003לא אפשר.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שדנו בדבר זה: \u0003היו רובן\u0004 של הקהל בפסח ראשון \u0003טמאי מתים\u0004 שמקריבים בשל כך בפסח ראשון מתוך טומאה \u0003ומיעוטן זבין\u0004 שאין טומאתם מתירתם להקריב בראשון ואותם זבים נטהרו עד לפסח שני,","\u0003רב הונא אמר: אין תשלומין לפסח הבא בטומאה,\u0004 שכיון שפסח ראשון נעשה בטומאה שוב אין עושים באותה שנה פסח שני, \u0003ורב אדא בר אהבה אמר: יש תשלומין לפסח הבא בטומאה\u0004 שמי שלא יכול לעשותו בזמן שהקריבו רוב הציבור בטומאה — עושה פסח שני.","ומציעים: \u0003נימא בהא קמיפלגי\u0004 \u0005[האם נאמר\u0006 שברעיון \u0005זה נחלקו]\u0006 \u0003דמאן\u0004 \u0005[שמי]\u0006 ש\u0003אמר,\u0004 רב הונא, \u0003אין תשלומין לפסח הבא בטומאה, קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003טומאה דחויה היא בציבור,\u0004 ולא הותרה היתר גמור, ולכן אינך יכול להחשיב את הטמאים כאילו היו טהורים ולדחות את הזבים לפסח שני.","ואילו \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר,\u0004 ר' אבא בר אהבה, \u0003יש תשלומין לפסח הבא בטומאה, קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003טומאה הותרה בציבור\u0004 והפסח הראשון נחשב כאילו נעשה בטהרה, ויש להקריב בפסח שני לאלה שלא יכלו לעשותו בזמנו.","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא,\u0004 אין צורך לקבל הנחה זו. אפשר לומר \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003טומאה דחויה\u0004 היא \u0003בציבור.\u0004 אלא \u0003בהא פליגי\u0004 \u0005[ב\u0006עקרון \u0005זה נחלקו]\u0006 \u0003מר\u0004 \u0005[חכם זה\u0006 רב הונא\u0005]\u0006 שאמר שאין תשלומין \u0003סבר:\u0004"],["\u0003טהרה מדחיא\u0004 \u0005[דוחה]\u0006 את הטמאים לפסח שני, פסח הנעשה ב\u0003טומאה לא מדחיא\u0004 \u0005[דוחה]\u0006 את הטמאים לפסח שני. \u0003ומר\u0004 \u0005[וחכם זה\u0006 רב אדא\u0005]\u0006 שאמר שיש לו תשלומים \u0003סבר: אפילו טומאה נמי מדחיא\u0004 \u0005[גם כן דוחה]\u0006 לפסח שני.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שדנו חכמים בבעיה זו: \u0003היו שלישיתן\u0004 של הקהל \u0003זבין, ושלישיתן טהורין, ושלישיתן טמאי מתים,\u0004 מה יעשו? \u0003אמר ר' מני בר פטיש: אותן טמאי מתים אינן עושין לא את\u0004 הפסח \u0003הראשון ולא\u0004 את \u0003השני.\u0004","\u0003בראשון לא עבדי\u0004 \u0005[עושים]\u0006 כי \u0003הגדילו זבין\u0004 שאינם מקריבים בטומאה כלל \u0003על הטהורים\u0004 שנוסף מנין הזבים על הטהורים, ולכן \u0003לא עבדי\u0004 \u0005[עושים]\u0006 את הפסח \u0003בטומאה, הוה ליה\u0004 \u0005[נעשו להם]\u0006 \u0003טמאי מתים\u0004 בפסח ראשון \u0003מיעוטא\u0004 \u0005[מיעוט]\u0006 בלבד, \u0003ומיעוטא\u0004 \u0005[ומיעוט]\u0006 \u0003לא עבדי\u0004 \u0005[עושים]\u0006 \u0003ב\u0004פסח \u0003ראשון\u0004 בטומאה. ואילו \u0003בשני לא עבדי\u0004 \u0005[עושים]\u0006 מטעם אחר: \u0003נצרפו\u0004 \u0005[מצטרפים]\u0006 \u0003זבין\u0004 שנטהרו בינתיים \u0003עם טמאי מתים\u0004 שכולם יחד \u0003לא עבדי\u0004 \u0005[עשו]\u0006 בפסח \u0003ראשון, הוו להו רובא\u0004 \u0005[ונעשו להם רוב\u0006 הקהל\u0005]\u0006 שצריכים לעשות את הפסח, \u0003ורובא\u0004 \u0005[ורוב]\u0006 הקהל \u0003לא מדחו\u0004 \u0005[נדחים]\u0006 \u0003לפסח שני.\u0004","\u0003הפסח שנזרק דמו ואחר כך נודע שהוא\u0004 הבשר או הדם \u0003טמא — הציץ\u0004 של כהן גדול \u0003מרצה\u0004 בדיעבד על הטומאה, והבעלים פטורים מלעשות פסח שני. נודע לאחר מכן ש\u0003נטמא הגוף\u0004 של הבעלים עצמם \u0003אין הציץ מרצה\u0004 וחייב לעשות פסח שני, \u0003מפני שאמרו\u0004 חכמים: \u0003הנזיר ועושה פסח, הציץ מרצה על טומאת הדם\u0004 או הבשר של הקרבן אבל \u0003אין הציץ מרצה על טומאת הגוף\u0004 של מביא הקרבן.","ועוד הלכה: אם נודע לאחר שהקריב כי \u0003נטמא הגוף טומאת תהום\u0004 שהוא כינוי לטומאת ספק וכגון שאמרו לו שבאותו בית ששהה בו באותו זמן היה קבר מתחת למקום מושבו — \u0003הציץ מרצה.\u0004","בדין הפסח, שנודע שהוא טמא לאחר זריקת הדם, מדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 ש\u0003נזרק\u0004 הדם \u0003ואחר כך נודע\u0004 שהוא טמא \u0003אבל\u0004 אם \u0003נודע\u0004 שנטמא \u0003ואחר כך נזרק\u0004 הדם בשוגג או במזיד — \u0003לא מרצה\u0004 הציץ.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממקור אחר, ששנינו \u0003על מה הציץ מרצה? — על הדם ועל הבשר ועל החלב שנטמא בין בשוגג בין במזיד, בין באונס בין ברצון בין ביחיד בין בציבור\u0004 משמע שהציץ מרצה בכל מקרה ואפילו כשנזרק הדם במזיד!","\u0003אמר רבינא\u0004 כך יש להבין את ההלכה בענין הציץ: על \u0003טומאתו\u0004 שהיתה \u0003בין בשוגג בין במזיד — הורצה\u0004 על ידי הציץ, אולם על \u0003זריקתו\u0004 של הדם, אם נזרק \u0003בשוגג — הורצה,\u0004 אבל \u0003במזיד לא הורצה.\u0004","\u0003ר' שילא אמר\u0004 כך יש להבין את הדברים: \u0003זריקתו\u0004 של הדם של קרבן טמא \u0003בין בשוגג בין במזיד — הורצה, טומאתו\u0004 של הקרבן אם היתה \u0003בשוגג — הורצה,\u0004 אבל \u0003במזיד — לא הורצה.\u0004","ומסבירים: \u0003אלא הא דקתני\u0004 \u0005[זו ששנינו]\u0006 \u0003\"בין בשוגג בין במזיד\" הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003נטמא\u0004 הקרבן \u0003בשוגג, וזרקו בין בשוגג בין במזיד — הורצה.\u0004","\u0003והא דקתני\u0004 \u0005[וזו ששנינו\u0006 במשנתנו\u0005]\u0006 \u0003דם שנזרק ואחר כך נודע\u0004 מענין הטומאה, אין לדייק מן הדברים (כמו שדייקנו קודם) \u0003דט עמא\u0004 \u0005[שהטעם]\u0006 דווקא ש\u0003נזרק\u0004 הדם \u0003ואחר כך נודע\u0004 שהוא טמא \u0003אבל\u0004 אם \u0003נודע\u0004 שנטמא \u0003ואחר כך נזרק\u0004 הדם בשוגג או במזיד \u0003לא\u0004 מרצה הציץ, שכן \u0003הוא הדין\u0004 ש\u0003אפילו נודע ואחר כך נזרק\u0004 גם אז הציץ מרצה.","\u0003והאי דקתני\u0004 \u0005[וזו ששנינו]\u0006 \u0003נזרק ואחר כך נודע\u0004 אין לדייק ממנו אלא \u0003משום דבעי למתני לסיפא\u0004 \u0005[שרוצה לשנות את סוף\u0006 המשנה\u0005]\u0006 \u0003נטמא הגוף אין הציץ מרצה\u0004 ורצה להדגיש שבטומאת הגוף, \u0003אפילו נזרק ואחר כך נודע\u0004 שנטמא — \u0003לא\u0004 הורצה, לכן \u0003קתני רישא נמי\u0004 \u0005[שנה בתחילה גם כן]\u0006 \u0003נזרק ואחר כך נודע,\u0004 והוא הדין אם היה להיפך.","שנינו במשנה שאם \u0003נטמא טומאת התהום\u0004 הציץ מרצה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: כהן המרצה בקרבנותיהן\u0004 של עושי הפסח והנזיר, האם \u0003הותרה\u0004 גם \u0003לו טומאת התהום, או לא? מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003כי גמירי\u0004 \u0005[כאשר למדנו\u0006 קבלנו במסורת\u0005]\u0006 את ההיתר ב\u0003טומאת התהום\u0004 הרי זה \u0003בבעלים\u0004 של הקרבן אבל \u0003בכהן לא גמירי\u0004 \u0005[למדנו,\u0006 לא קבלנו\u0005],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003בזיבחא\u0004 \u0005[בזבח]\u0006 עושה פסח ונזיר בכלל \u0003גמירי\u0004 \u0005[למדנו,\u0006 קיבלנו\u0005].\u0006 \u0003ו\u0004לכן \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם היתה טומאה \u0003בכהן ולא שנא\u0004 \u0005[שונה]\u0006 אם היתה \u0003בבעלים.\u0004","ומציעים, \u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה, \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא: לא אמרו טומאת התהום אלא\u0004 לטומאת \u0003מת בלבד.\u0004 ונדייק: \u0003מת למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 \u0003לאו למעוטי\u0004 \u0005[האם לא למעט]\u0006 \u0003טומאת התהום\u0004 של \u0003שרץ,\u0004 שאם נטמא בשרץ שלא היה ידוע בכל זאת לא הורצה.","ונברר, \u0003ובמאי עסקינן\u0004 \u0005[ובמה\u0006 באיזה מקרה \u0005עוסקים אנו]\u0006 \u0003אי נימא\u0004 \u0005[אם תאמר]\u0006 שמדובר כאן שנטמאו \u0003הבעלים. ובמאן\u0004 \u0005[ובמי\u0006 מדובר\u0005]?\u0006 \u0003אי\u0004 \u0005[אם\u0006 מדובר\u0005]\u0006 \u0003בנזיר — מי מהני ביה\u0004 \u0005[האם מועיל\u0006 משנה, בו\u0005]\u0006 טומאה של שרץ לסתור את נזירותו ולהצריכו להביא קרבן אחר? והלוא נאמר: \u0003\"וכי ימות מת עליו\u0004 בפתע פתאום וטימא ראש נזרו וגלח ראשו ביום טהרתו ביום השביעי יגלחנו\u0003\"\u0004 (במדבר ו, ט) במת \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 ולא בטומאת שרץ, שלא נתבטלה הנזירות אלא בטומאת מת בלבד.","\u0003אלא\u0004 תאמר שמדובר כאן \u0003בעושה פסח.\u0004 ואמנם \u0003הניחא למאן\u0004 \u0005[\u0006שיטה \u0005זו תהא נוחה למי]\u0006 ש\u0003אמר אין שוחטין\u0004 הפסח \u0003וזורקין\u0004 דמו \u0003על טמאי שרץ\u0004 שלכך צריך לדון בענין טומאת התהום בו. \u0003אלא ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר שוחטין וזורקין על טמאי שרץ, השתא\u0004 \u0005[עכשיו]\u0006 הרי אתה אומר כי \u0003טומאה ידועה הותרה לו,\u0004 שאפילו כשברור שנטמא בשרץ הותרה לו טומאה זו, ושוחטים וזורקים עליו מפני שבערב יהיה כבר טהור, \u0003טומאת התהום לא כל שכן\u0004 שהותרה.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מוכרחים לומר כי לא מדובר כאן אלא \u0003בכהן\u0004 המרצה שנטמא, \u0003ושמע מינה\u0004 \u0005[ונלמד מכאן]\u0006 \u0003הותרה לו טומאת התהום!\u0004","\u0003אמר רב יוסף: לא,\u0004 אין להוכיח מכאן, \u0003לעולם\u0004 אפשר לומר כי מדובר כאן בשנטמאו ב\u0003עלים\u0004 בטומאת התהום, ומדובר דווקא בעושי \u0003פסח.\u0004 ודיוק זה שלמדנו שלא אמרו טומאת התהום אלא למת בלבד הרי זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 את \u0003טומאת התהום\u0004 של \u0003זיבה.\u0004 שטומאה בלתי ידועה לחלוטין הקשורה בדיני זיבה ונדה, אין לה ריצוי ציץ.","ומקשים: וכי \u0003טומאת תהום\u0004 של \u0003זיבה לא מרצה\u0004 הציץ עליה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' יוסי אומר: שומרת יום כנגד יום\u0004 שהיא אשה שראתה דם יום אחד או שנים שלא בימי נדתה, ומדין תורה היא צריכה להמתין יום נוסף ולבדוק עצמה, ואם לא תראה דם — הרי היא טהורה, ואם תראה דם ביום השלישי הריהי מטמאה כזבה. ואותה אשה \u0003שחטו וזרקו עליה\u0004 (בשבילה)"],["\u0003בשני שלה\u0004 שספק הוא אם תראה דם גם היום וגם למחרת ויצטרפו לשלושה ימים ותהיה זבה גדולה או לא ותיטהר לעת ערב, \u0003ואחר כך ראתה\u0004 דם, ונתברר למפרע שהיא זבה \u0003אינה אוכלת\u0004 מן הפסח משום טומאה, אבל \u0003פטורה מלעשות פסח שני.\u0004","ונברר: \u0003מאי טעמא\u0004 \u0005[מה טעמה]\u0006 של הלכה זו, מדוע פטורה מפסח שני? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דמרצי\u0004 \u0005[שמרצה]\u0006 \u0003ציץ\u0004 עליה? ואם כן נמצא כי הציץ מרצה על ספק טומאה. שהרי בשעת זריקת הדם ספק הוא אם היא נחשבת כזבה או לא, ולכך ירצה אף על טומאת תהום שבזבה! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיית הוכחה זו: \u0003לא\u0004 זה הטעם, אלא \u0003משום דקסבר\u0004 \u0005[שסבור הוא]\u0006 \u0003ר' יוסי: מכאן ולהבא היא מטמאה.\u0004 שלדעתו שומרת יום כנגד יום שראתה ביום השלישי אין אומרים שהתחילה זיבתה מהיום הראשון, אלא רק מן היום השלישי, בו הוכרה כזבה גדולה.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 שבה נאמר להיפך, \u0003ר' יוסי אומר: זב בעל שתי ראיות\u0004 שראה זוב רק שתי פעמים (שהוא טמא שבעה ימים, אבל יש לו תיקון בטבילה בלבד ואינו זקוק עוד לקרבן טהרה ביום השמיני) \u0003ששחטו\u0004 קרבן פסח \u0003וזרקו עליו\u0004 דמו ביום \u0003שביעי שלו, ואחר כך\u0004 באותו יום \u0003ראה\u0004 זוב נוסף והוא עתה זב בעל שלוש ראיות, וצריך להמתין שבעה ימים ולהביא קרבן להטהר. \u0003וכן שומרת יום כנגד יום ששחטו וזרקו עליה בשני שלה ואחר כך ראתה — הרי אלו מטמאין משכב ומושב למפרע\u0004 שכל משכב ומושב שנגעו בהם נטמא למפרע, מן היום בו ראו את הזיבה הראשונה,","אבל \u0003פטורים מלעשות פסח שני.\u0004 ומכאן ראיה שסבור ר' יוסי שטומאתם היא למפרע, וממילא בשעת זריקת דם הפסח הריהי ספק טמאה ונמצא מרצה הציץ על ספק וירצה אם כן אף על טומאת התהום של זיבה!","ודוחים: \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 למפרע בדברי ר' יוסי אלה, כוונתו היא רק \u0003מדרבנן\u0004 \u0005[מ\u0006דברי \u0005סופרים]\u0006 בלבד, שהחמירו בו להחשיבו כטמא, אבל מדין תורה אכן אינם מטמאים אלא מכאן ולהבא.","ומעירים, \u0003ואף ר' אושעיא סבר\u0004 כי זב כעין זה ושומרת יום כנגד יום לשיטת ר' יוסי \u0003מטמא למפרע מדרבנן\u0004 \u0005[מ\u0006דברי \u0005סופרים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' אושעיא אומר: אבל זב שראה בשביעי שלו — סותר את\u0004 ימי הטהרה \u0003שלפניו,\u0004 ונחשב למפרע כזב בכל אותם ימים. \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: לא יסתור אלא יומו,\u0004 אותו יום שראה בו בלבד ולא יוסיף לספור אלא יום אחד בלבד!","ותוהים: \u0003ממה נפשך,\u0004 כלומר, מכל צד שתעיין בדבר דעה זו תמוהה; \u0003אי קסבר\u0004 \u0005[אם סבור]\u0006 ר' יוחנן \u0003למפרע הוא מטמא — אפילו כולהו\u0004 \u0005[\u0006את כל הימים \u0005כולם]\u0006 \u0003נסתור,\u0004 כדברי ר' אושעיא. \u0003אי קסבר\u0004 \u0005[אם סבר]\u0006 \u0003מכאן ולהבא הוא מטמא — יומו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא נסתור\u0004 שהרי מקצת היום שספר נחשב ככולו ונגמרה ספירתו בלא ראיה נוספת! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 תקן בלשונו, שכך אמר ר' יוחנן: \u0003לא יסתור ולא יומו,\u0004 אפילו לא את יומו.","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 ר' אושעיא: אמנם אין דעתי כן, אבל דע לך כי \u0003ר' יוסי\u0004 הפוטר מפסח שני את הרואה זוב כעין זה \u0003קאי כוותך\u0004 \u0005[עומד בשיטתך\u0006 סבור כמותך\u0005]\u0006 שמכאן ולהבא הוא מטמא, ולכאורה \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ר' יוסי אומר: מטמאין משכב ומושב למפרע! אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמה שאומרים \u0003מטמא למפרע הוא מדרבנן\u0004 \u0005[מ\u0006דברי \u0005חכמים]\u0006 בלבד, ולא מן התורה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","ושואלים: \u0003ולר' יוסי, השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמר\u0004 שבטומאת הזיבה \u0003מכאן ולהבא מטמא\u0004 ואם כן לענין פסח אין צורך בריצוי ציץ על טומאת תהום של זיבה, שהרי גם בלא כן שוחטים וזורקים קרבן פסח עבור אלה, אם כן הלכה זו שאין טומאת התהום אלא \u0003למת בלבד, למעוטי מאי\u0004 \u0005[למעט מה]?\u0006","ולכאורה \u0003נפשוט מינה\u0004 \u0005[נפתור מכאן]\u0006 את שאלתנו, שודאי בא הדבר למעט טומאת שרץ, ולפי מה שאמרנו קודם, נמצא שמדובר \u0003בכהן, והותרה לו טומאת התהום,\u0004 ותפתר איפוא בעיית רמי בר חמא.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיה: \u0003לעולם\u0004 יכול אתה לפרש שמדובר כאן בטומאת \u0003בעלים,\u0004 וכן מדובר כאן בקרבן \u0003פסח, וקסבר\u0004 \u0005[וסבור הוא]\u0006 \u0003אין שוחטין וזורקין על טמאי שרץ,\u0004 ויש איפוא מקום לדון בדינם של הנטמאים בשרץ בלא יודעים, ולכן \u0003איצטריך למעוטי\u0004 \u0005[הוצרך למעט]\u0006 ולומר שטומאת התהום היא רק בטומאת מת ולא בטומאת שרץ.","ועוד שואלים: \u0003אלא\u0004 לענין שומרת יום כנגד יום \u0003לר' יוסי זבה גמורה\u0004 שמטמאה \u0003היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]?\u0006 שאם שומרת יום כנגד יום אינה מטמאה בראיה שלישית למפרע, וראיה שלישית נחשבת כאילו היתה ראשונה כיצד אפשר לצרף שלוש ראיות לטומאה? הלוא תמיד תחשבנה כנפרדות זו מזו, ואין כאן שלוש יחד!","ומשיבים: \u0003בשופעת,\u0004 כגון שהיתה שותתת דם במשך שלושת הימים ברציפות. \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 באופן אחר: \u0003כגון שראתה כל שני בין השמשות,\u0004 שראתה כל משך זמן של בין השמשות ביום אחד וביום השני, שאז ודאי היא טמאה כל היום השלישי כולו, שהרי לא היה הפסק טהרה בין יום ליום.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב יוסף: כהן המרצה\u0004 בקרבן ה\u0003תמיד,\u0004 האם \u0003הותרה לו טומאת התהום או לא?\u0004 וצדדי השאלה: \u0003אם תמצא לומר\u0004 ולקבל את ההנחה כי \u0003כהן המרצה בקרבנותיהן של נזיר ועושה פסח הותרה לו טומאת התהום, כהן המרצה בתמיד מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003כי גמירי\u0004 \u0005[כאשר למדנו,\u0006 קבלנו\u0005]\u0006 דין \u0003טומאת התהום\u0004 הרי זה בקרבן \u0003פסח,\u0004 אבל בקרבן \u0003תמיד לא גמירי.\u0004 \u0005[למדנו]\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003יליף\u0004 \u0005[לומד]\u0006 \u0003תמיד מפסח\u0004 בגזירה שוה.","\u0003אמר רבה:\u0004 אפשר לפתור בעיה זו על ידי \u0003קל וחומר: ומה במקום שלא הותרה לו טומאה ידועה\u0004 בעושה פסח ונזיר, שיחיד העושה את הפסח או נזיר המביא את קרבנו ונטמא בטומאה ידועה אין לו היתר וחייב בפסח שני בכל זאת \u0003הותרה לו טומאת התהום, מקום שהותרה לו טומאה ידועה\u0004 בקרבנות הציבור, שאם הצבור טמא הותרה אפילו טומאה ידועה, שהם קרבים אפילו בטומאה —"],["\u0003אינו דין שהותרה לו טומאת התהום\u0004 לגמרי אפילו אם יש כהנים אחרים טהורים.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיה: \u0003ומי דיינינן\u0004 \u0005[והאם דנים אנו]\u0006 \u0003קל וחומר מהלכה\u0004 למשה מסיני? ודין טומאת התהום הוא הלכה למשה מסיני, וכלל הוא שאין דנים קל וחומר מהלכה. \u0003והתניא\u0004 \u0005[ש\u0006אכן כן \u0005הרי שנינו\u0006 בברייתא\u0005],\u0006 שבה רצה ר' עקיבא ללמוד טומאת דם מטומאת עצם שאף על מגעה ומשאה מגלח הנזיר כבמגע או משא עצם המת, בקל וחומר, \u0003אמר לו ר' אליעזר: עקיבא,\u0004 טומאת \u0003עצם כשעורה הלכה\u0004 למשה מסיני היא, וטומאת \u0003רביעית דם\u0004 רוצה אתה ללמוד אותה ממנה ב\u0003קל וחומר, ואין דנין קל וחומר מהלכה!\u0004 ואם כן אף בבעיה שלנו — אינך יכול ללמוד קל וחומר מהלכה.","\u0003אלא אמר רבא: יליף\u0004 \u0005[לומד]\u0006 בגזירה שוה \u0003\"מועדו\" \"מועדו\" מפסח\u0004 שממנו למדים להשוות דין פסח ודין תמיד, כשם שבקרבן פסח טומאת התהום נרצית לכהן — כן גם בקרבן תמיד.","לעצם הדברים שואלים: \u0003וטומאת התהום גופא\u0004 \u0005[עצמה]\u0006 שהתירוה בנזיר ועושה פסח בריצוי ציץ \u0003היכא כתיבא\u0004 \u0005[היכן\u0006 היא \u0005כתובה]?\u0006 \u0003אמר ר' אלעזר: אמר קרא\u0004 \u0005[המקרא]\u0006 בנזיר: \u0003\"וכי ימות מת עליו\u0004 בפתע פתאום\u0003\"\u0004 (במדבר ו, ט), והדגשה זו מלמדת: כשהיתה הטומאה \u0003מחוורת\u0004 (ברורה) \u0003עליו,\u0004 אבל טומאה שאינה ידועה אינה קרויה טומאה.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ראיה לענין \u0003נזיר, עושה פסח מנלן\u0004 \u0005[מנין לנו]\u0006 שהותרה בו טומאת התהום? \u0003אמר ר' יוחנן: אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"\u0004איש איש כי יהיה טמא לנפש או \u0003בדרך רחקה לכם\"\u0004 (במדבר ט, ט) כוונתו \u0003במחוורת לכם\u0004 וטומאה שאינה ברורה אין אומרים שיהא עושה הפסח טמא בה.","\u0003ר' שמעון בן לקיש אמר:\u0004 אפשר ללמוד באופן אחר, מן המלה \"דרך\" הסמוכה ל\"כי יהיה טמא\"; \u0003כדרך — מה דרך\u0004 היא \u0003בגלוי — אף טומאה נמי\u0004 \u0005[גם כן]\u0006 \u0003בגלוי.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על ראיות אלה ממה ששנינו: \u0003אי זהו טומאת התהום\u0004 שהותרה לנזיר ולעושה פסח \u0003— כל שלא הכיר בה\u0004 אפילו אדם \u0003אחד\u0004 ואפילו \u0003בסוף העולם,\u0004 אבל אם \u0003הכיר בה\u0004 אפילו אדם \u0003אחד בסוף העולם — אין זה טומאת התהום.\u0004 ואילו לשיטת \u0003ר' אלעזר\u0004 ש\u0003אמר\u0004 שהראיה היא ממה שנאמר \"עליו\", ולמדים מכאן \u0003במחוורת עליו,\u0004 אם כן טומאה מחוורת תיחשב רק \u0003עד דידע הוא\u0004 \u0005[עד שידע הוא\u0006 עצמו\u0005]\u0006 שיש כאן טומאה ואין די שאחרים יודעים","ו\u0003לר' יוחנן\u0004 ש\u0003אמר\u0004 שהענין נלמד מהמלה \u0003\"לכם\" במחוורת לכם\u0004 — צריך שיהיה לפחות \u0003עד דידעי\u0004 \u0005[שידעו]\u0006 \u0003בה\u0004 בטומאה \u0003תרין\u0004 \u0005[שני]\u0006 אנשים,","ו\u0003לר' שמעון בן לקיש\u0004 ש\u0003אמר\u0004 צריך להיות \u0003כדרך\u0004 שלמדים מן המילה \"דרך\" צריך שיהיה \u0003עד דידעי כולי עלמא\u0004 \u0005[שידעו כל העולם\u0006 על כך\u0005]!\u0006","\u0003אלא\u0004 עלינו לחזור מכל הראיות שהבאנו, ולומר \u0003טומאת התהום הלכתא גמירי לה\u0004 \u0005[הלכה למדו,\u0006 קבלו, \u0005אותה]\u0006 במסורת ממשה מסיני, \u0003וקרא\u0004 \u0005[והמקרא]\u0006 שהביאו \u0005—\u0006 \u0003אסמכתא בעלמא\u0004 \u0005[סמך בלבד\u0006 הוא\u0005]\u0006 לזיכרון בלבד, ולא כמקור לדין.","\u0003אמר מר בר רב אשי: לא שנו\u0004 שהציץ מרצה על טומאת התהום בנזיר ועושה פסח \u0003אלא\u0004 כ\u0003שנודע לו לאחר זריקה, דכי איזדריק\u0004 \u0005[שכאשר נזרק]\u0006 \u0003דם — שפיר איזדריק\u0004 \u0005[יפה נזרק]\u0006 והיה ראוי, \u0003אבל נודע לו לפני זריקה — לא מרצה,\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003המוצא מת מושכב לרחבו של דרך\u0004 שהיה טמון שם ולא יתכן שלא נטמא מן המת בדרך כלשהי אם בנגיעה, או בהיסט או באהל, אם היה זה לדין \u0003תרומה\u0004 — הרי זה \u0003טמא,\u0004 שהרי ודאי נטמא העובר, ואם היה כהן אסור לו לאכול בתרומה. ולענין \u0003נזיר ועושה פסח — טהור,\u0004 שטומאת התהום נרצית על ידי הציץ בנזיר ועושה פסח. \u0003וכל טמא וטהור\u0004 שאומרים — \u0003להבא הוא\u0004 שאומרים אותם כפסק הלכה לכתחילה ולא רק בדיעבד אם כבר נזרק דם הקרבן. משמע שטומאת התהום לא הותרה במקרים אלה כלל.","\u0003אלא אי איתמר הכי איתמר\u0004 \u0005[אם נאמר כך נאמר]\u0006 וכך יש לתקן: \u0003אמר מר בר רב אשי: לא תימא\u0004 \u0005[תאמר]\u0006 \u0003נודע לו לאחר זריקה הוא\u0004 ש\u0003מרצה אבל נודע לו לפני זריקה לא מרצה, אלא אפילו נודע לו לפני זריקה — מרצה\u0004 משום שטומאת התהום אינה נחשבת לגבי עושה פסח ונזיר.","כיון שהבאנו את הברייתא לענין טומאת התהום, דנים בה \u0003גופא\u0004 \u0005[עצמה].\u0006 \u0003המוצא מת מושכב לרחבו של דרך, ל\u0004ענין \u0003תרומה — טמא, לנזיר ועושה פסח — טהור.\u0004","\u0003במה דברים אמורים\u0004 שלתרומה טמא — \u0003שאין לו מקום לעבור\u0004 באותה דרך מבלי להאהיל על המת. \u0003אבל יש מקום לעבור\u0004 באותה דרך — \u0003אף לתרומה טהור,\u0004 שמא עבר במקום שלא היה בו המת, וספק טומאה ברשות הרבים, טהור.","וכן \u0003במה דברים אמורים\u0004 שטמא — \u0003כשמצאו,\u0004 את המת, \u0003שלם. אבל\u0004 היה \u0003משובר ומפורק — טהור, שמא בין הפרקים עבר\u0004 ולא נגע ולא האהיל. ודברים אלה אמורים כשמצאו את המת מוטל סתם, אבל \u0003בקבר, אפילו\u0004 היה המת \u0003משובר ומפורק — טמא, מפני שהקבר מצרפו.\u0004","וכן \u0003במה דברים אמורים\u0004 שמשובר ומפורק טהור — \u0003ב\u0004זמן שהעובר \u0003מהלך ברגליו, אבל\u0004 אם היה \u0003טעון\u0004 משא \u0003או רכוב\u0004 על גבי בהמה — \u0003טמא, לפי שמהלך ברגליו אפשר שלא יגע\u0004 בעצם המת ואף \u0003לא יאהל\u0004 על המת, \u0003אבל הטעון\u0004 משא על גבו ומתוך כובדו של המשא נע ונד הוא לכל צד \u0003או רכוב\u0004 שהבהמה מאהילה \u0003אי אפשר שלא יגע ולא יאהל.\u0004","\u0003במה דברים אמורים\u0004 שהנזיר ועושה פסח טהור \u0003בטומאת התהום, אבל\u0004 אם היתה זו \u0003טומאה ידועה\u0004 אלא שהוא עבר ולא ידע — \u0003טמא,\u0004","ומגדירים: \u0003ואי זה היא טומאת התהום — כל שלא הכיר בה\u0004 אפילו אדם \u0003אחד בסוף העולם. אבל\u0004 אם \u0003הכיר בה\u0004 אפילו אדם \u0003אחד\u0004 אף \u0003בסוף העולם — אין זה\u0004 נחשב \u0003טומאת התהום.\u0004","וכיצד אפשר לדעת אם הכיר אדם במת זה אי פעם? בודקים לפי האופן שנמצא; אם \u0003מצאו\u0004 למת \u0003טמון בתבן,\u0004 או \u0003בעפר,\u0004 או \u0003בצרורות\u0004 ויש מקום לחשוב שמת במפולת עפר או תבן ומאז שמת קשה להניח שמישהו הכיר בדבר — \u0003הרי זה טומאת התהום.\u0004 אבל אם מצאו מוטל \u0003במים\u0004 או \u0003באפילה\u0004 (מקום חשוך) או \u0003בנקיקי הסלעים\u0004 שאין רבים מצויים שם — \u0003אין זה טומאת התהום,\u0004 לפי שבאופן שנמצא יתכן שמישהו עבר וראה אותו שהרי הוא מקום העשוי להגלות. \u0003ולא אמרו\u0004 היתר \u0003טומאת התהום אלא למת בלבד\u0004 ולא בטומאות אחרות.","\u0003נטמא\u0004 קרבן הפסח \u0003שלם או רובו — שורפין אותו לפני הבירה\u0004 (המקדש) \u0003מעצי המערכה\u0004 שנותנים לבעלי הפסח לצורך זה. \u0003נטמא מיעוטו\u0004 וכן \u0003הנותר\u0004 מן הפסח (שכאמור בתורה יש לשרפו) \u0003שורפין אותו\u0004 בעלי הפסח \u0003בחצרותיהן. או על גגותיהן מעצי עצמן,\u0004 ורק \u0003הציקנין\u0004 (הקמצנים) שרוצים לחסוך בדמי העצים — \u0003שורפין אותו לפני הבירה בשביל ליהנות מעצי המערכה.\u0004","שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 שורפים את הפסח שנטמא לפני הבירה, ולא יניחו לרוצים בכך לשורפו במקום אחר? \u0003אמר ר' יוסי בר חנינא: כדי לביישן,\u0004 שמן הסתם לא נזהרו בו ובשל כך נטמא ולכן תיקנו שישרפו אותו במקום פומבי.","שנינו במשנה שאם \u0003נטמא מיעוטו\u0004 וכן הנותר ממנו שורפים בחצרותיהם מעצי עצמם. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך ממה ששנינו: \u0003וכן מי שיצא מירושלים ונזכר שיש בידו בשר קדש,\u0004 והבשר הזה כיון שיצא ממקומו נפסל מאכילה וטעון שריפה \u0003אם עבר\u0004 את כפר \u0003צופים — שורפו במקומו\u0004 שנזכר בו ואינו צריך לחזור ולשורפו בירושלים, \u0003ואם לאו\u0004 שעדיין לא עבר את כפר צופים —"],["\u0003חוזר ושורפו לפני הבירה מעצי המערכה\u0004 משמע מהלשון \"ונזכר שיש בידו בשר קודש\" שלא רק אם נטמא רוב הפסח אלא אפילו עבור מיעוט קרבן שצריך היה להיזכר בכלל שהוא נמצא בידו, משתמש לשריפתו מעצי המערכה!","\u0003אמר רב חמא בר עוקבא: לא קשיא\u0004 \u0005[קשה],\u0006 \u0003כאן\u0004 שאמרו ששורפו לפני הבירה בעצי המערכה — מדובר \u0003באכסנאי\u0004 שאינו קבוע בירושלים ואין ברשותו עצים ולכן שורפו מעצי המערכה. \u0003כאן\u0004 שאמרו ששורפו בביתו מעצי עצמו — מדובר \u0003בבעל הבית\u0004 הגר בקביעות בירושלים.","\u0003רב פפא אמר: הא והא\u0004 \u0005[זה וזה]\u0006 מדובר \u0003באכסנאי,\u0004 אלא \u0003כאן\u0004 כשרשאי לשורפו מעצי המערכה מדובר \u0003שהחזיק בדרך\u0004 כלומר שכבר הלך לדרכו, וקשה לו להתחיל לאסוף עצים, \u0003כאן\u0004 שאינו שורפו אלא בעצי עצמו — מדובר \u0003שלא החזיק בדרך\u0004 ויכול למצוא עצים לעצמו.","\u0003רב זביד אמר: לעולם\u0004 אפשר לפרש \u0003כ\u0004מו ש\u0003אמר\u0004 הסביר רב חמא \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003כאן באכסנאי כאן בבעל הבית, ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא החזיק בדרך,\u0004 והטעם \u0003אכסנאי כיון דלית ליה\u0004 \u0005[שאין לו]\u0006 עצים \u0003עשאוהו\u0004 ותיקנו לו בית דין שייחשב \u0003כציקנין. דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003הציקנין שורפין אותו לפני הבירה בשביל ליהנות מעצי המערכה\u0004 משמע שתיקנו בית דין שמי שאינו חש לכבודו (כציקנין) מותר לו להשתמש בעצי המערכה ואין חשש מעילה בדבר, וכמו כן התירו לאכסנאי.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים בתוספתא\u0006\u0005]:\u0006 \u0003באו\u0004 ורצו \u0003לשורפו\u0004 את הפסח שנטמא \u0003בחצרותיהן\u0004 ולקחת לשם כך \u0003מעצי המערכה — אין שומעין להן.\u0004 וכן אם היו רוצים לשורפו \u0003לפני הבירה ומעצי עצמן — אין שומעין להן.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שהרוצים לשרוף \u0003מעצי המערכה בחצרותיהן אין שומעין להן\u0004 יש טעם בדבר — \u0003דילמא פיישן מינייהו\u0004 \u0005[שמא ישארו מהם]\u0006 שלא ישתמשו בכל העצים לצורך שריפת הפסח, \u0003ואתו בהו\u0004 \u0005[ויבואו בהם]\u0006 \u0003לידי תקלה\u0004 להשתמש בהם לצורך אחר. \u0003אלא לפני הבירה מעצי עצמן, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 ישמעו להם? הלוא לכאורה הם חוסכים הוצאה למקדש!","\u0003רב יוסף אמר: שלא לבייש את מי שאין לו,\u0004 שאם ירשו לשורפים להביא עצים משל עצמם יבינו שרק העניים צריכים להשתמש בעצי המערכה ונמצאו מתביישים. \u0003רבא אמר: מפני החשד,\u0004 שמא יחזירו לביתם את העצים שנותרו ויחשדום בני אדם שהם גונבים מעצי המערכה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 \u0003דאייתי קני וחריותא\u0004 \u0005[שמביאים קנים או חריות\u0006 של דקל\u0005]\u0006 \u0003דלא חזי\u0004 \u0005[שאינם ראויים]\u0006 \u0003למערכה,\u0004 שלצורך עצי המערכה לא היו משתמשים באלה, ולכן אין בכך מקום לחשד, אבל עדיין תופס הנימוק שלא לבייש את מי שאין לו.","מחלוקת דומה לזו בנושא אחר נאמרה במשנה אחרת, \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת תמיד: \u0003ראש המעמד\u0004 הממונה על כל הכהנים השייכים למעמד, ומשמר זה \u0003היה מעמיד את\u0004 הכהנים \u0003הטמאין על\u0004 פתח \u0003שער המזרח.\u0004 ושאלו: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 מדוע לא ישלחום לבתיהם בלא העמדה זו? \u0003אמר רב יוסף: כדי לביישן\u0004 על שלא נזהרו בעצמם כראוי, ונטמאו. \u0003רבא אמר:\u0004 היו מעמידים אותם שם \u0003מפני החשד\u0004 שלא יחשדום שהם משתמטים מעבודות המקדש כדי שלא להיבטל מעבודתם הקבועה וידעו שזה מחמת הטומאה,","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 \u0003מפנקי\u0004 \u0005[מפונקים]\u0006 אנשים שאינם עובדים והכל יודעים שאינם משתמטים מחמת מלאכתם, \u0003אי נמי דקא גדיל שישורא\u0004 \u0005[או גם כן שהוא גודל\u0006 שוזר, \u0005חבלים]\u0006 שבשל עבודה פחותה ובלתי מכניסה כזו ודאי לא יבטלו מעבודת המקדש ואין כאן מקום לחשד.","\u0003הפסח שיצא\u0004 ממחיצה הראויה לו \u0003או שנטמא — ישרף מיד\u0004 עוד בערב הפסח. ואם \u0003נטמאו הבעלים או שמתו — תעובר צורתו\u0004 כלומר תתקלקל צורתו, על ידי שישאירו אותו זמן מסויים ולא ישרפוהו מיד, \u0003וישרף בששה עשר\u0004 בניסן מיד לאחר החג. \u0003ר' יוחנן בן ברוקה אומר: אף זה ישרף מיד לפי שאין לו אוכלין\u0004 ואף הוא פסול חמור שאין טעון עיבור צורה.","שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003טמא\u0004 שטעון שריפה \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקרא: \u0003\"והבשר אשר יגע בכל טמא לא יאכל באש ישרף\"\u0004 (ויקרא ז, יט), ואם כן צריך לקיים מצוה זו. \u0003אלא יוצא\u0004 ממחיצתו \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שדינו בשריפה?","ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 כאשר בא משה בטענה לאהרן ולבניו על שלא אכלו את החטאת ביום השמיני למלואים אמר להם: \u0003\"הן לא הובא את דמה אל הקדש פנימה\u0004 אכול תאכלו אתה בקודש כאשר צויתי\u0003\"\u0004 (ויקרא י, יח) וכך יש להבין, \u0003אמר לו משה לאהרן: מדוע לא אכלתם את החטאת? שמא נכנס דמה לפני ולפנים\u0004 אל הקודש וחטאת כזו דינה בשריפה. \u0003אמר לו\u0004 אהרן: \u0003לאו\u0004 \u0005[לא].\u0006","\u0003אמר לו\u0004 משה: \u0003שמא חוץ למחיצתה יצתה\u0004 ובשל כך לא אכלתם אותה? \u0003אמר לו: לאו\u0004 \u0005[לא],\u0006 \u0003בקודש היתה. אמר לו\u0004 משה: \u0003אי\u0004 \u0005[אם]\u0006 \u0003בקודש היתה\u0004 ולא יצאה \u0003\"והן לא הובא את דמה אל הקדש פנימה\" מדוע לא אכלתם אותה? מכלל\u0004 הדברים אתה למד: \u0003דאי נפקא\u0004 \u0005[שאם יוצאת]\u0006 ממחיצתה, \u0003אי נמי עייל\u0004 \u0005[או גם כן\u0006 אם \u0005נכנס]\u0006 \u0003דמה לפנים — בת שריפה היא,\u0004 ומכאן למדים לכל הקרבנות.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003נטמא גלי רחמנא\u0004 \u0005[גילתה התורה]\u0006 את הדין \u0003בקדשים קלים\u0004 שהפסוק \"והבשר אשר יגע בכל טמא לא יאכל\" נאמר בשלמים, \u0003כל שכן\u0004 שהוא הדין \u0003בקדשי קדשים. אלא יוצא, אשכחן\u0004 \u0005[מצאנו]\u0006 שכן הדין ב\u0003קדשי הקדשים,\u0004 אבל ב\u0003קדשים קלים\u0004 כגון פסח \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שגם בהם יוצא דינו בשריפה? \u0003ותו\u0004 \u0005[ועוד]\u0006 יש מקום לשאול \u0003הא דתניא\u0004 \u0005[זו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003לן דמה\u0004 של בהמת קרבן ולא נזרק ביום שחיטתה,"],["או \u0003נשפך דמה,\u0004 או \u0003יצא דמה חוץ לקלעים\u0004 (למחיצות העזרה) \u0003דקיימא לן\u0004 \u0005[שמוחזק בידינו]\u0006 שדינה \u0003בשריפה. מנלן\u0004 \u0005[מנין לנו]\u0006 הלכה זו?","ומשיבים: \u0003נפקא לן\u0004 \u0005[יוצא,\u0006 נלמד, \u0005לנו]\u0006 הענין מדרשתו של \u0003ר' שמעון דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' שמעון אומר\u0004 נאמר: \u0003\"\u0004וכל חטאת אשר יובא מדמה אל אהל מועד לכפר \u0003בקדש\u0004 לא תאכל \u0003באש תשרף\"\u0004 (ויקרא ו, כג) — \u0003לימד על חטאת ששריפתה בקדש.\u0004","\u0003אין לי אלא זו בלבד, שאר פסולי קדשי קדשים ואימורי קדשים קלים מנין\u0004 שאף דינם להשרף בעזרה שהיא מחיצתן בשעת כשרותם? \u0003תלמוד לומר: \"וכל... בקדש... באש תשרף\"\u0004 לאמור כל שהוא דבר של קודש — בקודש תהא שריפתו.","ומקשים שוב: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 דין זה לענין \u0003קדשי קדשים,\u0004 אולם \u0003קדשים קלים מנלן\u0004 \u0005[מנין לנו]\u0006 שגם בהם נוהגת הלכה זו? \u0003אלא\u0004 כך צריך לומר: \u0003כל\u0004 ש\u0003פסולו בקדש\u0004 דינו \u0003בשריפה, לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היה זה \u0003קדשים קלים ולא שנא\u0004 \u0005[שונה]\u0006 \u0003קדשי קדשים,\u0004 וכל אלה \u0003גמרא גמירי לה\u0004 \u0005[במסורת נלמדים הם]\u0006 ואילו \u0003חטאת\u0004 של \u0003אהרן\u0004 זו ששרפוה בשמיני למילואים לא היה צורך להשמיע שדינה בשריפה אלא \u0003משום מעשה שהיה כך היה,\u0004 ולא בא אותו מעשה ללמדנו דבר להלכות קדשים.","ושואלים: ולשיטת \u0003תנא דבי\u0004 \u0005[מבית]\u0006 מדרשו של \u0003רבה בר אבוה,\u0004 ש\u0003אמר: אפילו פיגול\u0004 שפסולו בגופו וטעון שריפה \u0003טעון עיבור צורה\u0004 שילינוהו עד למחרת ויתקלקל מעט, ואז שורפים אותו. \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 סברה זו?","ומשיבים: \u0003יליף\u0004 \u0005[לומד]\u0006 בגזירה שוה מן המלים השוות \u0003\"עו‍ן\" \"עו‍ן\"\u0004 האמורות גם בפיגול (\"פיגול יהיה והנפש האוכלת ממנו עוונה תישא\". ויקרא ז, יח) וגם ב\u0003נותר\u0004 (\"והנותר... באש ישרף... ואוכליו עוונו ישא\". ויקרא יט, ו. וויקרא יט, ח)\u0003.\u0004 ולכן נוהגים בפיגול להלינו כדי שתעובר צורתו ולאחר מכן שורפים אותו ויהא דינו כדין נותר.","ומקשים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 \u0003\"עו‍ן\" \"עו‍ן\" מחטאת\u0004 של \u0003אהרן\u0004 בימי המילואים (\"מדוע לא אכלתם את החטאת... ואותה נתן לכם לשאת את עוון העדה\". ויקרא י, יז), שאף בה נאמר \"עון\" ונשרפת מיד, ללא עיבור צורה! \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 תנא זה: \u0003חטאת\u0004 של \u0003אהרן כי האי גוונא\u0004 \u0005[בכגון זה,\u0006 במקרה כזה\u0005]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003עיבור צורה לדורות בעיא\u0004 \u0005[צריכה]\u0006 \u0003והתם\u0004 \u0005[ושם]\u0006 בחטאת אהרן ששרפוה מיד — \u0003הוראת שעה היתה.\u0004","ושואלים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 שקיבלנו את המסקנה ש\u0003כל פסולי\u0004 (פסולים) של \u0003קדש בשריפה, לא שנא\u0004 \u0005[אינו שונה]\u0006 פסול \u0003קדשי קדשים, ולא שנא\u0004 \u0005[ואינו שונה]\u0006 של \u0003קדשים קלים,\u0004 כל אלה \u0003גמרא גמירי לה\u0004 \u0005[במסורת למדים אותה].\u0006 ושואלים: אם כן הכתוב \u0003\"בקדש... באש תשרף\" למה לי?\u0004 מה מלמדנו כתוב זה שלא ידענו מאותה מסורת? ומשיבים: \u0003ההוא מבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו]\u0006 כדי ללמד שדין השריפה הנלמד מאותה מסורת אינו יכול להתבצע בכל מקום אלא \u0003שריפתה\u0004 תהיה \u0003בקדש\u0004 בלבד.","ועוד שואלים: אם למדנו דין זה מן המסורת, מה שנאמר \u0003\"והבשר אשר יגע בכל טמא לא יאכל באש ישרף\"\u0004 (ויקרא ז, יט) \u0003למה לי?\u0004 הלוא אף טומאת הקרבן בכלל פסולי הקודש, ומה צורך בכתוב מיוחד?","ומשיבים: \u0003ההוא, לגופיה איצטריך\u0004 \u0005[אותו\u0006 כתוב, \u0005לעצמו הוצרך]\u0006 \u0003סלקא דעתך אמינא\u0004 \u0005[עולה על דעתך לומר]\u0006 \u0003כל פסולי\u0004 (פסולים) של \u0003קדש\u0004 כולל דברים \u0003כגון: לן דמה\u0004 ולא נזרק ביומו, או \u0003נשפך דמה,\u0004 או \u0003יצא דמה\u0004 מחוץ לקלעים, \u0003ו\u0004כן בהמת קרבן \u0003נשחטה בלילה,\u0004 שכל אלה דינם \u0003בשריפה\u0004 שהם פסולי קודש מיוחדים \u0003דליתנהו\u0004 \u0005[שאינם]\u0006 \u0003בחולין,\u0004 שכל אלה אינם פסולים כלל בחולין.","\u0003אבל נטמא\u0004 הבשר, ש\u0003בחולין נמי מפסיל\u0004 \u0005[גם כן נפסל],\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003הואיל ואיתעביד ביה עובדין\u0004 \u0005[ונעשו בו דברים]\u0006 של \u0003חול,\u0004 שפסולו אינו מיוחד לקדשים — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא תיבעי\u0004 \u0005[יצטרך]\u0006 קרבן \u0005זה\u0006 \u0003שריפה, ותיסגי ליה\u0004 \u0005[ודי לו]\u0006 \u0003בקבורה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב שגם פסול טומאה בקרבן טעון שריפה.","שנינו במשנה שאם \u0003נטמאו הבעלים\u0004 של הקרבן \u0003או שמתו — תעובר צורתן\u0004 של הקרבנות וישרפו לאחר החג, ור' יוחנן בן ברוקה חלק ואמר שדינם בשריפה מיד. \u0003אמר רב יוסף: מחלוקת\u0004 זו היתה כ\u0003שנטמאו בעלים אחר זריקה, דאיתחזי\u0004 \u0005[שהיה ראוי]\u0006 \u0003בשר לאכילה\u0004 שכל העבודות היו בהכשר. \u0003אבל נטמאו בעלים לפני זריקה,\u0004 ש\u0003לא איתחזי\u0004 \u0005[היה ראוי]\u0006 \u0003הבשר לאכילה\u0004 אפילו רגע אחד — \u0003דברי הכל ישרף מיד.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על סברה זו מן התוספתא: \u0003זה הכלל: כל שפסולו בגופו — ישרף מיד.\u0004 ואם היה הפסול \u0003בדם\u0004 הקרבן או \u0003בבעלים — תעובר צורתו ויצא לבית השריפה.\u0004","ונדייק: \u0003קתני\u0004 \u0005[שנה]\u0006 \u0003בעלים דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003דם, מה דם\u0004 חייבים לומר שאירע בו פסול \u0003לפני זריקה\u0004 (שהרי לאחר זריקה אינו מעלה ואינו מוריד) \u0003אף בעלים\u0004 הכוונה שהיה בהם פסול אפילו \u0003לפני זריקה\u0004 בניגוד לדברי רב יוסף.","\u0003אלא אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר דבר\u0006 בשם רב יוסף, \u0005כך נאמר]:\u0006 \u0003מחלוקת\u0004 זו דווקא כ\u0003שנטמאו בעלים לפני זריקה,\u0004 ש\u0003לא איתחזי\u0004 \u0005[היה ראוי]\u0006 \u0003הבשר לאכילה דהוה ליה\u0004 \u0005[ש\u0006הרי \u0005נעשה לו]\u0006 \u0003כפסולו בגופו. אבל נטמאו בעלים לאחר זריקה דאיתחזי\u0004 \u0005[שראוי]\u0006 ה\u0003בשר לאכילה — דברי הכל\u0004 הרי זה \u0003פסולו מחמת דבר אחר, ובעיא\u0004 \u0005[וטעונה]\u0006 \u0003עיבור צורה.\u0004","\u0003ור' יוחנן אמר: אף לאחר זריקה נמי\u0004 \u0005[גם כן]\u0006 \u0003מחלוקת\u0004 אם טעון עיבור צורה. \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003ר' יוחנן לטעמיה\u0004 \u0005[לשיטתו],\u0006 ש\u0003אמר ר' יוחנן: ר' יוחנן בן ברוקה ור' נחמיה אמרו דבר אחד,\u0004 השיטה של \u0003רבי יוחנן בן ברוקה הא דאמרן\u0004 \u0005[אמרנו]\u0006. כלומר, עיקרון אחד היה להם.","ותוהים: \u0003ר' נחמיה מאי היא\u0004 \u0005[מה הוא]\u0006 הענין שדיבר בו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' נחמיה אומר:\u0004 חטאת אהרן שנשרפה בשמיני למילואים \u0003מפני אנינות\u0004 (אבלות) \u0003נשרפה זו\u0004 שהרי באותו יום מתו נדב ואביהוא בני אהרן \u0003לכך נאמר\u0004 שהסביר אהרן למשה \"ותקראנה אותי \u0003כאלה\u0004 ואכלתי חטאת היום הייטב בעיני ה'\" (ויקרא י, יט), כלומר מאורעות של אבל כאלה, ומטעם זה נשרפה.","ומכאן ממשיך ר' יוחנן לדון \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אנינות כלאחר זריקה הויא\u0004 \u0005[היתה]\u0006 שפסול האנינות אינו פוסל את עצם עבודת הקרבת הקרבן לגבי כהן גדול כאהרן אלא הוא פסול בבעלים שאינו יכול לאכול ממנו, והוא כשאר פסולים שלאחר זריקה שכל חסרונם הוא באי היכולת לאכול את הקרבן. \u0003וכי אשתרוף לאלתר אשתרוף\u0004 \u0005[וכאשר נשרף\u0006 הקרבן \u0005מיד נשרף]\u0006 ולא המתינו לו עד למחר. משמע שגם ר' נחמיה סבור שגם קרבן שאירע בו פסול לאחר הזריקה ישרף מיד."],["\u0003רבה מוסיף\u0004 לא הם בלבד החזיקו בשיטה זו, אלא \u0003אף ר' יוסי הגלילי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יוסי הגלילי אומר: כל הענין כולו\u0004 שאמר \"וכל חטאת אשר יובא מדמה אל אהל מועד לכפר בקודש לא תאכל באש תשרף\" (ויקרא ו, כג) לא בחטאת רגילה שהכניסוה שלא כדין הוא מדבר, \u0003אינו מדבר אלא בפרים הנשרפים ובשעירין הנשרפין\u0004 שהם קרבנות חטאת מיוחדים שאמרה התורה שיש להכניס את דמם פנימה לקודש, ועל חטאות מיוחדות אלה נאמר שיש \u0003לשרוף\u0004 את \u0003פסוליהן אבית\u0004 \u0005[בבית]\u0006 \u0003הבירה\u0004 בקודש, \u0003וליתן\u0004 איסור \u0003\"לא תעשה\" על אכילתן.\u0004","\u0003אמרו לו\u0004 חכמים לר' יוסי הגלילי: אם כך דורש אתה כתוב זה, \u0003חטאת\u0004 רגילה \u0003שנכנס דמה\u0004 שלא כדין \u0003לפני ולפנים\u0004 בקודש \u0003מנין\u0004 שטעונה שריפה? \u0003אמר להן:\u0004 דבר זה נלמד מדברי הכתוב \u0003\"הן לא הובא את דמה אל הקדש פנימה\"\u0004 (ויקרא י, יח) \u0003מכלל\u0004 הדברים נלמד: \u0003דאי נפיק איהי\u0004 \u0005[שאם יצאה היא,\u0006 החטאת\u0005]\u0006 ממקומה לחוץ? \u0003אי נמי עייל\u0004 \u0005[או גם כן\u0006 אם \u0005נכנס]\u0006 \u0003דמה\u0004 לקודש, דינה \u0003בשריפה\u0004 מיד בלא עיבור צורה.","\u0003ור' יוחנן\u0004 שלא הוסיף את שיטת ר' יוסי הגלילי לשיטות אלה \u0003סבר\u0004 שיש הבדל בין השיטות כי טומאת \u0003דם ובשר חדא מילתא\u0004 \u0005[דבר אחד]\u0006 \u0003היא,\u0004 ואפשר לחשוב טומאת דם כפסול הגוף. אבל פסלות \u0003בעלים מלתא אחריתי\u0004 \u0005[דבר אחר]\u0006 \u0003היא,\u0004 שיש חכמים המתירים לשרוף את הקודש מיד בשל פסול בעלים.","\u0003העצמות\u0004 של קרבן הפסח שנשאר בהן מוח הראוי לאכילה אחר שאי אפשר לשבור את עצמות הפסח כדי לאוכלו \u0003והגידין והנותר\u0004 מן הפסח — \u0003ישרפו\u0004 כולם \u0003בששה עשר\u0004 בניסן, מיד לאחר החג. ואם \u0003חל ששה עשר\u0004 בניסן \u0003להיות בשבת — ישרפו בשבעה עשר\u0004 בו. \u0003לפי שאינן\u0004 (אין מצות שריפתם) \u0003דוחין לא את השבת ולא את יום טוב,\u0004 ונשרפים ביום החול הקרוב ביותר.","\u0003אמר רב מרי בר אבוה אמר ר' יצחק: עצמות קדשים ששמשו נותר\u0004 כלומר אלה שיש עליהן או בהן משהו שנותר מקרבן לאחר זמן אכילתו — \u0003מטמאין את הידים\u0004 כנותר עצמו, \u0003הואיל ונעשה בסיס לדבר האסור,\u0004 הריהן נדונות כמותו. ומציעים: \u0003נימא מסייע ליה\u0004 \u0005[\u0006שמא \u0005נאמר נוכל לסייע לו]\u0006 ממה ששנינו במשנתנו: \u0003העצמות והגידים והנותר ישרפו לששה עשר\u0004 בניסן.","ונברר: \u0003הני\u0004 \u0005[אותן]\u0006 \u0003עצמות היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהן עצמות \u0003דלית בהו\u0004 \u0005[שאין בהן]\u0006 \u0003מוח, למה\u0004 יהא דינן \u0003בשריפה? נשדינהו\u0004 \u0005[נזרוק אותן],\u0006 שהרי לא חייבה התורה שריפה בנותר אלא בדבר הראוי לאכילה! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 מובן, שמדובר כאן בעצמות \u0003דאית בהו\u0004 \u0005[שיש בהן]\u0006 \u0003מוח,\u0004 ומוח זה הוא חלק מבשר הקרבן, ובקרבנות אחרים היו שוברים את העצם ומוציאים את המוח ממנה.","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003שימוש נותר\u0004 דבר המשמש כבסיס וכלי לנותר \u0003מילתא היא\u0004 \u0005[דבר הוא]\u0006 ויש בו כדי לפסול כנותר עצמו, \u0003אמטו להכי\u0004 \u0005[משום כך]\u0006 \u0003בעי\u0004 \u0005[צריכים]\u0006 \u0003שריפה\u0004 כנותר עצמו. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003שימוש נותר לאו מילתא היא\u0004 \u0005[אין הוא דבר]\u0006 ואינו נחשב, \u0003למה להו\u0004 \u0005[להן]\u0006 לעצמות \u0003שריפה? נתברינהו ונחלצה למוח דידהו ונשרפיה ונשדינהו לדידהו\u0004 \u0005[נשברן ונחלוץ,\u0006 נוציא, \u0005את המוח שלהן ונשרוף אותו ונזרוק אותן עצמן]\u0006 ולא יטרח בשריפת העצמות. \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003שימוש נותר מילתא היא\u0004 \u0005[דבר הוא]\u0006 והעצמות נאסרות משום תכולת הקדשים שבתוכן וכן גם נטמאות מחמתם.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003שימוש נותר לאו מילתא\u0004 \u0005[אין הוא דבר],\u0006 \u0003וקסבר\u0004 \u0005[וסבור הוא]\u0006 התנא של משנתנו כי האיסור שנאמר בפסח \"ועצם לא תשברו בו\" (שמות יב, מו) הכוונה היא \u0003\"בו\"\u0004 בפסח \u0003כשר, ואפילו\u0004 בפסח \u0003פסול\u0004 שגם העצמות שנותרו מן הפסח ואינן כשרות עוד לאכילה אף לגביהן נשאר האיסור שלא לשבור עצם.","ותוהים: \u0003אפילו בפסול סלקא דעתך\u0004 \u0005[עולה על דעתך\u0006 לומר\u0005]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אבל המותיר\u0004 בפסח \u0003טהור\u0004 או \u0003השובר\u0004 עצם בפסח \u0003טמא — אינו סופג את הארבעים\u0004 משמע שאיסור שבירת עצם הוא רק בפסח כשר! ודוחים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003כאן\u0004 כשאמרנו שאף בפסול אסור לשבור עצם — מדובר \u0003שהיתה לו שעת הכושר\u0004 כגון נותר, שכיון שהיה שעה מסויימת שהיה \u0003כשר\u0004 בו טרם היותו נותר, חל עליו האיסור. \u0003כאן\u0004 שאומרים שאין בו איסור — הרי זה כ\u0003שלא היתה לו שעת הכושר.\u0004","ומוסיפים: \u0003ומאן\u0004 \u0005[ומי הוא]\u0006 ה\u0003תנא דשני ליה\u0004 \u0005[ששונה לו,\u0006 בעיניו\u0005]\u0006 \u0003בין\u0004 פסח \u0003שהיתה לו שעת הכושר ללא היתה לו שעת הכושר, ר' יעקב היא. דתניא\u0004 [\u0005ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 על הכתוב \u0003\"ועצם לא תשברו בו\"\u0004 מפרשים את ההדגשה \u0003\"בו\" —\u0004 דווקא \u0003בכשר ולא בפסול. ר' יעקב אומר:\u0004 קרבן ש\u0003היתה לו שעת הכושר ונפסל — יש בו משום שבירת העצם, לא היתה לו\u0004 כלל \u0003שעת הכושר — אין בו משום שבירת העצם.\u0004 ואילו \u0003ר' שמעון אומר: אחד זה ואחד זה,\u0004 בין שהיתה לו ובין שלא היתה לו שעת הכושר, כיון שנפסל — \u0003אין בו משום שבירת העצם.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003כל עצמות הקדשים אין טעונין שריפה, חוץ מעצמות הפסח מפני התקלה.\u0004 ומעתה נברר: \u0003הני עצמות היכי דמי\u0004 \u0005[עצמות אלו, כיצד\u0006 בדיוק \u0005מדובר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 באלה \u0003דלית בהו\u0004 \u0005[שאין בהן]\u0006 \u0003מוח,\u0004 אם כן \u0003למה להו\u0004 \u0005[להם]\u0006 \u0003שריפה?\u0004 שיזרקום! \u0003אלא פשיטא דאית בהו\u0004 \u0005[פשוט\u0006 שמדובר באלה \u0005שיש בהן]\u0006 \u0003מוח, ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 ש\u0003שימוש נותר מילתא היא\u0004 \u0005[דבר הוא] —\u0006 \u0003עצמות\u0004 שאר קדשים \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין טעונין שריפה?\u0004 הלוא בעצמות אלה יש מוח והוא נותר!","\u0003אמר רב נחמן בר יצחק: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 במקרה מיוחד: \u0003כגון שמצאן חלוצין\u0004 שמצא עצמות שכבר הוציאו מהן את המח. ויש מקום לחלק: \u0003עצמות קדשים\u0004 ש\u0003אין בהן\u0004 איסור משום \u0003שבירת עצם\u0004 — מן הסתם \u0003קמי דנהוו\u0004 \u0005[לפני שנעשו]\u0006 \u0003נותר חלצינהו\u0004 \u0005[חלץ מהן]\u0006 את המוח ואכלו, ואם כן עצמות אלו \u0003לא הוו\u0004 \u0005[היו]\u0006 \u0003שימוש נותר, ולא בעו\u0004 \u0005[צריכות]\u0006 \u0003שריפה,\u0004 ויכול להשליכן, ואילו","\u0003עצמות הפסח שיש בהן\u0004 איסור \u0003משום שבירת העצם,\u0004 בודאי לא בזמן איסור שבירה אלא \u0003לבתר דנהוו\u0004 \u0005[לאחר שנעשו]\u0006 \u0003נותר הוא דחלצינהו\u0004 \u0005[שחלץ מהן]\u0006 את המוח, בשעה שאין עוד איסור בשבירת עצם. \u0003והוו להו\u0004 \u0005[ונעשו להן]\u0006 העצמות לפי שעה \u0003שימוש נותר,\u0004 ולכן \u0003בעו\u0004 \u0005[צריכות]\u0006 \u0003שריפה.\u0004","\u0003רב זביד אמר:\u0004 אפשר לתרץ בדרך אחרת \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון\u0004"],["\u0003שמצאן צבורין צבורין, ומהן\u0004 אחדים שהוא רואה שהן \u0003חלוצין.\u0004 אם היו אלה \u0003עצמות קדשים\u0004 ש\u0003אין בהן משום\u0004 איסור \u0003שבירת העצם\u0004 — מן הסתם \u0003לכולהו הוה חליץ להו ואכיל להו\u0004 \u0005[לכולם היה חולץ\u0006 את המוח \u0005ואוכל אותן],\u0006 \u0003ולא בעי\u0004 \u0005[צריכות]\u0006 \u0003שריפה.\u0004","ואילו \u0003עצמות הפסח\u0004 ש\u0003יש בהן\u0004 איסור \u0003משום שבירת העצם, דילמא הני דחלצינהו\u0004 \u0005[שמא אלה ש\u0006רואה אותן \u0005חלוצות]\u0006 כבר חלץ מהן את המוח, \u0003ולהנך\u0004 \u0005[ולאחרות]\u0006 ש\u0003לא\u0004 בדק ולא \u0003חלצינהו\u0004 \u0005[חלץ מהן]\u0006 את המוח, \u0003ובעי\u0004 \u0005[וצריכות]\u0006 \u0003שריפה.\u0004 ואם כן לא מחמת שימוש נותר נאסרו העצמות, אלא מחמת נותר עצמו שבהן.","\u0003אמר רב יהודה אמר רב: כל הגידין\u0004 שבבהמה דינם כ\u0003בשר\u0004 שיוצאים בהם ידי חובת קרבן פסח ונמנים עליהם. \u0003חוץ מגידי צואר\u0004 שמפני קשיותם אינם נחשבים כלל כבשר.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003העצמות והגידים והנותר — ישרפו בששה עשר.\u0004 ונברר: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003גידין\u0004 שנזכרו \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהם \u0003גידי בשר — ניכלינהו\u0004 \u0005[שיאכלו אותם],\u0006 ומדוע ישרפום? \u0003ואי\u0004 \u0005[ואם]\u0006 הם גידים \u0003דאיתותר\u0004 \u0005[שנשארו]\u0006 ולא אכלום מפני סיבה אחרת — \u0003היינו\u0004 \u0005[הרי הם]\u0006 ה\u0003נותר\u0004 ומה טעם לחזור ולשנותם? \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שהכוונה היא ל\u0003גידי צואר,\u0004 השונים משאר הגידים והיה צורך ללמד עליהם במפורש.","\u0003אי אמרת בשלמא בשר נינהו\u0004 \u0005[נניח אם אומר אתה\u0006 שגידים אלה דינם \u0005כבשר],\u0006 \u0003אמטו להכי בעי\u0004 \u0005[משום כך צריכים]\u0006 \u0003שריפה, אלא אי אמרת לאו\u0004 \u0005[אם אומר אתה\u0006 ש\u0005לא]\u0006 \u0003בשר נינהו\u0004 \u0005[הם] —\u0006 \u0003למה להו\u0004 \u0005[להם]\u0006 \u0003שריפה?\u0004 ישליכם, כשאר פסולת! \u0003אמר רב חסדא: לא נצרכא\u0004 \u0005[נצרכה]\u0006 משנה זו בגידים \u0003אלא לגיד הנשה, ואליבא\u0004 \u0005[ועל פי\u0006 שיטת\u0005]\u0006 \u0003ר' יהודה.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 איסור גיד הנשה \u0003אינו נוהג\u0004 מן התורה \u0003אלא\u0004 בירך \u0003אחת\u0004 של בהמה ולא בשתיהן, \u0003והדעת מכרעת\u0004 שהוא \u0003של\u0004 ירך \u0003ימין.\u0004 אבל כיון שאין בידינו הוכחה גמורה לכך יש לחלוץ את גיד הנשה משתי הירכיים, ומעיקר הדין אותו גיד האסור באכילה אפשר לזורקו, והשני מותר באכילה, אבל מתוך הספק אין אנו אוכלים את שניהם וכיון שאיננו יודעים איזהו האסור — שורפים מלכתחילה את שניהם.","ושואלים: \u0003אלא תפשוט דספוקי מספקא ליה\u0004 \u0005[תפתור\u0006 מכאן \u0005שמסופק לו]\u0006 הדבר \u0003לר' יהודה\u0004 בענין גיד הנשה. שכאשר דנו חכמים בנושא זה לא מצאו פתרון לשאלה האם ר' יהודה בטוח שהוא של ירך ימין, או שאמר רק כי הדעת נוטה לכך, אבל אינו בטוח בדבר. \u0003דאי מיפשיט פשיטא ליה\u0004 \u0005[שאם פשוט לו,\u0006 בעיניו\u0005]\u0006 הדבר שהוא של ירך ימין, אם כן יש לנהוג אחרת: \u0003ההיא דהיתירא ניכליה\u0004 \u0005[אותו\u0006 ירך \u0005של היתר שיאכל את גידה]\u0006 \u0003ודאיסורא נישדייה\u0004 \u0005[ושל איסור שיזרקנו]\u0006 ובין זו ובין זו \u0003למה ליה\u0004 \u0005[לו]\u0006 לדון אותה \u0003בשריפה!\u0004","\u0003אמר רב איקא בר חיננא: כגון שהוכרו\u0004 הגידים מן הירכיים \u0003ולבסוף נתערבו,\u0004 שתחילה ידע איזהו גיד מירך ימין שהוא אסור, ואיזה מירך שמאל שהוא מותר, ולבסוף נתערבו הגידים, ומשום הספק אי אפשר לאכול את שניהם וטעונים שריפה.","\u0003רב אשי אמר: לא נצרכא\u0004 \u0005[נצרכה]\u0006 ההלכה שבמשנה על שריפת הגידים \u0003אלא לשמנו\u0004 (שומנו) של \u0003גיד הנשה. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003שמנו\u0004 של גיד המצוי סביבו \u0003מותר\u0004 מן התורה, אבל \u0003ישראל קדושים הם ונוהגין בו איסור\u0004 וכיון שמותר מן התורה — דין בשר עליו שאסור להשליכו כבשר קרבן הפסח עצמו, וכיון שישראל נזהרים מלאוכלו אין אוכלים אותו אף בפסח, ולכן נשאר עד לאחר זמנו ונשרף כדין נותר.","\u0003רבינא אמר:\u0004 מדובר כאן \u0003ב\u0004גיד ה\u0003חיצון, וכ\u0004שיטת \u0003רב יהודה אמר שמואל.\u0004 ש\u0003אמר רב יהודה אמר שמואל: שני גידין הן\u0004 בגיד הנשה, הגיד ה\u0003פנימי הסמוך לעצם — אסור\u0004 מן התורה \u0003וחייבין עליו\u0004 מלקות אם אכלוהו. הגיד \u0003החיצון הסמוך לבשר — אסור\u0004 מדברי סופרים, ולכן \u0003אין חייבין עליו\u0004 מלקות. וממילא כיון שמן התורה הוא מותר — חל עליו איסור נותר, כשלא אכלוהו.","במשנה שנינו שאם \u0003חל ששה עשר\u0004 בשבת אין שריפת הנותר דוחה את השבת, אלא שורפים בשבעה עשר. ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 לא ישרפו את הנותר מן הפסח ביום החג עצמו? \u0003ניתי\u0004 \u0005[שתבוא\u0006 מצות\u0005]\u0006 \u0003עשה\u0004 של שריפה \"באש תשרפו\" \u0003וידחי\u0004 \u0005[ותדחה]\u0006 \u0003לא תעשה\u0004 של מלאכה ביום טוב!","\u0003אמר חזקיה, וכן תני דבי\u0004 \u0005[שנה\u0006 חכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה: אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ולא תותירו ממנו עד בקר והנותר ממנו עד בקר באש תשרפו\"\u0004 (שמות יב, י), \u0003שאין תלמוד לומר\u0004 ואין משמעות לחזרה על המילים \u0003\"עד בקר\"\u0004 בשנית, \u0003מה תלמוד לומר \"עד בקר\" — ליתן לו בקר שני לשריפתו.\u0004 ללמדנו שהמצוה לשרוף את הנותר מן הפסח אינה בבוקר הראשון שחל עליו האיסור, הוא בוקרו של יום החג, אלא בבוקר השני, ביום ששה עשר בניסן ומתוך שהוא שבת נדחית השריפה ליום שבעה עשר.","\u0003אביי אמר:\u0004 הטעם הוא ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"עלת שבת בשבתו\u0004 על עולת התמיד ונסכה\u0003\"\u0004 (במדבר כח, י), כלומר: עולת שבת מותר להקטירה על המזבח וכן לשורפה אם נפסלה בשבת אבל \u0003לא עולת חול בשבת ולא עולת חול ביום טוב\u0004 ומכאן למדים שאין שורפים בשבת דבר שאינו ממצוות היום.","\u0003רבא אמר\u0004 נימוק אחר: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 לגבי יום טוב: \u0003\"\u0004מקרא קודש יהיה לכם כל מלאכה לא יעשה בהם אך אשר יאכל לכל נפש \u0003הוא לבדו יעשה לכם\"\u0004 (שמות יב, טז) ומכאן מדייקים: \u0003\"הוא\"\u0004 הכוונה המאכל עצמו יעשה לכם \u0003ולא מכשיריו\u0004 שאסור להכין את המכשירים לצורך האוכל אלא מבעוד יום, \u0003\"לבדו\"\u0004 אף הוא מיעוט,"],["\u0003ולא מילה שלא בזמנה\u0004 שמשום טעם כלשהו לא נעשתה בזמנה ביום השמיני שאין יום טוב נדחה מפניה דווקא באותו יום משום שמשעבר היום השמיני שוב אין חובה לעשותה, וצריך להדגיש זאת משום שהיא \u0003באה מקל וחמר\u0004 (מצרעת) שמכוחו היינו סבורים כי מילה זו תדחה שבת ויום טוב, על כן בא הכתוב להדגיש שאינה דוחה יום טוב.","\u0003רב אשי אמר\u0004 טעם אחר: \u0003\"שבתון\"\u0004 האמור ב\u0003יום טוב\u0004 — מצות \u0003עשה הוא,\u0004 ואם כן יש ביום טוב גם מצות עשה של שביתה וגם מצות לא תעשה של מלאכה ולכן \u0003אין עשה\u0004 של שריפת נותר \u0003דוחה לא תעשה ועשה\u0004 שביום טוב.","\u0003כל\u0004 דבר \u0003הנאכל\u0004 (הראוי להיאכל) \u0003בשור הגדול\u0004 שהתקשו עצמותיו הרבה \u0003יאכל\u0004 אף \u0003בגדי הרך\u0004 ויוצא בו ידי הפסח ואף נמנים עליו, אבל דברים שאינם ראוים לאכילה בשור הגדול, שבגדי הרך עדיין אפשר לאכלם, מפני רכותו, אינם חשובים בשר ואין יוצאים בו ידי חובת הפסח ואין נמנים עליהם. וכן גם \u0003ראשי כנפים\u0004 (ראשי הצלעות הרכות) \u0003והסחוסים\u0004 שהם רכים וראוים לאכילה.","\u0003רבה רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 כאן\u0005]:\u0006 \u0003כל הנאכל בשור הגדול יאכל בגדי הרך\u0004 ומכאן ברור כי מה \u0003שאינו נאכל\u0004 בשור הגדול — \u0003לא\u0004 יאכל אף בגדי. \u0003אימא סיפא\u0004 \u0005[אמור את סוף\u0006 המשנה\u0005]\u0006 \u0003ראשי כנפים והסחוסים\u0004 נאכלים בגדי \u0003והא הני\u0004 \u0005[והרי אלה]\u0006 \u0003לא מתאכלי\u0004 \u0005[נאכלים]\u0006 \u0003בשור הגדול\u0004 שכבר התקשו כעצם, ואינם ראויים לאכילה!","\u0003אלא תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין זה, ושתי הדעות מצויות במשנתנו, \u0003והכי קתני\u0004 \u0005[וכך שנה,\u0006 כך יש לשנות\u0005]\u0006 את המשנה כדי לתת לה משמעות: \u0003כל הנאכל בשור הגדול — יאכל בגדי הרך, ושאינו נאכל — לא, ויש אומרים: אף ראשי כנפים והסחוסים\u0004 יאכלו בגדי הרך, כיון שלאחר בישול רב ראויים הם להיאכל אף בשור הגדול.","\u0003רבא אמר:\u0004 משנתנו בסגנון \u0003\"מה הן\" קתני\u0004 \u0005[שנה],\u0006 כלומר יש בה קודם קביעה כללית ואחר כך פירוט, \u0003והכי קתני\u0004 \u0005[וכך שנה]:\u0006 \u0003כל הנאכל בשור הגדול בשלקא\u0004 \u0005[בבישול]\u0006 \u0003יאכל בגדי הרך\u0004 על ידי \u0003צלי,\u0004 אף כי בשור הגדול אי אפשר לאכול חלק זה כשהוא צלוי. \u0003ומה הן\u0004 חלקים אלה — \u0003ראשי כנפים והסחוסים.\u0004","\u0003תניא כוותיה דרבא\u0004 \u0005[שנויה\u0006 ברייתא כשיטת \u0005רבא]:\u0006 \u0003כל הנאכל בשור הגדול בשלקא יאכל בגדי הרך בצלי, ומה הן — ראשי כנפים והסחוסים, וגידין הרכין נידונין כבשר.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בשאלה זו: \u0003גידין שסופן להקשות\u0004 ועדיין רכים הם עכשיו, \u0003ר' יוחנן אמר: נמנין עליהן בפסח, ריש לקיש אמר: אין נמנין עליהן בפסח.\u0004 ומפרשים: \u0003ר' יוחנן אמר: נמנין עליהן\u0004 בפסח כי \u0003בתר השתא אזלינן\u0004 \u0005[אחר\u0006 המצב \u0005עכשיו אנו הולכים],\u0006 וכיון שעכשיו ראויים הם לאכילה דינם כבשר. \u0003ריש לקיש אמר: אין נמנין עליהן\u0004 כי \u0003בתר בסוף אזלינן\u0004 \u0005[אחר\u0006 המצב \u0005בסוף אנו הולכים]\u0006 וסופם שאינם ראויים לאכילה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן,\u0004 שנינו: \u0003כל הנאכל בשור הגדול יאכל בגדי הרך, ומה הן — ראשי כנפים והסחוסים,\u0004 ונדייק: \u0003הני — אין\u0004 \u0005[אלה —\u0006 \u0005כן]\u0006 \u0003אבל גידין שסופן להקשות — לא,\u0004 שלא כשיטת ר' יוחנן! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תנא הני והוא הדין להנך\u0004 \u0005[שנה את אלו,\u0006 כנפיים וסחוסים, \u0005והוא הדין לאלה\u0006 הגידין\u0005].\u0006 כי \u0003הני מאי טעמא\u0004 \u0005[אלה\u0006 ראשי כנפים וסחוסים \u0005מה טעם]\u0006 נמנים עליהם — \u0003דהא מתאכלי\u0004 \u0005[שהרי נאכלים]\u0006 \u0003בשור הגדול בשלקא\u0004 \u0005[בבישול]\u0006 \u0003הנך נמי מתאכלי\u0004 \u0005[אלה\u0006 הגידים \u0005גם כן נאכלים]\u0006 \u0003בשור הגדול בשלקא\u0004 \u0005[בבישול],\u0006 וראויים לאכילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' אבין: כי אזלת לקמיה\u0004 \u0005[כאשר תלך לפני]\u0006 \u0003ר' אבהו רמי ליה\u0004 \u0005[הקשה לו,\u0006 הראה לפניו סתירה זו\u0005]:\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יוחנן: גידין שסופן להקשות נמנין עליהן בפסח, אלמא: בתר השתא אזלינן\u0004 \u0005[מכאן שאחר\u0006 המצב \u0005עכשיו אנו הולכים]\u0006 \u0003והא בעא מיניה\u0004 \u0005[והרי שאל ממנו]\u0006 \u0003ריש לקיש מר' יוחנן: עור הראש של עגל הרך\u0004 שעדיין הוא ראוי לאכילה, \u0003מהו שיטמא\u0004 טומאת אוכלין, האם רואים אנו אותו כעור או כבשר? \u0003ואמר לו: אין מטמא. אלמא:\u0004 \u0005[מכאן]\u0006 \u0003בתר בסוף אזלינן\u0004 \u0005[אחר\u0006 המצב \u0005בסוף אנו הולכים]\u0006 וסותרת איפוא שיטתו שם את שיטתו כאן!","כשבא ר' אבין לפני ר' אבהו ושאלו שאלה זו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דרמא לך הא\u0004 \u0005[\u0006זה \u0005שהקשה לך\u0006 קושיה \u0005זו] —\u0006 \u0003לא חש לקמחיה\u0004 \u0005[חשש לקמחו]\u0006 כלומר לדברים שהוא מוציא מפיו. \u0003הא הדר ביה\u0004 \u0005[הרי חזר בו]\u0006 \u0003ר' יוחנן\u0004 בענין זה \u0003לגבי\u0004 \u0005[אצל]\u0006 שיטת \u0003ריש לקיש. ואמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לאחר משא ומתן שהיה ביניהם: \u0003אל תקניטני\u0004 להקשות עלי ממשנה המוכיחה לכאורה שהולכים אחר המצב הנוכחי \u0003שבלשון יחיד אני שונה אותה,\u0004 שאותה משנה שסמכתי עליה מתחילה דעת יחיד היא ואין לסמוך עליה, הרי זו ראיה ששינה ר' יוחנן את דעתו והחליט שקובעים לפי מצב הדברים בסוף, ודעתו שהוזכרה בענין פסח היתה עדיין טרם חזרתו בו.","\u0003השובר את העצם בפסח הטהור — הרי זה לוקה ארבעים\u0004 מלקות על שעבר על מצות לא תעשה האמורה בתורה. \u0003אבל המותיר\u0004 מן הפסח ה\u0003טהור\u0004 או \u0003השובר\u0004 עצם בפסח ה\u0003טמא — אינו לוקה את הארבעים.\u0004","בגמרא דנים בדינים שבמשנה: ב\u0003שלמא\u0004 [נניח] \u0003מותיר בטהור\u0004 שאינו לוקה אף שעבר על דברי תורה — יש לכך הסבר, \u0003דתניא\u0004 [שכן שנינו בברייתא] על הנאמר בכתוב: \u0003\"ולא תותירו ממנו עד בקר והנתר ממנו עד בקר\u0004 באש תשרופו\u0003\"\u0004 (שמות יב, י) — \u0003בא הכתוב ליתן\u0004 מצות \u0003עשה\u0004 של שריפה \u0003אחר\u0004 מצות \u0003לא תעשה\u0004 של \"לא תותירו\" \u0003לומר שאין לוקה,\u0004 שכל לאו שנמצא בו גם תיקון (ניתק\") למעשה הלאו על ידי מצות עשה — אין לוקין עליו, אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' יעקב אומר: לא מן השם הוא זה\u0004 כלומר, לא זה טעמו של הדין \u0003אלא משום דהוה ליה\u0004 \u0005[שהינו]\u0006 \u0003לאו שאין בו מעשה.\u0004 שהרי המותיר אינו עושה מעשה, אלא רק נמנע מאכילה, ומצות לא תעשה שאין בה עשייה \u0003אין לוקין עליו,\u0004 ובכן יש לדין זה טעם. \u0003אלא שובר בטמא מנלן\u0004 \u0005[מנין לנו]\u0006 שאין לוקים עליו? ומשיבים: מקור הדבר הוא ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"\u0004בבית אחד יאכל לא תוציא מן הבית מן הבשר חוצה \u0003ועצם לא תשברו בו\"\u0004 (שמות יב, מו). ונדייק: \u0003\"בו\"\u0004 כוונתו \u0003ב\u0004פסח ה\u0003כשר ולא בפסול.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 באותו ענין \u0003\"ועצם לא תשברו בו\"\u0004 ומדייקים: \u0003\"בו\" — בכשר ולא בפסול. רבי אומר:\u0004 כך יש ללמוד הלכה זו: נאמר, \u0003\"בבית אחד יאכל\"\u0004 ובסמוך לו נאמר: \u0003\"ועצם לא תשברו בו\"\u0004 לומר: \u0003כל\u0004 פסח \u0003הראוי לאכילה — יש בו משום שבירת עצם, ושאין ראוי לאכילה אין בו משום שבירת עצם.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם למעשה]?\u0006 שאמנם נחלקו לענין מקור ההלכה, אך מה ההבדל ביניהם מבחינת המסקנות המעשיות? \u0003אמר ר' ירמיה: פסח הבא בטומאה\u0004 שכל ישראל אוכלים ממנו בטומאה \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005].\u0006 \u0003ל\u0004דעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ומדייק מלשון הפסוק שרק בפסח ה\u0003כשר\u0004 יש איסור שבירת עצם"],["\u0003האי\u0004 \u0005[זה]\u0006 \u0003פסול\u0004 הוא ושבירה מותרת בו. ואילו \u0003ל\u0004דעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ודייק מלשון הכתוב שהכל תלוי אם פסח \u0003ראוי לאכילה — האי נמי\u0004 \u0005[זה גם כן]\u0006 הפסח הבא בטומאה \u0003ראוי לאכילה הוא\u0004 ואסור אף בשבירה.","\u0003רב יוסף אמר: כי האי גוונא\u0004 \u0005[כגון זה]\u0006 פסח הבא בטומאה — \u0003דכולי עלמא\u0004 \u0005[ל\u0006דעת \u0005הכל]\u0006 \u0003אין בו משום\u0004 איסור \u0003שבירת העצם,\u0004 כי \u0003רבי לאקולי קא אתי\u0004 \u0005[להקל בא]\u0006 \u0003והאי הא פסול הוא\u0004 \u0005[ו\u0006פסח \u0005זה\u0006 שבא בטומאה \u0005הרי פסול הוא]\u0006 אף שגזירת הכתוב שעולה לרצון.","\u0003אלא\u0004 לענין פסח ש\u0003היתה לו שעת הכושר\u0004 (שעה שהיה כשר בה) \u0003ונפסל\u0004 לאחר מכן, \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאמר]\u0006 ודייק מהפסוק שדווקא פסח אסור בשבירה \u0003כשר — הא\u0004 \u0005[הרי]\u0006 \u0003כשר הוא\u0004 פסח זה. \u0003ל\u0004דעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ודייק מהפסוק שצריך הפסח להיות \u0003ראוי לאכילה הרי השתא\u0004 \u0005[עכשיו]\u0006 \u0003לאו\u0004 \u0005[אינו]\u0006 \u0003ראוי לאכילה.\u0004","\u0003אביי אמר: כולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003כל כי האי גוונא\u0004 \u0005[כגון זה]\u0006 \u0003אין בו משום\u0004 איסור \u0003שבירת העצם, מאי טעמא השתא מיהת הא פסול הוא\u0004 \u0005[עכשיו מכל מקום פסול הוא]\u0006 \u0003אלא\u0004 בדין \u0003שבירת העצם מבעוד יום\u0004 לפני זמן אכילתו \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005].\u0006 \u0003ל\u0004דעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ודייק מהפסוק שדווקא \u0003כשר\u0004 אסור בשבירה \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כשר הוא,\u0004 ואילו \u0003ל\u0004דעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר ראוי לאכילה\u0004 על כל פנים \u0003השתא\u0004 \u0005[עכשיו]\u0006 לפני שהגיע הלילה — \u0003לאו בר אכילה הוא\u0004 \u0005[אינו ראוי לאכילה],\u0006","\u0003מיתיבי\u0004 \u0005[מקשים],\u0006 \u0003רבי אומר: נמנין\u0004 באכילת הפסח \u0003על מוח שבראש ואין נמנין\u0004 לאכילה \u0003על מוח שבקולית\u0004 (עצם הירך). ונברר: \u0003על מוח שבראש מאי טעמא\u0004 \u0005[מה טעם]\u0006 נמנים — \u0003הואיל ויכול לגוררו\u0004 ממקומו \u0003ולהוציאו\u0004 בלא לשבור עצם מן הקרבן מה שאין כן במוח שבקולית. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003שבירת העצם מבעוד יום שפיר דמי\u0004 \u0005[יפה\u0006 וראוי \u0005הוא]\u0006 לשיטת רבי \u0003קולית נמי נתבריה\u0004 \u0005[גם כן נשברנה]\u0006 \u0003מבעוד יום ונפקוה למוח דידיה ונמנו עליה\u0004 \u0005[ויוציאו את המוח שלה\u0006 ממנה \u0005וימנו עליה]\u0006","\u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003אביי: ולטעמיך\u0004 \u0005[ולשיטתך]\u0006 ולדעתך, כפי שאתה מבין זאת, \u0003משחשיכה נמי\u0004 \u0005[גם כן]\u0006 יש דרך לאכול את המוח שבקולית: \u0003נייתי גומרתא וניחות עליה ונקלה ונפקה למוח דידיה ונימני עליה\u0004 \u0005[נביא גחלת ונניח עליה\u0006 את העצם \u0005ונשרוף אותה ונוציא את המוח שלה\u0006 ממנה \u0005ונמנה עליו]\u0006 \u0003דהא תניא\u0004 \u0005[שהרי שנויה\u0006 ברייתא\u0005]\u0006 במפורש: \u0003אבל השורף בעצמות\u0004 הפסח או \u0003המחתך בגידין — אין בו\u0004 איסור \u0003משום\u0004 איסור \u0003שבירת העצם.\u0004 ובודאי לא אלה היו הטעמים.","\u0003אלא מאי אית לך למימר\u0004 \u0005[אלא מה יש לך לומר]\u0006 ולהסביר מפני מה אין מוציאים את המוח מן הקולית על ידי שריפה — \u0003אביי אמר: משום פקע\u0004 שמא מחמת החום תתפוצץ העצם במקום שאינו מונח על הגחלת ונמצא עובר על שבירתה, \u0003רבא אמר: משום הפסד קדשים, דקא מפסיד ליה בידים\u0004 \u0005[שהוא מפסיד\u0006 מקלקל, \u0005אותה בידים\u0006 בעשייה בפועל\u0005],\u0006 ומדוע — \u0003דילמא אכיל נורא ממוח דידיה\u0004 \u0005[שמא תאכל האש מן המוח שבו]\u0006 והוא הדין שאסורה שבירת עצם \u0003מבעוד יום נמי\u0004 \u0005[גם כן],\u0006 \u0003גזירה\u0004 מדברי סופרים \u0003מבעוד יום אטו\u0004 \u0005[משום]\u0006 \u0003משחשיכה.\u0004","\u0003רב פפא אמר: כל כי האי גוונא\u0004 \u0005[כל כגון זה]\u0006 \u0003כולי עלמא\u0004 \u0005[ל\u0006דעת \u0005הכל]\u0006 \u0003יש בו משום שבירת העצם. מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של דבר שהרי \u0003לאורתא מיחזי לאכילה\u0004 \u0005[לערב ראוי לאכילה]\u0006 \u0003אלא באבר שיצא מקצתו\u0004 מחוץ למקום שמותר לאכלו, ונפסל על ידי כך ורצונו בשל כך לחותכו \u0003קמיפלגי\u0004 \u0005[נחלקו].\u0006 \u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 ודייק מהפסוק שדווקא \u0003כשר\u0004 אסור בשבירה \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כשר הוא\u0004 ואסור לשבור בו עצם, \u0003ו\u0004לדעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ודייק מהפסוק שדווקא \u0003ראוי לאכילה — האי לאו בר אכילה הוא\u0004 \u0005[הרי זה אינו בן אכילה]\u0006 ומותרת בו שבירת עצם.","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: אבר שיצא מקצתו ושברו — אין בו משום\u0004 איסור \u0003שבירת העצם\u0004 כדעה זו שאמרנו שכיון שאינו ראוי לאכילה — אין בו איסור שבירה.","\u0003רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר: כל כי האי גוונא דכולי עלמא\u0004 \u0005[כל כגון זה\u0006 לדעת \u0005הכל]\u0006 \u0003אין בו משום\u0004 איסור \u0003שבירת העצם, דהאי אבר הא פסול הוא\u0004 \u0005[שאבר זה הרי פסול הוא]\u0006 ולא רק בלתי ראוי לאכילה. \u0003אלא שבירת העצם\u0004 בפסח שאינו צלוי לגמרי \u0003ועודנו נא איכא בינייהו\u0004 \u0005[יש ביניהם].\u0006 לדעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ודייק מהפסוק שדווקא \u0003כשר\u0004 אסור בשבירה \u0005—\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כשר הוא\u0004 ואסורה בו שבירת עצם, \u0003ו\u0004לדעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ודייק מהפסוק שצריך הפסח להיות \u0003ראוי לאכילה — השתא\u0004 \u0005[עכשיו]\u0006 \u0003אינו ראוי לאכילה\u0004 עד שתגמר צלייתו ולכך לא נאסרה בו שבירת עצם.","\u0003רב נחמן בר יצחק אמר: כל כי האי גוונא\u0004 \u0005[כל כעין זה]\u0006 \u0003יש בו משום שבירת העצם, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003דהא חזי לאכילה\u0004 \u0005[שהרי הוא ראוי לאכילה]\u0006 \u0003דמטוי ליה ואכיל ליה\u0004 \u0005[שהוא\u0006 מוסיף \u0005וצולה אותו ואוכל אותו]\u0006 \u0003אלא שבירת\u0004 העצם ב\u0003אליה איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 \u0003למאן דאמר\u0004 שצריך שיהא \u0003כשר — הא\u0004 \u0005[הרי]\u0006 \u0003כשר הוא\u0004 בודאי ואסורה בו השבירה, \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאמר]\u0006 \u0003ראוי לאכילה, האי\u0004 \u0005[זה]\u0006 \u0003אינו ראוי לאכילה\u0004 מכיון \u0003דאליה לגבוה סלקא\u0004 \u0005[שהאליה לגבוה\u0006 לקרבן, \u0005היא עולה]\u0006 ולא נאסרה בה שבירת עצם.","\u0003רב אשי אמר: כל כי האי גוונא\u0004 \u0005[כל כעין זה]\u0006 \u0003ודאי אין בו משום שבירת העצם, דהא\u0004 \u0005[שהרי]\u0006 \u0003ודאי\u0004 שום חלק מן האליה \u0003אינו ראוי לאכילה כלל. אלא\u0004 נחלקו בדין \u0003אבר שאין עליו כזית בשר. ל\u0004דעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ודייק מהפסוק שדווקא \u0003כשר\u0004 אסור בשבירה — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כשר הוא\u0004 ואסור לשבור בו עצם, \u0003ל\u0004דעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר ראוי לאכילה — בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהא \u0003שיעור אכילה\u0004 שהוא כזית לפחות \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 ולכן אין בו איסור שבירה.","\u0003רבינא אמר: כל כי האי גוונא\u0004 \u0005[כל כגון זה]\u0006 ודאי \u0003לית ביה\u0004 \u0005[אין בו]\u0006 \u0003משום שבירת העצם, דבעינן\u0004 \u0005[שצריכים אנו]\u0006 לכל הדעות שיהא \u0003שיעור אכילה. אלא\u0004 נחלקו בדין \u0003אבר שאין עליו כזית בשר במקום זה\u0004 שבו הוא שוברו \u0003ויש עליו כזית בשר במקום אחר. ל\u0004דעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ודייק מהפסוק שצריך הפסח להיות \u0003כשר, הא\u0004 \u0005[הרי]\u0006 \u0003כשר הוא\u0004 זה ואסור לשבור בו עצם כלל. \u0003ל\u0004דעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר ראוי לאכילה, בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003שיעור אכילה במקום שבירה, והא ליכא\u0004 \u0005[והרי אין כאן]\u0006 ולכך מותרת בו שבירת העצם.","ומעירים: \u0003תניא כארבעה מינייהו\u0004 \u0005[שנויה\u0006 ברייתא \u0005כארבעה מהם]\u0006 כארבע משיטות ההסבר שנמנו. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003רבי אומר:\u0004 נאמר \u0003\"בבית אחד יאכל... ועצם לא תשברו בו\"\u0004 (שמות יב, מו), ללמדנו: \u0003על\u0004 הפסח \u0003הכשר הוא חייב ואינו חייב על הפסול.\u0004","\u0003היתה לו שעת הכושר\u0004 (שעה שהיה כשר בה) \u0003ונפסל בשעת אכילה אין בו משום שבירת עצם\u0004 (כהסבר רב יוסף).","\u0003יש בו שיעור אכילה — יש בו משום שבירת העצם, אין בו שיעור אכילה — אין בו משום שבירת עצם\u0004 (כרב אשי או רבינא).","\u0003הראוי למזבח\u0004 (למעט אליה שאינה ראויה למזבח) \u0003אין בו משום שבירת עצם\u0004 (כשיטת ר' נחמן בר יצחק).","\u0003בשעת אכילה יש בו משום שבירת עצם שלא בשעת אכילה אין בו משום שבירת עצם\u0004 (שיטת אביי). הרי שנינו במפורש ככמה דעות באותה ברייתא.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה זו: \u0003אבר שאין עליו כזית בשר במקום זה\u0004 שבו הוא שוברו \u0003ויש עליו כזית בשר במקום אחר,\u0004 מה דינו לענין שבירת עצם? \u0003ר' יוחנן אמר: יש בו משום\u0004 איסור \u0003שבירת העצם, ר' שמעון בן לקיש אמר: אין בו משום\u0004 איסור \u0003שבירת עצם.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לר' שמעון בן לקיש:\u0004 נאמר \u0003\"ועצם לא תשברו בו\" — אחד עצם שיש עליו כזית בשר ואחד עצם שאין עליו כזית בשר, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אין עליו כזית בשר? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003אין עליו כזית בשר כלל\u0004 — אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003יש בו משום\u0004 איסור \u0003שבירת העצם?\u0004 הרי אינו ראוי לאכילה כלל! \u0003אלא לאו הכי קאמר\u0004 \u0005[האם לא כך אמר]\u0006 וכך יש לתקן: \u0003אחד עצם שיש עליו כזית בשר במקום זה ואחד שאין עליו כזית בשר\u0004 שנאסרה שבירתה, \u0003במקום זה ויש עליו כזית בשר במקום אחר,\u0004 ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מסקנה זו \u0003לר' שמעון בן לקיש!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006"],["\u0003לא\u0004 כך הכוונה, אלא \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003אחד עצם שיש עליו כזית בשר מבחוץ ואחד עצם שאין עליו כזית בשר מבחוץ\u0004 אבל \u0003יש עליו כזית בשר\u0004 (מוח העצם) \u0003מבפנים במקום שבירה\u0004 במקום שבו שוברים שנאסרה שבירתה.","ומעירים: \u0003והתניא\u0004 \u0005[וכן\u0006 אכן \u0005שנינו]\u0006 על הנאמר בכתוב: \u0003\"ועצם לא תשברו בו\"\u0004 (שמות יב, מו) — \u0003אחד עצם שיש בו מוח ואחד עצם שאין בו מוח\u0004 ואם כן \u0003ומה אני מקיים\u0004 במצות עשה של \u0003\"ואכלו את הבשר בלילה הזה\"\u0004 (שמות יב, ח) — דווקא \u0003בבשר שעל גבי העצם.\u0004","ודנים באותו מדרש הלכה: \u0003או אינו אלא\u0004 שחלה מצות אכילת הפסח גם \u0003בבשר שבתוך העצם\u0004 (מוח העצם), \u0003ומה אני מקיים \"ועצם לא תשברו בו\"\u0004 — דווקא \u0003בעצם שאין בו מוח, אבל בעצם שיש בו מוח — שובר\u0004 מלכתחילה \u0003ואוכל. ואל תתמה\u0004 שמותר לעבור כך על איסור שבתורה, \u0003שהרי\u0004 אפשר לומר: \u0003יבא עשה\u0004 של אכילת הבשר \u0003וידחה לא תעשה\u0004 של שבירת העצם, לפי הכלל שמצות עשה דוחה את לא תעשה,","אבל \u0003כשהוא אומר\u0004 \"לא ישאירו ממנו עד בוקר \u0003ועצם לא ישברו בו\u0004 ככל חוקת הפסח יעשו אותו\" (במדבר ט, יב) האמור \u0003בפסח שני, שאין תלמוד לומר\u0004 בחזרה על איסור זה לגופו \u0003שהרי כבר נאמר \"ככל חקת הפסח יעשו אתו\"\u0004 ונכלל בכך גם איסור שבירת העצם, \u0003הוי אומר\u0004 שבאה חזרה זו להדגיש את האיסור ולומר \u0003אחד עצם שיש בו מוח ואחד עצם שאין בו מוח\u0004 אסורים בשבירה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003אבר שיצא מקצתו\u0004 מחוץ לתחום המותר ונפסל על ידי כך, \u0003חותך\u0004 את הבשר שיצא \u0003עד מקום שמגיע לעצם\u0004 שבאבר זה \u0003וקולף\u0004 את שאר הבשר \u0003עד שמגיע לפרק\u0004 הקרוב \u0003וחותך\u0004 ומשליך את העצם ואוכל את הבשר,","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003אבר שאין עליו כזית בשר במקום זה ויש\u0004 עליו \u0003במקום אחר אין בו משום\u0004 איסור \u0003שבירת העצם,\u0004 אם כן \u0003למה לי\u0004 שיהא \u0003קולף עד שמגיע לפרק וחותך? נקלוף ביה פורתא ונתבריה\u0004 \u0005[נקלוף ממנו\u0006 מעליו את הבשר הנוגע בו \u0005ונשברנו]\u0006 שהרי אין בשר במקום השבירה!","\u0003אביי אמר:\u0004 אין עושים זאת \u0003משום פקע,\u0004 שמא תיפקע כתוצאה מכך כל העצם אף במקום בשר. \u0003רבינא אמר:\u0004 מדובר כאן \u0003בקולית\u0004 (עצם הירך) שיש מוח מרובה בתוכה ולא די בקילופה.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003הפיגול והנותר... מטמאין את הידים\u0004 מדברי סופרים אף שבתורה לא נאמרה בהם טומאה. ובטעם הדבר נחלקו \u0003רב הונא ורב חסדא. חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר:\u0004 הטעם הוא \u0003מפני חשדי כהונה\u0004 הכהנים החשודים לקלקל במזיד, שמתוך שנאה לבעל הקרבן יבואו לפגל את קרבנו ולכן גזרו על הפיגול, שיטמא מיד את ידי הכהן העושה קרבן זה, ויהא זה לו לקנס. \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר:\u0004 הטעם הוא \u0003מפני עצלי כהונה\u0004 שלא יבואו להתרשל ולהשאיר בשר קרבן מבלי שיאכלוהו.","ומסבירים בעצם לא נחלקו, אלא \u0003מר מתני אפיגול, ומר מתני אנותר\u0004 \u0005[חכם זה שונה\u0006 את טעמו \u0005על\u0006 טומאת \u0005פיגול וחכם זה שונה על\u0006 טומאת \u0005נותר].\u0006 \u0003מאן דמתני אפיגול\u0004 \u0005[מי ששונה על פיגול]\u0006 טעמו \u0003משום חשדי כהונה\u0004 שלא יבואו לפגל במזיד, שאין פיגול נעשה אלא על ידי כוונה תחילה. \u0003ומאן דמתני אנותר\u0004 \u0005[ומי ששונה על נותר]\u0006 טעמו \u0003משום עצלי כהונה,\u0004 שלא יאכלו את הזבח,","\u0003מר מתני\u0004 \u0005[חכם\u0006 אחד \u0005היה שונה]\u0006 שטומאה זו חלה על בשר ששיעורו \u0003כזית, ומר מתני\u0004 \u0005[וחכם\u0006 זה \u0005שונה]\u0006 ששיעורו \u0003כביצה.\u0004 ומסבירים: \u0003מאן דמתני\u0004 \u0005[מי ששונה]\u0006 \u0003כזית\u0004 — טעמו ששיעור טומאתו כשיעור \u0003איסורו,\u0004 שאיסור אכילה בפיגול הוא בכזית וכן הדין אף בנותר. \u0003ומאן דמתני\u0004 \u0005[ומי ששונה]\u0006 \u0003כביצה\u0004 טעמו שטומאת בשר פיגול ונותר כדין \u0003טומאתו\u0004 של בשר בכלל ושיעור טומאת אוכלין מן התורה — כביצה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 בהמשך לדברים אלו: בשר קודש \u0003היוצא\u0004 מן התחום הראוי לו האם \u0003גזרו רבנן טומאה\u0004 עליו \u0003או לא? מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003נותר\u0004 ש\u0003גזרו\u0004 בו \u0003טומאה\u0004 יש טעם בדבר \u0003דאתי לאיעצולי ביה\u0004 \u0005[שיבואו להתעצל בו]\u0006 ולא לאכלו, \u0003אבל יוצא\u0004 אין לחשוש לכך, כי \u0003אפוקי\u0004 \u0005[להוציא]\u0006 בפועל \u0003בידים לא מפקי לה\u0004 \u0005[מוציאים אותו]\u0006 \u0003בידים\u0004 לעשות בו מעשה לפסלו, וכיון שאין לחשוש לכך \u0003לא גזרו ביה רבנן\u0004 \u0005[בו חכמים]\u0006 \u0003טומאה, או דילמא\u0004 \u0005[שמא]\u0006 נאמר \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 שבכל קודש שנפסל גזרו חכמים טומאה להוסיף זהירות למתעסקים בו.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון לשאלה זו. ששנינו: \u0003אבר שיצא מקצתו חותך עד שמגיע לעצם, וקולף עד שמגיע לפרק\u0004 הקרוב \u0003וחותך, ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003גזרו ביה רבנן טומאה\u0004 \u0005[גזרו בו חכמים טומאה]\u0006 ביוצא, \u0003כי חתיך ליה מאי הוי\u0004 \u0005[כאשר חותך אותו מה יהיה]\u0006 ומה יוסיף התיקון בדבר זה \u0003הא קמטמא ליה\u0004 \u0005[הריהו מטמא אותו]\u0006 שהחלק שיצא ונטמא על ידי כך מטמא במגעו את האבר שלא יצא.","ומשיבים: \u0003טומאת סתרים היא\u0004 שהרי החלק שיצא מטמא את החלק האחר על ידי חיבורו בפנים, בתוך העצם שהוא מקום שאינו גלוי לעין, וכלל הוא ש\u0003טומאת סתרים לא מטמיא\u0004 \u0005[אינה מטמאה].\u0006","ושואלים: ולשיטת \u0003רבינא\u0004 ש\u0003אמר: חיבורי אוכלין לאו חיבור הוא\u0004 שכיון שעשויים להפרד אינם נחשבים כמחוברים \u0003וכמאן דמפרתי דמי\u0004 \u0005[וכמי שהיו מופרדים\u0006 זה מזה \u0005נחשבים]\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003הא קנגע בהדדי וקא מטמא\u0004 \u0005[הרי נוגעים זה בזה ומטמא]!\u0006 \u0003אלא\u0004 לשיטתו יש לפרש כך: \u0003למאן דמתני כזית\u0004 \u0005[למי ששונה\u0006 שטומאה זו היא \u0005בכזית]\u0006 סבור שמדובר באבר \u0003דלית ביה כזית\u0004 \u0005[שאין בו כזית]\u0006 שיוכל לטמא. \u0003ומאן דמתני כביצה\u0004 \u0005[ומי ששונה כביצה]\u0006 סבור שמדובר באבר \u0003דלית ביה\u0004 \u0005[שאין בו]\u0006 שיעור כביצה.","ועוד מציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה אחרת. שנינו: \u0003המוציא בשר פסח מחבורה לחבורה אף על פי שהוא בלא תעשה\u0004 שהרי אסרה התורה לאוכלו מחוץ למקום שהוא נאכל בו, בכל זאת \u0003טהור.\u0004 ונברר: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה הוא \u0003טהור\u0004 משום טומאה אבל \u0003אסור\u0004 משום שפסח ה\u0003יוצא מחבורה לחבורה כ\u0004דין קודש ה\u0003יוצא חוץ למחיצתו דמי\u0004 \u0005[נחשב]\u0006 \u0003ומפסיל\u0004 \u0005[ונפסל],\u0006 \u0003ואפילו הכי קתני\u0004 \u0005[כך שנינו]\u0006 \u0003טהור, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003לא גזרו רבנן\u0004 \u0005[חכמים]\u0006 \u0003טומאה\u0004 ביוצא!","ודוחים: \u0003לא\u0004 כך יש להבין שם אלא \u0003טהור ומותר,\u0004 כי \u0003יוצא מחבורה לחבורה לאו\u0004 \u0005[לא]\u0006 \u0003כיוצא חוץ למחיצתו דמי\u0004 \u0005[נחשב]\u0006 \u0003ולא מפסיל\u0004 \u0005[נפסל]\u0006","ומקשים: \u0003והא קא תני סיפא\u0004 \u0005[והרי שנינו בסוף]\u0006 הברייתא: \u0003האוכלו\u0004 את הפסח שיצא מחבורתו \u0003הרי זה בלא תעשה! בשלמא למאן דאמר כביצה\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאמר\u0006 שטומאתו \u0005כביצה]\u0006 הרי מדובר כאן בבשר \u0003דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003כזית ולית ביה\u0004 \u0005[ואין בו]\u0006 \u0003כביצה\u0004 ולכן האוכלו חייב, שהאיסור חל משעה שאוכל כזית אבל טומאה אין בו, לפי שאין בו שיעור המטמא, \u0003אלא למאן\u0004 \u0005[למי]\u0006 ש\u0003אמר\u0004 שטומאה שגזרו חכמים היא \u0003כזית, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אלא\u0004 נחזור מדחיות קודמות ונאמר: \u0003ביוצא בפסח לא מיבעיא לן\u0004 \u0005[נסתפק לנו]\u0006 ש\u0003לא גזרו רבנן\u0004 \u0005[חכמים]\u0006 \u0003טומאה\u0004 עליו, \u0003מאי טעמא\u0004 \u0005[מה טעמו\u0006 של דבר\u0005]\u0006 — \u0003בני חבורה זריזין הן ומזהר זהירי ביה\u0004 \u0005[ונזהרים בו]\u0006 הרבה בשמירתו שלא ייצא חוץ למקומו, ואין מקום לקנסם. \u0003אלא, כי קא מיבעיא לן\u0004 \u0005[כאשר נשאלה לנו\u0006 השאלה\u0005]\u0006 היה זה \u0003ביוצא\u0004 בשאר \u0003קדשים, מאי\u0004 \u0005[מה\u0006 דינו\u0005],\u0006 לשאלה זו לא נמצאה תשובה, והושארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","לגוף הנושא שואלים: \u0003ומוציא בשר פסח\u0004"],["\u0003מחבורה לחבורה מנין\u0004 שנפסל? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 על הכתוב: \u0003\"\u0004בבית אחד יאכל \u0003לא תוציא מן הבית מן הבשר חוצה\"\u0004 (שמות יב, מו), \u0003אין לי\u0004 איסור \u0003אלא\u0004 למוציא \u0003מבית לבית,\u0004 המוציא \u0003מחבורה לחבורה\u0004 אפילו היו באותו בית, \u0003מנין\u0004 שהוא אסור? \u0003תלמוד לומר: \"חוצה\"\u0004 והכוונה: \u0003חוץ\u0004 למקום \u0003אכילתו.\u0004","\u0003אמר ר' אמי: המוציא בשר פסח מחבורה לחבורה אינו חייב עד שיניח\u0004 את הבשר במקום מושבה של החבורה השניה. וטעמו: \u0003\"הוצאה\" כתיב ביה\u0004 \u0005[כתובה בו]\u0006 (\"לא תוציא\") כמו שכתובה בדיני \u0003שבת, מה\u0004 בדיני \u0003שבת\u0004 אינו חייב על הוצאה \u0003עד דעבד\u0004 \u0005[שעושה]\u0006 \u0003עקירה\u0004 מרשות אחת \u0003והנחה\u0004 למקום אחר. \u0003אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 חייב רק לאחר \u0003עקירה\u0004 ממקום מושב חבורה אחת \u0003והנחה\u0004 במקום מושב השניה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' אבא בר ממל\u0004 מדין חטאות הפנימיות הנשרפות שהן מטמאות את המוציאים אותן לחוץ, ושנינו: \u0003היו סובלים\u0004 (נושאים) \u0003אותן במוטות,\u0004 אם \u0003הראשונים יצאו חוץ לחומת העזרה והאחרונים\u0004 עדיין \u0003לא יצאו\u0004 בכל זאת \u0003הראשונים מטמאין\u0004 מיד \u0003בגדים והאחרונים אין מטמאין בגדים\u0004 הרי שמיד עם היציאה נטמאים ויש לשאול: \u0003והא לא נח\u0004 \u0005[והרי לא נח]\u0006 הבשר בחוץ? ומדוע יחשב כיוצא!","\u0003הוא מותיב לה\u0004 \u0005[היה מקשה אותה]\u0006 את הקושיה הזו \u0003והוא מפרק לה\u0004 \u0005[מתרץ אותה],\u0006 שכאן מדובר \u0003בנגררין\u0004 על הקרקע שמיד שיצאו מן העזרה הרי הם כמונחים על הקרקע.","\u0003אבר שיצא מקצתו\u0004 מן התחום הראוי לו \u0003חותך\u0004 בבשר \u0003עד שמגיע לעצם, וקולף\u0004 את הבשר שעל העצם \u0003עד שמגיע לפרק\u0004 הקרוב \u0003וחותך\u0004 בפרק שהרי אסור לשבור עצם הפסח. ובשאר \u0003מוקדשין\u0004 שיצאו \u0003קוצץ בקופיץ\u0004 עד אותו מקום שיצא בו, שהרי \u0003אין בו משום\u0004 איסור \u0003שבירת העצם.\u0004 וכיצד קובעים את תחומו של מקום?","כל מה שנמצא \u0003מן האגף\u0004 (עומק, חלל הפתח) \u0003ולפנים\u0004 — דינו \u0003כלפנים, מן האגף ולחוץ — כלחוץ. החלונות\u0004 שבחומה \u0003ועובי החומה\u0004 עצמה — דינם \u0003כלפנים,\u0004 ואין קרוי יוצא אלא שיצא מחוץ לחומה כולה.","\u0003אמר רב יהודה אמר רב: וכן\u0004 הדין \u0003לתפלה,\u0004 שהעומד מחוץ לפתח אינו מצטרף עם המתפללים הנמצאים בפנים, ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דעת \u0003ר' יהושע בן לוי,\u0004 ש\u0003אמר ר' יהושע בן לוי: אפילו מחיצה של ברזל אינה מפסקת בין ישראל לאביהם שבשמים\u0004 ולענין תפילה אין כלל חשובות המחיצות.","על משנתנו תוהים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה],\u0006 שיש בה סתירה כאשר מדקדקים בה, תחילה \u0003אמרת מן האגף ולפנים כלפנים, הא\u0004 \u0005[הרי]\u0006 אם נדייק מכאן נבין כי חללו של \u0003אגף עצמו כלחוץ.\u0004 אולם, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003מן האגף ולחוץ — כלחוץ.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 נמצא שחלל \u0003אגף עצמו\u0004 — דינו \u0003כלפנים!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 ויש ליישב את הסתירה שאין הם דנים באותו נושא, \u0003כאן\u0004 בתחילת המשנה — מדובר \u0003בשערי עזרה\u0004 שבהם גם האגף עצמו כלפנים וקדוש בקדושת העזרה, \u0003כאן\u0004 בסופה של המשנה — מדובר \u0003בשערי ירושלים\u0004 שעובי חלל הפתח כלחוץ ואין בו מקדושת ירושלים.","ש\u0003אמר ר' שמואל בר רב יצחק: מפני מה לא נתקדשו\u0004 חללי \u0003שערי ירושלים\u0004 בתוך עוביים \u0003מפני שמצורעין מגינין\u0004 על עצמם ביושבם \u0003תחתיהן, בחמה —\u0004 כדי להגן \u0003מפני החמה, ובגשמים —\u0004 כדי להגן \u0003מפני הגשמים.\u0004 שהרי אסור למצורעים להכנס אל העיר ירושלים, והתקינו שתהא להם הגנה כל שהיא מפני החום והקור בתוך חללי השערים.","ובדומה לזה \u0003אמר ר' שמואל בר רב יצחק: מפני מה לא נתקדשה\u0004 חללו של \u0003שער נקנור\u0004 בקדושת העזרה? \u0003מפני שמצורעין\u0004 שנתרפאו וצריכים להביא קרבן טהרה \u0003עומדין שם ומכניסין בהונות ידם\u0004 כדי שיזו עליהם מדם הקרבן לטהרם. ולפי דרכנו למדנו ששאר שערי העזרה חללם נתקדש, ושערי ירושלים לא נתקדשו.","נאמר במשנה כי \u0003החלונות ועובי החומה\u0004 דינם כלפנים. \u0003אמר רב: גגין ועליות לא נתקדשו\u0004 ולכן הגגות שבעזרה אין להם קדושת עזרה, וגגות שבירושלים אין קדושתם כקדושת ירושלים. ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב משום\u0004 \u0005[בשם]\u0006 \u0003ר' חייא\u0004 בלשון פתגם: \u0003\"כזיתא פסחא, והלילא פקע איגרא\"\u0004 \u0005[הפסח\u0006 גודלו \u0005כזית, והלל שובר את הגג]\u0006 שהיו הרבים הנמנים על קרבן אחד ואין מגיע בחלוקת הבשר לכל אחד אלא כזית, אומרים הלל בקול גדול ודומה כי פוקעים הגגות מפני ההמולה, אף שהפסח שאומרים עליו הלל זה, שיעורו קטן ביותר,"]]};
